window.BIBLE = {"meta":{"title":"蜉蝣十洲志","subtitle":"MASTER NOVEL BIBLE","version":"V3.0","anchor":"愧我莫如霜上鹭，霎时飞去便飞还。","anchorFrom":"仇远《奉寄田上人》","logline":"百年前一桩冤案让三族反目；一百年后，三个被各自种族的偏见所伤的后裔，从三个方向查向同一个真相——而真相本身，正是“所有人都宁愿相信谎言”。","author":"闻颂 / ARIA","note":[]},"pian":[{"num":"一","title":"作品总纲","raw":"第一篇｜作品总纲","zh":[{"title":"01. 作品定位","sec":[{"title":"1.1 基本信息","blk":[{"t":"table","head":["项","内容"],"rows":[["书名","《蜉蝣十洲志》"],["类型","长篇小说 · 国风奇幻 · 多视角悬疑 · 世情群像"],["题材","三族分裂世界中的一桩百年冤案，与三个被偏见所伤的后裔"],["体例","六卷 / 约一百八十章 / 每卷三十章；章首引\"三族史书异文\""],["叙事","三线轮替 POV（鸣可 / 噬轲 / 巽宁）"],["篇幅预估","六卷 × 约 12 万字＝ 70 万字级"],["目标读者","20—35 岁国风奇幻与悬疑读者；偏好群像、考据、克制情感的成年读者；兼及影视与游戏改编市场"],["类型承诺","前三章给\"命案与异族世界\"，前三十章给\"三个视角三种真相\"，全书给\"偏见如何被制造，又为何难以拆除\""]]},{"t":"p","s":"书名释义："},{"t":"p","s":"蜉蝣——灵族经文中对凡族的蔑称与忌语，\"朝生暮死，不知潮汐\"。全书把它从一句骂人的话，翻回一句自况：三族都是蜉蝣，都在同一次呼吸里。"},{"t":"p","s":"十洲——地理的统称，也是\"分\"的象形：一块主岛裂成十份，各写各的史。"},{"t":"p","s":"志——方志体。志不抒情，只记事；而\"记什么、不记什么\"，就是全书最大的暴力。"}]},{"title":"1.2 一句话故事（Logline）","blk":[{"t":"p","s":"百年前一桩冤案让三族反目；一百年后，三个被各自种族的偏见所伤的后裔，从三个方向查向同一个真相——而真相本身，正是\"所有人都宁愿相信谎言\"。"},{"t":"p","s":"三个族，三本史书，三种说法。"},{"t":"p","s":"一个人族的蛊师、一个妖族的刺客、一个灵族的琴师，各自握着一块碎掉的真相。"},{"t":"p","s":"他们把碎片拼起来的时候，发现最不愿看见的人，是自己。"}]},{"title":"1.3 核心主题与主题锚句","blk":[{"t":"p","s":"锚句："},{"t":"p","s":"\"愧我莫如霜上鹭，霎时飞去便飞还。\"——仇远《奉寄田上人》"},{"t":"p","s":"锚句的三层用法："},{"t":"table","head":["意象","表层","深层","落点"],"rows":[["霜上鹭","三族如霜上之鹭，一有动静便各自飞散","\"愧\"字——每个人心里都知道自己参与了什么，只是不说","沈聿临刑不辩的那个\"愧\""],["霎时飞去","冤案一夜之间拆散三族百年共处","偏见的传播速度远快于事实","潮历一〇七年五月的流言"],["便飞还","三族终将重聚（不是和好，是重新住到一起）","飞回来的不是原来那只鹭","终卷通语新词\"回来\""]]},{"t":"p","s":"主题的三层结构：主题不是\"有人歧视别人\"，而是分三层，各由不同的叙事层承载。"},{"t":"table","head":["层次","内涵","全书载体"],"rows":[["第一层 · 认知偏见","未经接触就下的判断：\"妖族皆蛮荒\"\"灵族皆傲慢\"\"人族皆窃火\"","三族创世神话、NPC 的日常话术、章首三史异文"],["第二层 · 制度偏见","偏见被写成规矩：佩牌令、禁市令、通婚之禁、混血不立名","各洲洲规、律法条文、港口与城门的日常摩擦"],["第三层 · 既得利益","有人靠偏见吃饭，于是维护它","六大派系、氏老会、守档首座、牙人上层"]]},{"t":"p","s":"一句话立意：查案的过程，就是亲手拆掉这三层。真相不重要，\"为什么所有人宁愿相信谎言\"才重要。"}]},{"title":"1.4 世界观核心命题（三条）","blk":[{"t":"ol","items":["偏见不是错误信息，是秩序的成本。三族都需要一个敌人来维持内部团结——所以每十年衰潮一次，仇恨就被重新点一次火。没有主谋，只有惯性。"]},{"t":"ol","items":["证据能证明事实，不能证明人心。鸣可的整条弧线是这句话的正反两面：她靠证据活下来，最终学会在证据缺席处仍然相信人。"]},{"t":"ol","items":["真相不是终点，是新的分裂起点。终卷不合并史书，三份记述永久并立——叙事结构本身就是答案。"]}]},{"title":"1.5 叙事风格与文学气质","blk":[{"t":"p","s":"基调：志异其表，世情其里。世界是奇的（鲲鹏、器灵、影行、蜃市），人心是实的（讨价还价、赊账、怕丢脸、护孩子）。"},{"t":"p","s":"三条笔法原则："},{"t":"ol","items":["方志作骨，白描作肉。每卷开篇有一段\"志\"体（地理、风俗、律条），正文一律白描，短句，少形容词，情绪落在动作与物件上。"]},{"t":"ol","items":["世界观不许由作者解说。一切设定必须由人物\"用错的方式\"说出来——偏见的说法，就是最好的世界观说明书。"]},{"t":"ol","items":["克制的志异。术法写得像体力活：会疼、会累、会留后遗症。越奇的能力，代价越日常。"]},{"t":"p","s":"三个不许："},{"t":"p","s":"不许好人全对（沈聿的沉默是保护，也是共谋）；"},{"t":"p","s":"不许反派自认恶（韩朔认为自己守边，沈阶认为自己护史）；"},{"t":"p","s":"不许大团圆消解主题（终卷仍有人拒看档案）。"},{"t":"p","s":"意象系统（贯穿全书的七个物件）："},{"t":"table","head":["意象","首次出现","含义演变"],"rows":[["霜 / 鹭","卷一开篇","霜=短暂的共处；鹭=三族；飞还=重聚但不复原"],["桥","卷一·蜃市","桥=例外之地；\"过桥不问名\"=暂时放下身份"],["影","噬轲线","影=被否认的一半；影行=把自己拆开"],["空弦","巽宁线","空弦=被抹去的一记记录；也是唯一能被补全的"],["三尺","落珂境","三尺=灵族最大的恐惧，也是最大的谎"],["簿 / 档","证物线","簿=民间的记忆；档=官方的记忆"],["回来","终卷","通语百年新词：三族各有写法，读音相同"]]}]},{"title":"1.6 三线 POV 结构","blk":[{"t":"table","head":["线","POV","视角特权","视角盲区（情节发动机）"],"rows":[["人族线","鸣可（蛊师，17）","能\"撬开谎言\"（迷梦蜘），能验尸验毒验亲","只信证据，读不懂\"人心中的真话\""],["妖族线","噬轲（刺客，19）","能潜入、能影行、能进氏老会密库","他被世界遗忘（影行代价），查到的证词无人肯认"],["灵族线","巽宁（琴师，琴龄 87）","能听见\"被压住的那一音\"，能读档（冰弦玉版）","读不出\"深信偏见的真话\"；且她是替身，身份本身是假的"]]},{"t":"p","s":"POV 铁律："},{"t":"ol","items":["每章只写一个视角人物能感知的东西，不写全知。"]},{"t":"ol","items":["同一事件若三线都经历，必须写出三个不同版本，且三版都是\"该人物所见的真话\"——不是有人说谎，是三个人站的位置不同。"]},{"t":"ol","items":["每章结尾留一件\"未解之物\"（一个动作、一句话、一件东西），不给解释。"]},{"t":"ol","items":["三线在碧海洲蜃市交汇；交汇章节用\"第四种视角\"——唱证人的愿约簿（第三人称客观记录），全书仅三次。"]}]},{"title":"1.7 类型承诺与读者预期管理","blk":[{"t":"table","head":["读者的期待","本书如何回应"],"rows":[["想看\"异世界设定\"","十洲方志、洋流航程、三族生理与律法，硬设定可考据"],["想看\"悬疑解谜\"","三份密档、七件证物、六处大反转，线索全部前置可回查"],["想看\"人物情感\"","三主角各自弧线；沈聿×白芜的旧爱是全书的暖源"],["想看\"打脸爽感\"","不给。本书的\"爽\"是\"终于有人肯把话说完\""],["想看\"大团圆\"","半给。世界变好了一点，但有人始终不肯看"]]}]}]}]},{"num":"二","title":"世界起源与基础规则","raw":"第二篇｜世界起源与基础规则","zh":[{"title":"02. 世界观总论","sec":[{"title":"2.1 世界起源：鲲鹏与玄溟洋","blk":[{"t":"p","s":"作者层真相："},{"t":"p","s":"远古混沌中孕育出一股原初灵力。灵力渗入世间，世界重获生机。这股气息的源头，是一头永眠于玄溟洋底的巨兽——鲲鹏。它不动作，只呼吸；一次呼吸以万年计。它呼出的\"生的气息\"（羽粉）升腾、扩散、稀薄、下沉，形成世界的气脉，即灵脉。"},{"t":"p","s":"三族神话层（各自的第一支歌）："},{"t":"table","head":["族","经典","一句话","偏见如何写进创世"],"rows":[["人族","《拾穗书·羲和卷》","鲲鹏负天补漏，羽粉坠地，人族拾穗而稼穑","\"气息本分人族一半；坠于幽暗者为浊、为煞、为妖\"——拾穗的次序被写成血统的次序"],["妖族","《影翼谣》","鹏敛翼，天地暗，暗里生气生形，是为影裔","\"光拣剩的地方，影子来养\"——承认自己是暗生的，但坚持影子也是身"],["灵族","《落珂引》（琴曲经）","鹏化形栖为岛，羽尖坠光，光凝为灵","自认是\"光\"本身；凡族统称\"蜉蝣\"，说出口是忌语"]]},{"t":"p","s":"三则神话节引："},{"t":"p","s":"《拾穗书·羲和卷》：鸿蒙既判，天有巨漏，灵力外泄，万类将枯。鲲鹏负天而行，以翼蔽漏。羽粉簌簌而坠，是为\"生的气息\"。人族之先拾羽粉而稼穑，遂有五谷。故曰：气息本分人族一半；其坠于幽暗者，为浊，为煞，为妖——非我族类，拾穗之时未至也。"},{"t":"p","s":"《影翼谣》：鹏敛翼，天地暗。暗里有气，气里生形——是谓影裔。光拣剩的地方，影子来养。莫问影子为何凉，日头没照过的地方，都得自己生火。"},{"t":"p","s":"《落珂引》：鹏化形，栖为岛。岛即鹏，鹏即岛。羽尖坠光，光凝为灵。灵族者，鹏羽之光也。蜉蝣朝生暮死，不知潮汐；潮汐有时，蜉蝣自扰。慎言，慎言。"}]},{"title":"神话体系：一个鲲鹏，三种讲法","blk":[{"t":"p","s":"人族 ·《拾穗书·羲和卷》"},{"t":"p","s":"鸿蒙既判，天有巨漏，灵力外泄，万类将枯。鲲鹏负天而行，以翼蔽漏。羽粉簌簌而坠，是为\"生的气息\"。人族之先拾羽粉而稼穑，遂有五谷。故曰：气息本分人族一半；其坠于幽暗者，为浊，为煞，为妖——非我族类，拾穗之时未至也。"},{"t":"p","s":"→ 神话里就写着等级：人族是\"拾穗者\"，妖族是\"坠错的羽粉\"。偏见被写成了创世。"},{"t":"p","s":"妖族 ·《影翼谣》"},{"t":"p","s":"鹏敛翼，天地暗。暗里有气，气里生形——是谓影裔。光拣剩的地方，影子来养。莫问影子为何凉，日头没照过的地方，都得自己生火。"},{"t":"p","s":"→ 妖族不否认自己是\"暗\"生的，但他们说：影子也是身。《影翼谣》的末句在幽都传唱时，总要多唱一遍——那是唱给混血的孩子听的。"},{"t":"p","s":"灵族 ·《落珂引》（琴曲经）"},{"t":"p","s":"鹏化形，栖为岛。岛即鹏，鹏即岛。羽尖坠光，光凝为灵。灵族者，鹏羽之光也。蜉蝣朝生暮死，不知潮汐；潮汐有时，蜉蝣自扰。慎言，慎言。"},{"t":"p","s":"→ 灵族经文里\"蜉蝣\"是凡族的统称，且是忌语——说出口要抚琴一礼压一压。他们自认是\"光\"本身，凡族的百年，不过是他们的一次呼吸。"}]},{"title":"2.2 鲲鹏本体及其存在方式【待确认】","blk":[{"t":"p","s":"鹏是实体，永眠于洋底，以万年为呼吸。凡人只见\"影、羽、息\"三征，从不见其形。世界需要一个不可证的信仰，这正是偏见得以栖身的空穴。"},{"t":"p","s":"影：落珂境之影即鹏影（岛影随潮偏转，与日影不合，是唯一\"物证\"）；"},{"t":"p","s":"羽：极偶然的\"羽落\"——一枚巨大的羽状冰晶沉入海底，可遇不可求；"},{"t":"p","s":"息：潮汐本身。"},{"t":"p","s":"鲲鹏不得现身、不得说话、不得成为最终解谜的\"神迹\"。"},{"t":"p","s":"它是尺度，不是角色。"},{"t":"p","s":"\"全陆同听\"的潮鸣。"}]},{"title":"2.3 灵力、煞气与潮汐（世界引擎）","blk":[{"t":"p","s":"定义："},{"t":"p","s":"灵力＝鲲鹏呼出的\"生的气息\"在高浓度区的形态，可被引、可被储、可被\"借\"。"},{"t":"p","s":"煞气＝灵力被抽走或自然稀薄后，地气留下的\"空穴\"所纳之物。煞不是入侵者，是空出来的位置。"},{"t":"p","s":"潮汐＝鲲鹏的呼吸节律，即世界的心跳：涨潮（盈）、平潮、衰潮（滞）。"},{"t":"p","s":"四条机制（全书所有术法、政治、灾难的物质基础）："},{"t":"ol","items":["灵脉水位可测：以\"涸尺\"刻于灵脉井壁。衰潮表现有四：水位下降、井水味涩、引灵器功效衰减三成、夜空\"星失北辰\"。"]},{"t":"ol","items":["灵转煞：抽走灵力→留下空穴→空穴纳煞。&#x6545;\"净化煞气\"是伪命题：煞只能被搬运，不能被消灭。"]},{"t":"ol","items":["过度抽灵：抽灵半径之内，草木渐枯、井水带煞。帝都引灵阵抽灵百里，百里内寸草生煞——人族的繁荣在制造妖族的土地。"]},{"t":"ol","items":["不抽灵则自衡：若淮洲不引灵入器、不设大阵，灵气随潮自涨自落，\"如呼吸不憋\"，故洲上灵煞自行平衡——大陆上唯一\"不抽灵\"的活标本，也是《浊净同源考》的天然证据。"]}]},{"title":"2.4 三族诞生与演化","blk":[{"t":"p","s":"全书最犯忌：三族不是三个物种，而是同一批幸存者在灵力梯度上的三次分化。这句话是《浊净同源考》第一论点的民间版本，也是\"混血之体即同源之证\"的由来。"},{"t":"table","head":["族","神话起源","实际演化（作者层）","生理特征"],"rows":[["人族","拾羽粉而稼穑","居于灵力中等的平原，无法直接驭灵，转向器物与制度","寿 70—90；无灵觉，但\"灵耐\"强；嗅觉对煞极敏感（\"嗅煞\"，边军与蛊医的看家本事）"],["妖族","影中生形","长期居于低灵高煞之地，演化出耐煞体质","寿 90—150；皮下煞脉随情绪浮现；夜视、耐寒、骨密；畏高浓度灵力直照（\"净光灼身\"）"],["灵族","羽尖坠光凝形","居于高灵之地（落珂、涿光、赤华），血中灵浓","寿 200—300；血为\"净血\"（可续灵脉）；离高灵区久居则\"枯\"（皮肤如纸，指节先裂）；生育极低"],["混血","无神话（三族史书均不载）","跨族通婚的结果，体质灵煞同源","三类：人妖（最多）、人灵（极少，寿数之隔）、妖灵（罕见，煞地灵地不相邻）；日光下二气相争即灼痛；情绪激荡则煞纹失控"]]},{"t":"p","s":"混血的世界观意义：混血体质本身就是\"灵煞同源\"的活体证据——他们是《浊净同源考》第三论点的证明物，因此最犯忌。《封阳盟约》第三款不让他们立名，不是歧视的副产品，是歧视的目的：没有名字，就无法成为证据。"}]},{"title":"2.5 世界运行七法则","blk":[{"t":"table","head":["#","法则","内容","主题功能"],"rows":[["1","气息有潮","灵力涨落有周期，不可违、不可催","灾难是自然的，罪是人加的"],["2","灵煞同源","煞是灵空出来的位置","从宇宙观根子上拆掉\"妖=邪\""],["3","力有代价","一切术法等价损耗，载体有上限","世界没有等级，只有\"敢付多少\""],["4","名即籍","有名字才有籍，有籍才有产、有婚、有葬","命名权即权力；\"不立名\"是最狠的刑罚"],["5","档即史","谁记录，谁就有理；不记录等于没发生","三份史书＝三种现实"],["6","桥即例外","蜃市长桥之上，三族规矩暂废","例外之地的存在，证明规矩是人为的"],["7","不可证者恒信","鲲鹏从不可证，故人人信；偏见亦然","全书的认识论母题"]]}]},{"title":"2.6 世界的历史纪年：潮汐历","blk":[{"t":"p","s":"历法："},{"t":"p","s":"一年十二潮（月），岁首醒月：醒、息、涌、汛、平、盈、缓、滞、敛、沉、眠、藏。"},{"t":"p","s":"每潮三十日，一岁三百六十日；另置息日五天，不纪事——蜃市\"息日市\"，全年唯一的三族自由市日（不查籍、不佩牌、不收税）。"},{"t":"p","s":"小衰潮：滞月延长七至十日，约十年一次。"},{"t":"p","s":"大衰潮：滞月提前并连月，约百年一次（一〇七年滞月提前至五月；二〇七年提前至汛月）。"},{"t":"p","s":"天象：衰潮时\"昼短一线，星失北辰\"——北辰，传说是鲲鹏的眼睛。"},{"t":"p","s":"三族三套纪年："},{"t":"table","head":["族","纪年","元年","用法"],"rows":[["人族","潮历","灵族守档一脉立《潮录》之年","官方文书、史书、洲规"],["妖族","影历","十七氏立氏老会之年","氏籍册、血誓文书；比潮历晚四十三年"],["灵族","珂历","落珂境第一次净血大祭之年","琴音记史、祭仪名录"]]},{"t":"p","s":"叙事用法：跨族文书必须换算，换算即摩擦——同一件事，在三种日历上不是同一天。这是\"偏见写进时间\"的一处细节，正文中由抄书吏、牙人、唱证人三类人自然带出。"}]}]}]},{"num":"三","title":"地理与自然环境","raw":"第三篇｜地理与自然环境","zh":[{"title":"03. 十洲地理志","sec":[{"title":"3.1 玄溟洋总体地理","blk":[{"t":"p","s":"基准：上北下南，左西右东；大洋统称玄溟洋。"},{"t":"p","s":"名词：洲＝大型陆块；境＝次级岛；\"十洲\"是统称，实含 13 个独立岛体。"},{"t":"p","s":"计量：1 里＝ 0.5 公里；航速按普通木帆船、无风正常航速计；逆风或风暴加倍耗时。"},{"t":"p","s":"十三岛体一览："},{"t":"table","head":["#","岛体","方位","归属","备注"],"rows":[["1","澄鸣洲","中央主岛北部","人族","高地丘陵，书院林立"],["2","若淮洲","中央主岛西部","混居缓冲，中央主岛四洲之一；人族六洲行政链不覆盖，村社自治","淮水三角洲，不抽灵"],["3","羲和洲","中央主岛东部","人族","河谷平原，帝都"],["4","扶桑洲","中央主岛南部","人族","湿热密林，商港"],["5","封阳洲","西北独立岛","人族","岩岸石堡，军镇"],["6","珩蕴洲","西南独立岛","人族","迎风山城，匠作"],["7","凉凌洲","极南大陆","妖族","峡湾冰原，幽都在地底"],["8","赤华境","中南弧岛","灵族","红土台地，星象祭仪"],["9","落珂境","中东小岛","灵族","鲲鹏之源在岛下"],["10","涿光境","东北连体岛北段","灵族","峡谷灯楼，守档"],["11","东阴洲","东北连体岛南段","妖族","与涿光境隔谷相望"],["12","乾时洲","东南连体岛北段","人族","星位阵城"],["13","碧海洲","东南滨海低地","共管","浅滩红树林，蜃市"]]},{"t":"p","s":"中央主岛一体四洲，水道陆路互通，不需航海。故\"十洲\"是文化统称，\"十三岛体\"是航海事实。"}]},{"title":"3.2 洋流体系","blk":[{"t":"table","head":["洋流","走向","叙事用法"],"rows":[["北玄环流","北部顺时针：封阳东侧→若淮外海→涿光西侧→东","利西→东北航行；返程逆流艰难，商队按单程雇船"],["中洲横流","中央群岛东西向，环主岛外围，流速平缓","岛际通勤主航道；落珂、涿光在其带上"],["南寒回流","南部逆时针寒流：凉凌起→赤华外海→主岛南侧与横流交汇","携冷、多雾、多风暴；越往南越冷"],["洋流交汇危险带","赤华境北侧","冷暖相撞，常年海雾、突发气旋，古航海禁地"]]},{"t":"p","s":"翻潮：衰潮前兆之一，中洲横流短暂倒流半日。老水手观水色（靛转墨）可知。一〇七年五月曾翻潮——可作大衰的天象前兆；二〇七年汛月再翻，为故事开场的\"天有异象\"。"},{"t":"img","src":"assets/img1.png","cap":"玄溟洋海图（总览）"}]},{"title":"3.3 气候带（由北至南）","blk":[{"t":"p","s":"北部（封阳、涿光）温带季风，夏暖多雨、冬偏凉、海岸偶有冷雾，无永久冻土 → 中央主岛亚热带（澄鸣凉爽湿润、扶桑温热多河谷密林、山地局部气候）→ 中部岛群（赤华亚热带偏干、沿岸红土台地；落珂海洋性，温和多雨多丘陵）→ 东南（乾时北部温暖；碧海湿热，浅滩红树林，雨季台风）→ 西南珩蕴（迎风多雨，山地多云）→ 最南凉凌（亚寒带，寒流显著，全年偏冷，高地常年覆霜，夏季短暂凉爽）。"}]},{"title":"3.4 各洲地貌与本土物产","blk":[{"t":"table","head":["岛体","地貌","物产","一句话风物"],"rows":[["澄鸣洲","高地丘陵，山地林地","桑皮纸、松烟墨、刻书梨木、云雾茶","全洲以鸣钟作息，钟一响，满山翻书声"],["若淮洲","平缓丘陵＋淮水三角洲","淮稻、苇编、海盐、蚌珠","水清蚌肥——因为这块地从不抽灵"],["羲和洲","开阔河谷平原","五谷主仓、官窑\"净白\"瓷、驿马","城郭九重，檐角悬日纹，越往里越白"],["扶桑洲","湿热河谷密林","神木脂（船漆）、香料、硬木、蔗糖","船坞连着林子，砍树的人兼造桨"],["封阳洲","岩岸高台、石堡群","铁煤、青石、耐寒矮马、风干肉","风大得能把话吹散，故封阳人说话极短"],["珩蕴洲","迎风山城，多云多雨","铜锡矿、灵砂、砂器、引灵器物","家家有炉，孩子在炉边学认矿不学认字"],["凉凌洲","峡湾冰原，高地覆霜","寒煞冰晶、霜皮、雪参、幽冥矿","极夜里，地底有城，城里有星"],["赤华境","红土台地，偏干","赤陶、丹砂、火浣草（耐燃布）","红土晒得发白，观星台比屋高"],["落珂境","丘陵环礁湾","无大产——产\"补给与消息\"","港税、引水人；全世界的船都在这儿换水"],["涿光境","峡谷灯楼","光晶（存光矿石，档窖照明）","峡里全是灯，灯不为照路，为照档"],["东阴洲","平原河谷，与涿光隔谷","煞稻（暖流滋养）、影丝（幽蚕丝）、幽冥矿","日头照不到的谷子，照样灌浆"],["乾时洲","星位阵城、丘陵","测灵仪、阵盘、星图","街巷按星位铺，走错巷等于走错卦"],["碧海洲","浅滩红树林","盐、鱼、红树林蜜、蜃市百业","屋随潮涨潮落，桥不动，屋动"]]}]},{"title":"3.5 海图（文字版）","blk":[{"t":"pre","s":"封阳洲                  涿光境 —— 东阴洲\n                      │  ↷ 北玄环流 ↷            │\n                      │                      落珂境\n        珩蕴洲        │      【中央主岛】        │        乾时洲\n                      │  澄鸣 · 若淮 · 羲和 · 扶桑       碧海洲\n                      │  ⇠ 中洲横流 ⇠            │\n                        赤华境  ✖ 北侧风暴带\n                        凉凌洲  ↶ 南寒回流"}]},{"title":"3.6 航线、距离与航行时间","blk":[{"t":"table","head":["航线","距离","航程","主要风险","沿途港湾"],"rows":[["封阳→若淮","720 里","顺 5 天 / 逆 9 天","西海雾障","封阳石港 · 若淮西港"],["封阳→珩蕴","960 里","8—11 天","西部大洋无遮蔽","珩蕴炉湾"],["珩蕴→若淮","800 里","7—10 天","迎风浪","若淮西港"],["珩蕴→赤华","1100 里","9—13 天","长途无补给","赤华雾港"],["扶桑→赤华","360 里","顺风 3 天","赤华北侧常年海雾","赤华雾港"],["赤华→凉凌","480 里","4—6 天","寒流、流冰","凉凌峡湾"],["凉凌→落珂","1300 里","10—14 天","长途、风暴","落珂环礁湾"],["羲和→落珂","420 里","3—5 天","低","落珂环礁湾"],["落珂→东阴","540 里","4—6 天","低","落珂环礁湾"],["羲和→涿光","900 里","顺 7 天 / 逆 12 天","环流急流段","涿光南湾"],["东阴→乾时","840 里","7—9 天","东侧涌浪","乾时星港"],["乾时→落珂","700 里","6—8 天","涌浪","落珂环礁湾"],["碧海→凉凌","1400 里","11—15 天","东南风暴带","蜃市（起讫）"]]},{"t":"p","s":"一条消息从幽都到蜃市最快十一天——所以三线之间的信息永远滞后，误会永远比澄清先到。"}]},{"title":"3.7 危险海域与避风港湾","blk":[{"t":"p","s":"四处危险海域："},{"t":"ol","items":["赤华风暴带（禁地）：冷暖交汇，雾与突发气旋。唯一可泊处为北岸雾港——雾是灾，也是屏障：雾港人靠雾躲过百年兵灾（战争打不进的地方，是天气挡的，不是人让的）。"]},{"t":"ol","items":["西海无风带（封阳—珩蕴途半）：帆船搁风，比风暴更磨人。船上须备半月淡水。"]},{"t":"ol","items":["东南涌浪带（碧海—凉凌）：长涌暗涌，小船不宜。"]},{"t":"ol","items":["环流急流段（羲和—涿光北侧）：逆流返程耗时近乎翻倍。"]},{"t":"p","s":"六处主要港湾：蜃市（最大，三族共管）、若淮西港（混居补给第一港）、赤华雾港、凉凌峡湾、涿光南湾、珩蕴炉湾。"},{"t":"p","s":"封阳石港为军港——混血之船禁入：制度偏见写进港口，是卷二第一处\"不用台词\"的暴力。"}]},{"title":"3.8 航海风险事件","blk":[{"t":"table","head":["事件","现象","解法","叙事功能"],"rows":[["雾障\"蜃口\"","冷暖交汇浓雾，雾中有蜃楼，船会追着幻影改向","蜃市船帮\"哑铃铛\"规矩：雾中不发声，以水声辨礁；引水人路数全靠口传","无相失踪前最后露面处【挂点】；\"官图不如口传\"的主题镜像"],["洋流突变\"翻潮\"","横流倒流半日，水色靛转墨","老水手观水色，见墨即落帆","衰潮前兆；船期全乱，牙人借机抬价——灾年即牙人生意年"],["暗礁\"鹏牙\"","传说礁石为鲲鹏换羽落齿所化，实为玄武岩礁群","官图不载，只靠各船帮口传的\"礁谱\"","又一处\"口传胜于官档\""]]}]},{"title":"3.9 鲲鹏之源与落珂境","blk":[{"t":"p","s":"统一用字：落珂境。"},{"t":"p","s":"落珂境既是凡人地图上的外港中转岛，也是鲲鹏之源：圣地即在岛下——岛体是\"源\"浮出海面的部分。凡人只见港口市集；守脉者知通往岛心的路。"},{"t":"p","s":"落珂九项方志："},{"t":"p","s":"社会结构：无政，三老共议＋守脉者世职。"},{"t":"p","s":"货币：无市，以愿易愿（天下愿约的源头）。"},{"t":"p","s":"衣食住行：羽白裳；晨露灵酿；居琴阁。凡图上只是\"外港中转岛\"。"},{"t":"p","s":"信仰：鲲鹏本尊——全世界唯一\"见过\"鹏影的地方，因为岛影即鹏影。"},{"t":"p","s":"阶层：守脉者 > 琴史 > 凡灵。"},{"t":"p","s":"语言：珂语最古一支\"落珂音\"，可直接\"演奏\"潮汐。"},{"t":"p","s":"神话：落珂境不是鲲鹏的家，是它睡着时呼出的那一口气。"},{"t":"p","s":"文化：净血大祭之源、下元琴夜之源。"},{"t":"p","s":"科技：岛浮之理＝灵脉正压——灵脉衰则岛沉。衰潮时全岛下降三尺：\"三尺之危\"是灵族最大的恐惧，也是最深的秘密。"},{"t":"p","s":"◆ 碧海洲 · 蜃市（重点洲，三线交汇地）碧海洲是三族交界处唯一常年开放之地。洲上无城郭，只有一座横跨海峡的木石长桥和桥两头蔓延开的水上棚户——人称蜃市。三族在此贸易百年，规矩比任何一座洲城都多，也都软。"},{"t":"ul","items":["社会结构：无官府，靠\"桥议\"自治——每月初一，三族各出三名\"桥老\"在桥心议事，决议刻在桥栏上。牙人是实际的润滑剂与权力者。","货币-信用：三钱并行——人族铜\"蜃钱\"、妖族\"煞珠\"、灵族\"愿约\"（口头之诺，由唱证人高声记账，赖账者从此无人替他唱价）。兑换靠牙人抽成。","衣食住行-风俗：水上棚屋，屋随潮涨潮落。食鱼饭、煞植涮锅、灵酿\"晨露\"。最重要的风俗：\"过桥不问名\"——桥上不许问对方族籍与名讳，只称\"客\"。这条规矩是百年前冤案后，蜃市人自己立的：他们见过名字怎么变成刀。","信仰：蜃神与海灯娘。蜃市人信\"蜃吐楼台\"——蜃是鲲鹏的呼吸落在海面凝成的雾气，楼台是幻，幻里才有真。海灯娘掌灯塔，渔船夜归全凭她一盏灯。","阶层：牙人 > 船帮 > 有牌摊贩 > 无牌客。无牌者只许在夜市做买卖，而夜市恰恰是三族消息最灵通的地方。","语言：蜃市通语——三族语混出的克里奥尔式语言，语法是幽语的倒装，词根多借净语，敬语学珂语的音。孩子一句通语里能同时露出三个族的腔调。","神话：蜃市人说，鲲鹏每次敛翼，影子扫过海面，海里就多一只蜃。蜃不害人，它只是把\"你心里最想看见的\"吐给你看——所以蜃市人夜里不照镜。","文化：三节混编——上元借人族的灯，中元借妖族的影戏，下元借灵族的琴夜。三族节日互借了几十年，借到分不清原本是谁的。","科技：盐田、灯塔、驳船，以及唯一的共同禁令\"桥禁\"——任何人不得携兵刃过桥。桥禁是蜃市唯一的律法，也是唯一被三族共同遵守的东西。"]},{"t":"p","s":"◆ 羲和洲 · 帝都（人族）"},{"t":"ul","items":["社会结构：帝制+净籍制，户分\"净户\"与\"附籍\"。","货币：蜃钱本位，交子通行。","衣食住行：尚白（\"净\"色），九重城郭，檐角悬日纹。","信仰：羲和日神+祖先。","阶层：士农工商，籍贯定终身。","语言：净语，敬语按籍贯分档。","神话：《拾穗书》——鲲鹏以羽翼遮天漏，灵力是它的羽粉，\"本分给人族一半\"。","文化：修史传统极盛，澄鸣洲为其分支。","科技：大型引灵阵、官道驿传。帝都灵耗巨大，是\"过度抽灵生煞\"的反面教材。"]},{"t":"p","s":"◆ 扶桑洲 · 商港（人族）"},{"t":"ul","items":["社会结构：港督+十三行商。","货币：最活络的钱庄业，汇兑通达六洲。","衣食住行：临海吊脚楼，尚玄色商袍。","信仰：扶桑神木+财神。","阶层：以船定身——有大船者为上民。","语言：净语海腔，杂大量通语词。","神话：神木十日，饮其枝液者寿。","文化：航海志、异域博物学。","科技：远洋船、水密隔舱。"]},{"t":"p","s":"◆ 澄鸣洲 · 文教（人族）"},{"t":"ul","items":["社会结构：书院林立，学官治国。","货币：清贫，靠\"润笔\"与刻书业。","衣食住行：青衿，鸣钟为作息（洲名由来）。","信仰：文脉神——传说文字是鲲鹏振翅时抖落的音。","阶层：以著述定座次。","语言：净语雅言，排斥通语。","神话：删改最多——三族史书的\"人族版\"《澄鸣实录》藏于此。","文化：刻书、藏书、毁书。禁毁书目里有一部《浊净同源考》【提案：卷四证物】。","科技：雕版印刷、纸甲。"]},{"t":"p","s":"◆ 乾时洲 · 阵法（人族）"},{"t":"ul","items":["社会结构：阵师行会，师徒制。","货币：以\"阵契\"结算——预付灵力的期货。","衣食住行：洲城即一座大阵，街巷按星位铺设。","信仰：时序之神，司昼夜四时。","阶层：阵师品级即爵位。","语言：净语官腔+阵纹语（半符号系统）。","神话：鲲鹏振翅有时，人当效之。","文化：观星、制历。","科技：封灵阵（封阳洲关隘的技术来源）、测灵仪。"]},{"t":"p","s":"◆ 珩蕴洲 · 匠作（人族）"},{"t":"ul","items":["社会结构：匠籍世袭，行会自治。","货币：以物易工，\"工票\"流通。","衣食住行：炉城，家家有作坊，玉珩纹为匠徽。","信仰：祖师爷——第一位把灵力引进器物的人。","阶层：大匠 > 匠 > 徒 > 匠奴。","语言：净语匠腔，术语极密。","神话：鲲鹏遗羽一枚，铸成了第一柄引灵器。","文化：器物美学，匠人葬器俗（死后最得意之作随葬）。","科技：引灵器物冠绝大陆；彩凤鸣岐琴便出自珩蕴洲古匠之手后流入灵族【提案：联结巽宁线】。"]},{"t":"p","s":"◆ 封阳洲 · 关隘（人族）"},{"t":"ul","items":["社会结构：军镇，戍卒世兵。","货币：军票。","衣食住行：堡塞，阳纹旗。","信仰：关帝式的\"守关神\"。","阶层：军功制。","语言：净语军腔，短促。","神话：关隘封的不是妖，是\"阳过盛则煞生\"的古训。","文化：戍边诗。","科技：封灵阵最大应用地；冤案后《封阳盟约》在此签订【见卷三】。"]},{"t":"p","s":"◆ 东阴洲 · 东北妖域（妖族）【原\"东阳洲\"改定】"},{"t":"ul","items":["社会结构：氏族聚居（十七氏东北支），与灵族涿光境同岛相连、隔谷相望——摩擦不断的第一线。","货币：煞珠。","衣食住行：河谷梯田，煞稻耐寒；幽蚕吐\"影丝\"织影纹衣。","信仰：影翼大祭北支。","阶层：按煞脉深浅分氏，混血者不入氏籍。","语言：幽语东腔，尾音上挑。","神话：《影翼谣》东支唱法：\"日头照不到的谷子，照样灌浆。\"","文化：影戏、织造。","科技：幽冥淬体、煞驯兽。"]},{"t":"p","s":"◆ 凉凌洲 · 幽都所在（妖族）"},{"t":"ul","items":["社会结构：氏老会驻地+逐煞而居的部落联盟（雪罴氏等北境部落不认幽都）。","幽都：建于凉凌洲地底灵穴——亚寒带长夜承载\"城无日而明\"（极夜里，煞植荧荧如星）。"]},{"t":"p","s":"◆ 凉凌洲 · 北境（妖族）"},{"t":"ul","items":["社会结构：逐煞而居的部落联盟。","货币：以物易物。","衣食住行：冰穴，寒煞驯养的雪豹为骑。","信仰：寒煞祖灵。","阶层：猎首制。","语言：幽语北腔，多喉音。","神话：鲲鹏过北冥，冰下有它的旧影。","文化：雪祭、长调。","科技：寒煞冰晶（可封存灵力）。"]},{"t":"p","s":"◆ 若淮洲 · 缓冲（争议地）"},{"t":"ul","items":["社会结构：无主之洲，村社自洽，三族难民杂居。","货币：实物。","衣食住行：淮水两岸，人妖通婚者多隐居于此——违法，所以沉默。","信仰：淮水娘娘。","阶层：无阶层，只有\"留守\"与\"路过\"。","语言：混语，孩子都是天生的通语者。","神话：冤案的第一现场候选——洲上老人对\"那一夜\"各有说法，且互不相同。","文化：口述史，谁也不落笔。","科技：近乎无——恰恰因此，洲上灵煞自行平衡，是大陆上唯一\"不抽灵\"的活标本。"]}]}]}]},{"num":"四","title":"三族文明与社会制度","raw":"第四篇｜三族文明与社会制度","zh":[{"title":"04. 人族、妖族、灵族","sec":[{"title":"4.1 起源与生理特征/医毒体系","blk":[{"t":"table","head":["","人族","妖族","灵族"],"rows":[["自称","净民 / 拾穗者之后","影裔 / 氏人","灵 / 光之后"],["他称（贬）","\"窃火者\"（幽语）","\"妖\"\"蚀物\"（净语，字形从虫旁）","\"蜉\"（珂语忌语）"],["寿数","70—90","90—150","200—300"],["体型","中等，耐力好","偏高瘦，骨密，指节粗","细长，体重轻，肤薄近透"],["特殊感知","嗅煞（煞气敏感，边军与蛊医的看家本事）","夜视；煞脉感（能\"读\"地气走向）","音记忆（听过一遍的曲调永不遗忘）"],["生理弱点","无灵觉，不能直接驭灵","高浓度灵力直照＝灼伤（\"净光灼身\"）","离高灵区久居则\"枯\"：皮肤如纸，指节先裂"],["血","常血","煞血（暗稠，伤口结痂极快）","净血（高灵浓度，可续灵脉，故被索取）"],["生育","常","常（混血不入籍）","极低（一对灵族夫妇一生或仅一胎）"]]},{"t":"p","s":"一条必须记住的因果：灵族生育极低＋净血可续灵脉＝ 灵族的身体从出生起就是战略资源。净血大祭的本意不是杀祭，是\"献血\"；冤案之所以成立，是因为三族都需要有人为\"祭无效\"负责，而不是真的相信血被偷了。"},{"t":"p","s":"三族完整的医学分科、诊断程序、药物分类、医师训练制度、毒术标准。"},{"t":"p","s":"世界的医学底层：病究竟是什么？"},{"t":"p","s":"世界医学的五层病因模型"},{"t":"p","s":"① 普通形体损伤：身体本身出了问题"},{"t":"p","s":"② 灵力失衡：灵力运行和承载出了问题"},{"t":"p","s":"③ 煞脉异常：煞气与身体适应出了问题"},{"t":"p","s":"④ 灵煞冲突：两种力量在同一身体内发生干扰"},{"t":"p","s":"⑤ 器物与环境损伤：身体之外的系统造成疾病"},{"t":"ol","items":["普通形体损伤"]},{"t":"p","s":"与超自然力量没有直接关系的身体问题。"},{"t":"p","s":"外伤：刀伤、烧伤、骨折、撕裂伤。"},{"t":"p","s":"疾病：发热、咳喘、腹痛、感染、虚弱。"},{"t":"p","s":"中毒：误食、药物过量、毒物接触。"},{"t":"p","s":"生理损耗：失血、饥饿、脱水、疲劳、衰老。"},{"t":"p","s":"这类疾病主要依靠草药、包扎、固定、饮食调养、休息和外科处理。"},{"t":"p","s":"它们不应该被灵力直接解决。"},{"t":"ol","items":["灵力失衡"]},{"t":"p","s":"人体自身灵力的运行、储存或引导出现异常。"},{"t":"p","s":"灵力运行不畅。"},{"t":"p","s":"灵力输出过量。"},{"t":"p","s":"经脉承载能力下降。"},{"t":"p","s":"长期使用引灵器物导致身体损耗。"},{"t":"p","s":"灵力被封灵阵阻断后产生的生理异常。"},{"t":"p","s":"主要影响人族和灵族，但妖族也可能受到外部灵力环境变化的影响。"},{"t":"ol","items":["煞脉异常"]},{"t":"p","s":"妖族与煞环境之间的适应关系出现问题。"},{"t":"p","s":"煞脉堵塞。"},{"t":"p","s":"煞气浓度超过身体承载能力。"},{"t":"p","s":"长期离开适宜煞环境，出现煞脉衰弱。"},{"t":"p","s":"煞气被强行压制后产生反噬。"},{"t":"p","s":"煞蚀造成组织或器物损伤。"},{"t":"p","s":"煞不是可以被彻底消灭的邪气。煞气只能被引导、分散、封存、转移，或者改变其作用位置。把一个人的煞病转移到另一个人身上，不等于治愈。"},{"t":"ol","items":["灵煞冲突"]},{"t":"p","s":"人族的灵力体系与妖族的煞脉体系，在特定条件下会相互干扰。"},{"t":"p","s":"灵力与煞脉同时紊乱。"},{"t":"p","s":"一方压制另一方，造成身体局部失衡。"},{"t":"p","s":"灵力治疗加重煞脉损伤。"},{"t":"p","s":"煞气干扰引灵器物。"},{"t":"p","s":"长期接触不同力量环境，身体无法适应。"},{"t":"p","s":"这类患者最容易被三族传统医者误诊，因为每一族都倾向于用自己的知识解释疾病。"},{"t":"ol","items":["器物与环境相关疾病"]},{"t":"p","s":"引灵器物失控造成的身体损伤。"},{"t":"p","s":"封灵阵长期运行区域内的灵力异常。"},{"t":"p","s":"测灵仪检测误差造成的错误治疗。"},{"t":"p","s":"煞蚀导致药材、器具、容器发生变化。"},{"t":"p","s":"矿物、药材或水源受到灵煞环境影响。"},{"t":"p","s":"它意味着医者不能只检查病人，还要调查病人生活的环境、使用的器物以及接触过的物质。"},{"t":"p","s":"三族医学体系：各自如何认识身体、诊断疾病和治疗？"},{"t":"p","s":"人族医学体系名称：净息医理；"},{"t":"p","s":"核心特征：辨物、辨症、制药、用器"},{"t":"p","s":"人族医学的核心是：通过观察身体变化、识别外部物质、配制药物和使用器具，干预疾病。"},{"t":"p","s":"人族不应该因为没有妖族的耐煞体质、灵族的净光能力，就显得医学落后。"},{"t":"p","s":"人族的优势应该是积累、记录、配方、工具和技术。"},{"t":"p","s":"人族虽拥有引灵器物体系，但人族医学不是人人都会引灵。普通医者可以通过药物、外科、经验性诊断治疗普通疾病；只有受过训练的医者或掌握特殊器具的人，才有能力干预灵力运行。"},{"t":"p","s":"珩蕴洲的器物技术尤其发达，所以医者特殊器物大多来自珩蕴洲；"},{"t":"p","s":"纳维族则是世代以蛊入医的人族南方支族。"},{"t":"p","s":"人族医学的五个分支"},{"t":"table","head":["分支","主要研究对象","典型技术"],"rows":[["草木药学","植物、矿物、动物药材","辨药、炮制、煎煮、外敷"],["形体医术","骨骼、肌肉、脏腑、创伤","接骨、止血、包扎、针刺"],["蛊医","蛊虫与人体、病症的关系","养蛊、驭蛊、探病、引蛊"],["灵息医术","人体灵力运行","调息、引灵、经脉疏导"],["器具医术","引灵器物与身体的交互","测量、辅助诊断、局部干预"]]},{"t":"p","s":"人族医学如何诊断？"},{"t":"p","s":"建议形成一个相对标准化的诊疗过程："},{"t":"p","s":"问诊：症状出现时间、生活环境、饮食、接触过的药材。"},{"t":"p","s":"望诊：面色、皮肤、舌象、伤口、身体异常。"},{"t":"p","s":"触诊：脉搏、体温、肿胀、局部疼痛。"},{"t":"p","s":"试药：对少量药材或药物进行反应观察。"},{"t":"p","s":"器具辅助：有条件时使用引灵器物观察灵力运行情况。"},{"t":"p","s":"记录：药方、用量、疗程、疗效和不良反应。"},{"t":"p","s":"“测灵仪只测浓度、不测真伪”；"},{"t":"p","s":"不要让引灵器物代替医者判断。器物只能测量某些指标，不能自动理解病因。"},{"t":"p","s":"人族医学的弱点"},{"t":"p","s":"对煞植和妖族煞脉缺乏直接经验。"},{"t":"p","s":"普通医师难以处理灵煞冲突。"},{"t":"p","s":"依赖药材供应与器物条件。"},{"t":"p","s":"医学知识容易被正统医籍、药材行会和身份制度垄断。"},{"t":"p","s":"蛊医可能在专业上有效，却因为社会偏见而不被认可。"},{"t":"p","s":"特别是纳维族，建议把它设定为人族医学中的一个重要地方学派，而不是单纯的蛊术部落。"},{"t":"p","s":"妖族医学体系名称：幽脉医理；"},{"t":"p","s":"核心特征：顺煞、养脉、借植、适应环境"},{"t":"p","s":"妖族医学的核心是：身体并非要排斥煞，而是要与煞环境保持适当的关系。"},{"t":"p","s":"这与人族医学有根本区别。"},{"t":"p","s":"妖族具有煞脉相关的身体特征。"},{"t":"p","s":"妖族能够耐受一定程度的煞环境。"},{"t":"p","s":"煞地拥有煞植、煞兽和矿藏，是妖族的家园。"},{"t":"p","s":"妖族有幽冥淬体、煞驯兽等技术。"},{"t":"p","s":"煞气不能被消灭，只能转移。"},{"t":"p","s":"因此，妖族医学不把煞气简单视为疾病。"},{"t":"p","s":"妖族医学的五个分支"},{"t":"table","head":["分支","主要研究对象","典型技术"],"rows":[["煞脉医术","煞脉运行、浓度、承载","导煞、疏脉、缓煞"],["煞植药学","煞植的生长、药性与毒性","采集、炮制、药浴、敷治"],["煞兽医学","煞兽、兽毒、兽伤","驯养、取材、伤口处理"],["淬体疗法","身体对煞的适应能力","渐进耐受、体质调养"],["环境医术","煞地、灵穴、气候与疾病","迁居、择地、调节煞环境"]]},{"t":"p","s":"妖族医学如何诊断？"},{"t":"p","s":"它不会只看病人的脉搏，而会重点观察："},{"t":"p","s":"煞脉的深浅、运行和阻滞。"},{"t":"p","s":"皮肤、瞳孔、毛发等外在反应。"},{"t":"p","s":"身体对当地煞浓度的适应情况。"},{"t":"p","s":"患者近期是否离开原本的煞地。"},{"t":"p","s":"煞植、煞兽和矿物接触史。"},{"t":"p","s":"病人是否长期使用过压制煞气的药物。"},{"t":"p","s":"妖族医学的主要治疗方式"},{"t":"p","s":"第一种：导煞。"},{"t":"p","s":"改变煞气在身体中的分布，使局部过量的煞气不再持续损伤身体。"},{"t":"p","s":"但导煞必须有承载去处，不能凭空排出。"},{"t":"p","s":"第二种：缓煞。"},{"t":"p","s":"降低煞气对身体的即时刺激，让患者获得恢复时间。"},{"t":"p","s":"它可以缓解症状，却不代表病因消失。"},{"t":"p","s":"第三种：借植。"},{"t":"p","s":"利用煞植的生长环境、药性和载体特征，辅助调节患者身体中的煞气。"},{"t":"p","s":"这里可以让不同煞植有不同的作用："},{"t":"p","s":"有些适合暂时储存煞气。"},{"t":"p","s":"有些适合减缓煞气运行。"},{"t":"p","s":"有些可以作为煞毒的载体。"},{"t":"p","s":"有些能够缓解煞脉损伤。"},{"t":"p","s":"第四种：调境。"},{"t":"p","s":"改变患者所在环境，使身体重新适应适宜的煞浓度。"},{"t":"p","s":"这很重要，因为妖族的某些病症可能不是患者本身出了问题，而是他长期生活的环境发生了变化。"},{"t":"p","s":"妖族医学的弱点"},{"t":"p","s":"过于依赖煞地与煞植资源。"},{"t":"p","s":"不同氏族的煞脉结构和经验未必相通。"},{"t":"p","s":"离开原生环境后，部分治疗手段难以实施。"},{"t":"p","s":"煞脉深浅可能被用于划分阶层，医学知识因此成为氏族权力。"},{"t":"p","s":"过度导煞可能把病症转移给其他人、动物或环境。"},{"t":"p","s":"这最后一点尤其重要：妖族医者也可能因为利益而把患者的煞病转移到弱者身上。"},{"t":"p","s":"人妖医术有社会伦理冲突。"},{"t":"p","s":"灵族医学体系名称：珂光医理"},{"t":"p","s":"核心特征：净光、调律、封存、校正"},{"t":"p","s":"灵族医学的核心是：通过灵光、音律与精密控制，使身体和外部灵力环境恢复协调。"},{"t":"p","s":"灵族不应只是“高级治疗师”，也不应该拥有可以解决所有问题的万能净化能力。"},{"t":"p","s":"灵族医学的五个分支"},{"t":"table","head":["分支","主要研究对象","典型技术"],"rows":[["净光疗法","外部灵力干扰与部分煞蚀","净光、局部照护"],["灵律调理","身体与灵力的协调","音律引导、节律调整"],["灵质封存","灵力异常的暂时控制","封存、隔离、稳定"],["灵体诊察","灵力运行与载体状态","灵光观测、共振辨识"],["器灵照护","器物、器灵与灵力关系","校音、调律、修复"]]},{"t":"p","s":"因此，可以让灵族的医学知识也具有声音特征：不同音程代表不同状态，不同节律对应不同的调理方式。"},{"t":"p","s":"但要注意，琴音不能直接等于治疗。它更像一种灵力调节媒介。"},{"t":"p","s":"灵族医学如何诊断？"},{"t":"p","s":"观察灵光的稳定程度。"},{"t":"p","s":"判断灵力是否存在紊乱、断裂或异常聚集。"},{"t":"p","s":"通过音律反馈判断身体与外部灵力的协调情况。"},{"t":"p","s":"观察器物、环境和患者之间是否存在异常共振。"},{"t":"p","s":"对煞蚀造成的损伤判断是否仍在扩散。"},{"t":"p","s":"灵族医学的弱点"},{"t":"p","s":"净光不等于万能解毒。"},{"t":"p","s":"净光对某些煞蚀有效，但可能损伤妖族自身的煞脉。"},{"t":"p","s":"过度封存灵力可能使身体失去正常的力量调节能力。"},{"t":"p","s":"灵族的知识体系高度依赖音律和自身感知，跨族传授困难。"},{"t":"p","s":"灵族可能将自身的“净”视为绝对标准，忽略妖族身体对煞的正常需求。"},{"t":"p","s":"限制："},{"t":"p","s":"灵族净光可以削弱某些煞蚀过程，却不能把妖族身体中的煞脉当成污染清除。"},{"t":"p","s":"毒术体系？"},{"t":"p","s":"毒术应该是三族医学中共同存在的专业方向。"},{"t":"p","s":"研究的是：某种物质或力量，在什么剂量、什么载体、什么时间和什么身体条件下，会对生命造成什么影响。同一种物质可以是药，也可以是毒。"},{"t":"p","s":"区别不只在物质本身，还在于：剂量；使用方式；接触途径；身体承受能力；使用时机；是否有对应的解救措施。"},{"t":"p","s":"三族毒术的区别"},{"t":"table","head":["体系","毒术优势","主要局限"],"rows":[["人族毒术","药材炮制、复方配制、蛊毒、剂量控制","对特殊煞性物质识别不足"],["妖族毒术","煞植毒、煞兽毒、煞脉干扰","受煞环境和身体条件限制"],["灵族毒术","灵力扰乱、封存、器物干预","对妖族正常煞脉可能造成误伤"]]},{"t":"p","s":"毒术还应该有一套统一的专业分类，最重要的是，毒术必须有对应的解毒和救治知识。"},{"t":"table","head":["类别","作用方向","医学上的对应研究"],"rows":[["麻痹类","暂时影响身体活动","神经与肌肉功能"],["感官类","影响视觉、听觉、嗅觉等","感知异常"],["脏腑类","损伤内部器官功能","内脏损伤与解救"],["灵力类","干扰灵力运行","灵力失衡"],["煞性类","干扰煞脉或造成煞蚀","煞脉疾病"],["迷识类","影响认知和判断","意识异常"]]},{"t":"p","s":"混血医者能干什么"},{"t":"p","s":"举一个具体病例："},{"t":"p","s":"一名妖族患者长期生活在煞地，后来被封灵阵困在灵力稀薄的区域，又误服了人族药商出售的错误药物。"},{"t":"p","s":"人族医师可能先判断药物中毒和普通身体损伤。"},{"t":"p","s":"妖族医者可能发现煞脉受到压制，患者并非单纯煞气过盛。"},{"t":"p","s":"灵族医者可能判断封灵环境造成了持续的灵力失衡。"},{"t":"p","s":"混血医者则必须把三种诊断结合起来，判断先处理哪一个问题，哪些力量不能同时干预。"},{"t":"p","s":"混血医者的优势不是拥有三族都没有的神秘力量，而是能够理解三套医学语言，知道每一种治疗方式的边界。"},{"t":"p","s":"总结"},{"t":"p","s":"三族医学之间的客观关系"},{"t":"p","s":"三族医学应该形成一种互相需要、互相不信任的关系。"},{"t":"img","src":"assets/img2.png","cap":"三族医学知识互补结构"}]},{"title":"4.2 社会结构与政治制度","blk":[{"t":"table","head":["","人族","妖族","灵族"],"rows":[["政体","帝制＋学官制（羲和朝堂 / 澄鸣书院 / 六洲分治）","氏老会共议（十七氏，驻幽都）＋北境部落自治","三老共议＋守档 / 守脉世职"],["权力来源","籍（净籍）＋史（谁修史）＋阵（谁控灵）","血（氏籍）＋煞脉深浅＋猎场","血（净血）＋档（谁守档）"],["决策方式","廷议、奏疏、删改实录","血誓、氏老会、影戏舆论","琴议（以琴音表态，沉默即弃权）"],["基层","里甲、保甲、洲规","氏、帐、猎团","琴阁、档窖、祭户"],["特点","制度最完备，也最擅长用制度掩盖","最讲\"影\"，故最擅长藏","最讲\"记\"，故最擅长删"]]},{"t":"p","s":"人族六洲分工：羲和（帝都·朝堂）、澄鸣（文教·书院与史馆）、扶桑（商港·十三行）、乾时（阵法·行会）、珩蕴（匠作·匠门）、封阳（关隘·军镇）。六洲各有洲规，洲规之间互相不认——人族的偏见首先是\"自己人对自己人\"的。"},{"t":"p","s":"妖族十七氏（点名者）："},{"t":"p","s":"鬼豹氏：白芜所属。善潜行、突袭，氏纹为眉心一竖。冤案后被当作\"叛仪之族\"，猎场被夺，衰败至今。"},{"t":"p","s":"蜃蛟氏：河海交界，善驭水与雾，氏老蜃无涯为氏老会主战派盟主候选。"},{"t":"p","s":"烛阴氏：司\"影\"与\"记\"，历代秘密收容混血儿。"},{"t":"p","s":"雪罴氏：凉凌北境部落，不认幽都，只认寒灵。对\"血仇\"冷感：\"冻土里没有仇恨的燃料。\""},{"t":"p","s":"灵族三支：守脉（落珂境，掌灵脉与净血）、守档（涿光境，掌密档）、司祭（赤华境，掌星象与祭仪）。三支互不统属，三老由三支各推一人。"}]},{"title":"4.3 阶层、身份与户籍","blk":[{"t":"p","s":"人族 · 净籍制："},{"t":"p","s":"净户（正籍，可应试、置产、婚配、入城）"},{"t":"p","s":"附籍（次籍：匠奴、蛊医、疠人、归化妖族；可居不可试，可役不可仕）"},{"t":"p","s":"无籍（逃户、混血、流民；不入册即无诉权）"},{"t":"p","s":"妖族 · 氏籍制："},{"t":"p","s":"有氏者（十七氏任一，按煞脉深浅定尊卑）／无氏者（混血、被\"逐影\"者、俘人之后）"},{"t":"p","s":"氏籍册上没有\"混血\"这个写法——不是不写，是没有这个字（制度性失语，见 4.7）"},{"t":"p","s":"灵族 · 琴籍制："},{"t":"p","s":"有琴籍者（守脉／守档／司祭三支）／凡灵（无琴籍，可居不可议）／器灵（有身无籍，附于逝者之身，借名而活）"},{"t":"p","s":"混血 · 无籍：《封阳盟约》第三款原文：\"混血之子，不入两籍，不承两产，不立两名。\""},{"t":"p","s":"不入两籍 → 无诉权，无医籍，无葬地；"},{"t":"p","s":"不承两产 → 父母之产归族，混血者净身；"},{"t":"p","s":"不立两名 → 只能有一个名字，且不得记入任何册——名字变成刀之后，索性不许你有名字。"},{"t":"p","s":"这条法律是全设定最\"静\"的暴力。它不制造惨叫，只制造\"查无此人\"。噬轲的自我介绍永远是\"我叫噬轲\"——因为他没有第二个能证明自己的东西。"}]},{"title":"4.4 经济、货币与贸易","blk":[{"t":"p","s":"三套货币（蜃市并行，靠牙人换算成\"桥价\"）："},{"t":"table","head":["族","货币","形态","信用来源","弱点"],"rows":[["人族","蜃钱（铜钱）＋交子","铜钱、纸钞","帝都国库与十三行联保","战事一起即滥发"],["妖族","煞珠","幽煞凝晶，可磨可储","氏老会认珠不认人","离开煞地会缓慢\"失重\"（变轻、变脆）"],["灵族","愿约","口头之诺，由唱证人高声记账","信誉：赖账者从此无人替他唱价","无法继承、无法抵押，只认\"当场\""]]},{"t":"p","s":"桥价：蜃市牙人每日在桥心挂牌，以当日三族货量定兑换率。桥价一日三变，故蜃市有谚：\"桥上无隔夜的钱。\""},{"t":"p","s":"主要贸易品目："},{"t":"table","head":["出口","人族","妖族","灵族"],"rows":[["主产","粮、瓷、纸、阵盘、引灵器","煞植、影丝、幽冥矿、寒煞冰晶","灵酿、光晶、琴、净血制品（极贵，且违法）"],["急需","煞植药（妖医不可替代）、寒煞冰晶","铁器、盐、粮（凉凌不产粮）","铜锡、纸、器物（灵族不善造物）"],["禁运","封灵阵、测灵仪（军用）","煞毒、影丝（用于制\"隐衣\"）","净血、冰弦玉版、密档"]]},{"t":"p","s":"一处细节：灵族不事生产，靠\"净血制品\"与\"琴\"换粮——一个自称\"光\"的族，靠卖血活着。这是全书对灵族最不客气的一笔，也是璇玑恐惧\"公开衰潮\"的真正原因：一旦世界知道灵脉会衰，灵族连\"血\"都不值钱了。"}]},{"title":"4.5 日常生活：衣食住行","blk":[{"t":"table","head":["","人族","妖族","灵族"],"rows":[["衣","尚白（\"净\"色）；净户麻丝绸，附籍粗褐；佩牌者腰悬木牌","尚影纹；影丝织衣，纹样即家系；混血者不得用\"全纹\"，只能织半纹","羽白裳；琴史有\"音纹\"佩（一条丝绦代表一支曲）"],["食","五谷、蒸食、酱；蛊医家另备\"虫瓮\"","煞植涮锅、发酵肉、苦叶酒","晨露灵酿、花馔；不食\"有影之物\"（菌类、笋）"],["住","城郭合院，檐角悬日纹；羲和九重城郭，越里越白","幽都地底，屋随煞脉；东阴梯田吊脚楼","琴阁悬水，屋不落地（\"恐压灵脉\"）"],["行","官道驿传、车马、渡船","雪豹骑（北境）、影行（刺客）、渡鸦传信","舟、琴音传讯（珂语可\"以音代书\"）"]]},{"t":"ol","items":["若淮的\"隔水聘\"：两岸成亲，隔水拜堂，各不落籍。孩子生在水边，两边都不上籍——所以若淮的孩子全会说通语，因为没人教他们\"你该说哪一种话\"。"]},{"t":"ol","items":["蜃市的\"息日市\"：一年五天，不查籍、不佩牌、不收税。这一天桥上最挤，也最安静——因为没人敢在这一天吵架，吵了，明年就没得做买卖。"]}]},{"title":"4.6 信仰、神话与祭祀","blk":[{"t":"table","head":["族","神话","崇拜对象","祭祀","禁忌"],"rows":[["人族","《拾穗书》","羲和日神＋祖先＋文脉神","春祈秋报；澄鸣鸣钟祭文脉；封阳祭关","不祭\"浊\"；不直呼鲲鹏名（称\"天漏\"）"],["妖族","《影翼谣》","影翼（鲲鹏之影）＋煞脉祖灵","影翼大祭（敛月）；北境雪祭","不在正午行祭；不与\"净光\"同室"],["灵族","《落珂引》","鲲鹏本尊","净血大祭（十年一次，滞月）；下元琴夜","忌语\"蜉蝣\"；忌言\"潮汐有期\"；忌在琴史上\"留空\""]]},{"t":"p","s":"净血大祭的完整流程（这是冤案的制度舞台，必须写清）："},{"t":"ol","items":["定期：每十年一次，于滞月（衰潮月）在落珂境阶前举行。"]},{"t":"ol","items":["分工：灵族出净血（守脉者割腕注灵脉）；人族出司仪（唱礼、校时、定\"气序\"）；妖族出引路（以煞脉为衰弱的灵脉\"开道\"）。"]},{"t":"ol","items":["名录：三族各荐十二人，共三十六人；其中三人为\"执礼\"——献血者、司仪、引路。"]},{"t":"ol","items":["一〇七年：执礼三人为——灵族守脉者泠岫（献血）、人族祭司沈聿（司仪）、妖族行者白芜（引路）。"]},{"t":"ol","items":["祭后：气息未复，反衰。灵族讳\"祭无效\"，改称\"祭被人窃\"。"]},{"t":"p","s":"关键：仪式本身是真的，作用是有的，只是在衰潮年必然失效。所以\"祭无效\"不是骗局，是自然规律；而\"改称祭被人窃\"才是骗局的开始。"}]},{"title":"4.7 语言、文字与禁语","blk":[{"t":"table","head":["","人族 · 净语","妖族 · 幽语","灵族 · 珂语"],"rows":[["形制","方块表意字，有官定正字","倒装语序＋颤音，尾音表敬意；有字，字随氏变","无文字，琴音记史（音高纪年），口传经"],["问候","\"今日气清\"（净语问候即祈净）","\"你影里有火\"（视他人为可自燃之体）","无问候，以一段短琴音代之，曲调因人而异"],["称他族","妖字从\"虫\"旁（偏见写进字形）","人族称\"窃火者\"","凡族统称\"蜉\"（忌语，出口需抚琴一礼）"],["禁语","\"浊净同源\"四字不入正史","\"混血\"一词在氏籍册上无对应写法","\"潮汐周期\"在琴音记史中被抹为一记空弦"],["骂人字根","有（蚀、秽、蠹）","有（窃、伪、软）","有（蜉、浊、急）"]]},{"t":"p","s":"蜃市通语：三语混血——幽语的骨架、净语的词根、珂语的调子。孩子学话时三族话混着说，大人听不出谁是谁，也懒得分。通语是全书唯一\"没有偏见\"的东西，因为它谁的孩子都不是。→ 通语里没有骂人的字根。要骂人，必须切换回母语。每一次辱骂，都是一次\"认祖归宗\"。"},{"t":"p","s":"禁语的三处叙事用法："},{"t":"p","s":"灵族说\"蜉蝣\"要抚琴一礼——所以巽宁说这两个字时故意不抚琴，这是她的反抗手势，也是她唯一的\"失礼\"。"},{"t":"p","s":"人族史官写\"浊净同源\"四字须以朱笔加框，谓之\"囚字\"——字被关起来，意思就不会跑。"},{"t":"p","s":"幽语无\"混血\"写法，故噬轲在氏籍册上只能被写作\"无名·鬼豹氏帐下\"。"}]},{"title":"4.8 教育、文化与科技","blk":[{"t":"table","head":["","人族","妖族","灵族"],"rows":[["教育","澄鸣书院（经史）＋六洲学官＋匠门师徒＋阵师行会考核","氏学（口传）＋影戏（历史靠看戏学）＋猎团实训","琴阁（师徒一对一，以曲代课）＋档窖见习"],["文化","修史、刻书、藏书、毁书；诗文、篆刻","影戏、口弦、长调、织造、煞植医道","琴夜、音纹、祭舞；不留文字，故极重记忆"],["科技","雕版印刷、水密隔舱、引灵阵、封灵阵、测灵仪、纸甲","幽冥淬体、煞驯兽、影丝织造、寒煞冰封","光晶、冰弦玉版（音刻）、悬浮之理（灵脉正压）"],["教育的目的","造\"可用之人\"","造\"可战之人\"","造\"可记之人\""]]},{"t":"p","s":"对照：人族把孩子教成\"该说什么\"，妖族教成\"该忍什么\"，灵族教成\"该记什么\"。三族都不教孩子\"该问什么\"。"}]},{"title":"4.9 三族之间的关系与偏见","blk":[{"t":"pre","s":"递归歧视链（每个人都在链上有一个位置，故无人无辜）："},{"t":"p","s":"灵族 ──看低──▶ 人族（\"蜉蝣，不知潮\"）▲ ││ 看低└──看低── 妖族 ◀─────┘（\"妖，蚀物\"）│└─看低─▶ 混血（\"无籍，不算人\"）│└─看低─▶ 人族内部的蛊医 / 疠人 / 附籍（\"半秽\"）"},{"t":"p","s":"人族看妖族：污秽、带煞、蚀田。（经济根源：人族抽灵制造了煞地，却把煞地的主人当作灾祸。）"},{"t":"p","s":"人族看灵族：傲慢、不事生产、卖血为生。（真相刺痛，故说得最狠。）"},{"t":"p","s":"妖族看人族：窃火者、软、话多。（神话里人偷了光影的一半。）"},{"t":"p","s":"妖族看灵族：抽我们的地气，还嫌我们脏。"},{"t":"p","s":"灵族看两族：都是蜉蝣，百年即死，何足与论。（最优雅的轻蔑。）"},{"t":"p","s":"三族看混血：不存在。（最彻底的一种看法。）"},{"t":"p","s":"三族互评表："},{"t":"table","head":["","人族怎么说","妖族怎么说","灵族怎么说"],"rows":[["人族","——","\"话多，火多，胆子少\"","\"会造东西，不会养气\""],["妖族","\"身上有煞味，闻着就知道\"","——","\"影子里有火，倒还算活物\""],["灵族","\"不事生产，血比人贵\"","\"凉，傲，记仇记得比我们久\"","——"],["混血","\"不干净\"","\"不算氏人\"","\"两半都不是\""]]},{"t":"p","s":"偏见的三次制度化："},{"t":"ol","items":["一〇七年《封阳盟约》：通婚之禁 → 混血从\"私生\"变成\"违法\"。"]},{"t":"ol","items":["一七六年《佩牌令》：妖族入城佩牌 → 偏见从\"看法\"变成\"手续\"。"]},{"t":"ol","items":["一九八年《测灵仪之禁》：以\"测煞\"为名设卡收费 → 偏见从\"手续\"变成\"生意\"。"]}]}]}]},{"num":"五","title":"历史与核心事件","raw":"第五篇｜历史与核心事件","zh":[{"title":"05. 百年历史志","sec":[{"title":"","blk":[{"t":"p","s":"本章是全书的\"史书底稿\"。正文从不一次讲完，而由三族史书、唱证人愿约簿、老人回忆三种载体分别漏一点。写作者手中必须有完整的这一章。"}]},{"title":"5.1 鲲鹏衰潮与灵脉周期","blk":[{"t":"p","s":"周期规律：小衰潮约十年一次（滞月延长七至十日）；大衰潮约百年一次（滞月提前并连月）。"},{"t":"p","s":"民间认知：知道\"年成有好有坏\"，不知道\"灵气也有周期\"——因为周期被写进了禁语（珂语记史中抹为空弦）。"},{"t":"p","s":"上层认知：灵族三老与守档一脉知道；人族乾时行会的测灵仪数据在百年间早已画出周期曲线，被会首压下；妖族氏老会不知，但蜃蛟氏老\"感觉到\"了，并将其当作夺权的机会。"},{"t":"p","s":"全书最狠的一句设定：潮汐的周期成了仇恨的闹钟。每十年响一次，每次都需要一个罪人。"}]},{"title":"5.2 百年前的三族关系（潮历 60—107）","blk":[{"t":"p","s":"格局：三族百年内各按自己的方式划分领域，不通往来，边境交界处大大小小的资源争夺不断，但未起战事。"},{"t":"p","s":"唯一接触面：碧海洲蜃市（隙市）。三族在此贸易百年，\"过桥不问名\"的规矩早于冤案——冤案之后才被写死为铁律。"},{"t":"p","s":"人妖相恋并不罕见，只是不被记录。蜃市通语里\"过桥\"本来只是\"结婚\"的意思，冤案之后才添了\"偷偷地\"这层意思。"},{"t":"p","s":"净血大祭是唯一的\"三族共事\"，也是唯一合法的跨族合作。故冤案发生在祭仪上，破坏力最大——它炸掉的不是两个人，是三族唯一学会的合作方式。"}]},{"title":"5.3 净血大祭（制度说明）","blk":[{"t":"p","s":"见 4.6。此处补三点政治含义："},{"t":"ol","items":["祭仪是灵族的存在理由：灵族不事生产，靠\"净血\"与\"琴\"换取粮铁。祭仪若失效，灵族失去道统。"]},{"t":"ol","items":["祭仪是人族的体面：司仪之位由羲和祭官世家世袭，沈聿是旁支，能任司仪已是破格——他的出身本身就是\"阶层差异带来的不同待遇\"的一处注脚。"]},{"t":"ol","items":["祭仪是妖族的缺口：引路者需妖族人，这是妖族唯一能进入圣地落珂境的机会，也是三族中唯一\"被允许靠近核心\"的耻辱性特权。"]}]},{"title":"5.4 冤案：沈聿、白芜、聆霜","blk":[{"t":"p","s":"三个人："},{"t":"table","head":["","沈聿","白芜","聆霜"],"rows":[["族","人族（羲和祭官世家旁支）","妖族（鬼豹氏，行者）","灵族（守档人，守档一脉）"],["年龄（案发时）","32","29","二百余"],["职","净血大祭司仪","行者（穿行三族地界的信使）","守档人（涿光境密档属）"],["信条","\"礼者，圣人之藩\"——信程序能护人","\"路会通\"","\"档比人长寿\""],["软处","口吃，紧张时更甚","笑点极低，笑时先低头","不肯说\"我不知道\""],["罪名","窃气叛仪","窃气叛仪","失察（后改\"知情不报\"）"],["实际所为","在祭中私改\"气序\"半刻，为白芜多争半刻并肩的时间","在祭中替沈聿挡了一次盘查","请调潮汐档案自证\"此乃周期\"，被驳回"]]},{"t":"p","s":"他们之间的三年（书中最暖的一段，全靠细节，不靠抒情）："},{"t":"p","s":"相识于蜃市，一〇四年春。他替族人买煞植药，她替他讲价。"},{"t":"p","s":"三年间在愿约簿上互相\"唱价\"赊账：他赊她一次引路，她还他一次抄书；账目越记越乱，最后成了一本只有他们两个看得懂的情书。"},{"t":"p","s":"沈聿学幽语，总把\"你影里有火\"说成\"你影里有水\"，她每次都笑，从不纠正。"},{"t":"p","s":"二人本定于一〇七年十月\"过桥\"。《封阳盟约》十月颁行通婚之禁。差一步。"},{"t":"p","s":"冤案的真正成因（三层）："},{"t":"ol","items":["自然层：大衰潮。祭仪必败。"]},{"t":"ol","items":["制度层：祭败必须有人负责。三族各有不能承认的事——灵族不能承认灵脉会衰；人族不能承认司仪无能；妖族不能承认引路无功。"]},{"t":"ol","items":["利益层：三方各自推了一步，无人主谋（见 6.5\"合谋无主\"）。他们选中这两个人，不是因为这两个人有罪，是因为这两个人相爱——相爱是最好的罪证，因为它不需要证据。"]}]},{"title":"5.5 三族联席会审与处决（潮历一〇七年六月—八月）","blk":[{"t":"p","s":"六月：\"窃气叛仪\"罪名成立，沈聿、白芜下狱。聆霜请调潮汐档案自证，被三老驳回——\"档案不可示人\"。"},{"t":"p","s":"七月：三族联席会审，审了十九天。三份供词各按本族礼法书写，彼此矛盾。审出的不是真相，是三族各自\"需要一个罪人\"。"},{"t":"p","s":"人族供词：妖物混入祭仪，以煞引气。"},{"t":"p","s":"妖族供词：人族祭司窃气邀功，欲独吞灵脉。"},{"t":"p","s":"灵族供词：守祭不力，其罪在人妖。"},{"t":"p","s":"沈聿要求按本族礼法单独陈词，被驳。他沉默了——他以为沉默是守礼，后人读成了认罪。"},{"t":"p","s":"八月·敛月十九：处决。二人同日刑于落珂境阶前。临刑未辩一句。唱证人的愿约簿上，这一天的记录是空白——唱证人拒绝唱这一天的价，是百年间唯一一次罢工。"},{"t":"p","s":"同夜：聆霜自沉碧海。解去配重，尸身不获。"}]},{"title":"5.6 《封阳盟约》的签订（潮历一〇七年十月）","blk":[{"t":"p","s":"于封阳洲签订。三款："},{"t":"ol","items":["划界：三族各守其域，边境三十里为\"空界\"，不得耕牧。"]},{"t":"ol","items":["限市：蜃市只许\"息日\"开市（后因生计所迫，改为常年开市但限货类），妖族入城须由牙人作保。"]},{"t":"ol","items":["通婚之禁：三族不得通婚。原文只一句，却最长寿：\"异族为婚者，以叛仪论。\""]},{"t":"p","s":"→ 禁令第一条的措辞出自那桩\"祭仪丑闻\"——从此人妖相恋即是\"叛仪之遗风\"。一条法律把一段爱情变成了罪行。"}]},{"title":"5.7 三族战争与百年对立","blk":[{"t":"table","head":["阶段","年份","形态","特征"],"rows":[["热战","一〇七—一一八","边境烧田、劫粮、蜃市闭市三年","死人最多，记忆最浅——因为活下来的人都在忙着活"],["边衅","一一八—一五八","每十年衰潮一次小战；封阳军镇坐大；灵族闭岛","战争变成\"季节\"，像汛期"],["僵持","一五八—二〇七","佩牌令、测灵仪设卡、通婚禁令固化；蜃市重新繁荣","仇恨制度化：年轻一代只知恨，不知为何恨"]]},{"t":"p","s":"四件改变格局的事【提案】："},{"t":"table","head":["潮历","事件","后果"],"rows":[["118","碧海焚市：热战末期蜃市大火，唱楼半毁，愿约簿分簿开始流散","罗半帆祖上趁乱收购分簿；官方史书对火灾起因记载三种"],["147","销名之议：灵族追销聆霜之名，守档一脉改组，立\"只守档，不言档\"之规","灵族从此不再有\"言档者\"；巽宁终卷要恢复的正是这个位置"],["176","佩牌令：妖族入城须佩木牌，牌上刻氏名与\"限行\"","偏见从看法变成手续；噬轲幼年被盘查的记忆来源"],["198","测灵仪之禁：乾时行会以\"测煞\"为名设卡收费，混血者过卡须\"验血\"","偏见从手续变成生意；混血者被迫绕行山路，若淮因此人口激增"]]}]},{"title":"5.8 一百年间的历史演变（社会的\"慢性病\"）","blk":[{"t":"p","s":"人口：热战十年，三族各损一成。此后妖族生育率反升（煞地生存率高），人族靠农耕恢复最快，灵族再未恢复——三老更不敢公开衰潮了。"},{"t":"p","s":"经济：蜃市从\"隙市\"变成\"必需\"——三族都需要一个不查籍的地方，去买自己族里买不到的东西。"},{"t":"p","s":"语言：通语在蜃市完成克里奥尔化，成为\"第三种母语\"。三族上层视其为\"脏话\"，底层视其为\"活路\"。"},{"t":"p","s":"记忆：一百年足够让仇恨变成常识。二〇七年的年轻人，恨得比一〇七年的人更纯粹——因为他们没见过妖族，也没见过灵族。"},{"t":"p","s":"档案：三份抄本分散三处，各自被\"保护\"成了各自的把柄；愿约簿分簿流落商人之手；净血名录拓片散佚，半枚在纳维族（鸣可家）。"}]},{"title":"5.9 潮历二〇七年的故事起点","blk":[{"t":"p","s":"天象：大衰潮再临。滞月提前至汛月；醒月即见\"昼短一线\"；落珂境全岛下降三尺，守脉者连夜封港。"},{"t":"p","s":"人间：封阳军镇请增军费；乾时行会涨价；澄鸣书院重刊《澄鸣实录》\"冤案卷\"；幽都氏老会筹备影翼大祭，蜃无涯要借祭典定盟主位。"},{"t":"p","s":"三线同时启动，各有各的偶然："},{"t":"p","s":"鸣可：为一具\"煞死\"的尸体验毒，发现尸身上有半枚朱砂拓痕——与家传残片同源。"},{"t":"p","s":"噬轲：师父无相失踪满三年，第三颗佛珠在他掌心裂开一线。"},{"t":"p","s":"巽宁：所附之身的心口旧痕开始疼，疼的日子与落珂境\"三尺\"的谣言同时出现。"},{"t":"p","s":"必然：三条线都被同一件事牵动——有人在二〇七年，重新开始收集当年的证物。"}]}]}]},{"num":"六","title":"政治势力与社会群像","raw":"第六篇｜政治势力与社会群像","zh":[{"title":"","sec":[{"title":"","blk":[{"t":"p","s":"谁在维持这个世界，谁从现有秩序中获利，谁被排除在秩序之外，又是谁正在试图改变它。"},{"t":"p","s":"本篇不单纯介绍三族的政治机构，而是要建立一套完整的社会运行逻辑：权力如何形成、如何下沉到基层、如何转化为利益、如何制造偏见，又如何在漫长时间中变成普通人习以为常的生活规则。"}]}]},{"title":"06. 政权与社会","sec":[{"title":"","blk":[{"t":"p","s":"三族权力不是三座彼此独立的金字塔，而是三个互相扣着药的环。谁也无法彻底消灭谁，因此战争持续百年；也正因为彼此制约，终局谁都无法将对方彻底清算。"}]},{"title":"06.1 权力总论：三族权力三角","blk":[{"t":"ol","items":["三族权力的基本结构"]},{"t":"p","s":"三族的权力来源并不相同。"},{"t":"p","s":"人族依靠籍贯、历史解释权与灵阵技术建立制度；妖族依靠血统、煞脉与氏族关系维持共同体；灵族依靠净血道统、档案控制与祭仪秩序维护自身合法性。"},{"t":"p","s":"三族看似拥有各自完整的权力结构，实际上都存在无法绕开的软处。"},{"t":"table","head":["族群","核心权力来源","决策方式","基层控制手段","权力软处"],"rows":[["人族","籍：净籍；史：修史权；阵：灵阵控制权","廷议、奏疏、实录删改","里甲、保甲、洲规","六洲洲规互不相认；史官害怕档案牵连自身"],["妖族","血：氏籍；煞脉深浅；猎场","血誓、氏老会、影戏舆论","氏、帐、猎团","十七氏内部不齐；北境不认幽都；混血不入册"],["灵族","净血、档案控制权、琴议","三支议事、琴音表态、沉默弃权","琴阁、档窗、祭户","三支互不统属；守档一脉只守档、不言档"]]},{"t":"ol","items":["三条权力铁律"]},{"t":"p","s":"第一条：名即籍，籍即权。"},{"t":"p","s":"一个人是否拥有名字，不只是称呼问题，而是能否进入社会秩序的问题。"},{"t":"p","s":"有名字，才可能拥有正式身份；有籍，才可能获得财产、婚姻、葬仪和法律保护。"},{"t":"p","s":"没有被登记的人，不一定不存在，但在制度中可以被当作不存在。"},{"t":"p","s":"命名权是最安静、也最狠的刑罚。"},{"t":"p","s":"第二条：档即史，史即理。"},{"t":"p","s":"谁记录，谁就拥有解释权；谁决定不记录，谁就能让一件事在制度意义上从未发生。"},{"t":"p","s":"三族各有史书，各自保存一套关于百年前事件的解释。三份史书并非简单的真假之分，而是三种被制度承认的现实。"},{"t":"p","s":"第三条：桥即例外。"},{"t":"p","s":"蜃市长桥之上，三族的身份规矩暂时失效。"},{"t":"p","s":"过桥不问名，不问族籍，只称“客”。"},{"t":"p","s":"蜃市的存在证明：三族的规矩并非天然不可改变，而是人为建立、也可以被人为修改的制度。"},{"t":"pre","s":"3. 三族权力结构总图\n人族\n羲和朝堂\n│\n├── 澄鸣洲：书院与史馆\n├── 扶桑洲：港督与十三行\n├── 乾时洲：阵师行会\n├── 珩蕴洲：匠门\n└── 封阳洲：军镇\n│\n里甲、保甲、村社\n妖族\n幽都氏老会\n│\n├── 十七氏\n│     ├── 氏籍\n│     ├── 血誓\n│     ├── 影戏\n│     └── 猎团\n│\n└── 北境部落：自治，不认幽都\n灵族\n三老\n│\n├── 守脉：落珂境\n├── 守档：涿光境\n└── 司祭：赤华境\n│\n琴阁、档窗、祭户\n蜃市\n桥议\n│\n├── 三桥老\n├── 牙人\n├── 船帮\n├── 唱证人行会\n└── 有牌摊贩、无牌客\n跨族暗线\n潮汐档案\n│\n├── 三族上层各自封存\n└── 无人公开"},{"t":"ol","items":["权力戏的写作原则"]},{"t":"p","s":"权力戏不以“谁赢了”为核心，而以“谁还被需要、谁已经不再被需要”为核心。"},{"t":"p","s":"一个人物失去权力，不一定是被主角打败，也可能是他赖以维持权力的理由已经不存在。"},{"t":"p","s":"终局不追求大规模清算，而是让旧制度逐渐失去继续运作的理由。"}]},{"title":"06.2 人族六洲权力结构","blk":[{"t":"ol","items":["人族权力的整体特征"]},{"t":"p","s":"人族是三族中制度最完备、行政层级最清晰的一方。"},{"t":"p","s":"人族权力建立在三个基础之上："},{"t":"p","s":"净籍： 决定一个人是否拥有正式身份。"},{"t":"p","s":"修史： 决定一件事如何被记录和解释。"},{"t":"p","s":"灵阵： 决定资源、交通、防御与技术设施由谁控制。"},{"t":"p","s":"人族最擅长的不是直接使用暴力，而是把权力写进程序。"},{"t":"p","s":"制度不必公开宣称某些人不值得被保护，只需要在登记、审批、通行、婚姻和财产继承时，让他们始终无法满足条件。"},{"t":"p","s":"人族内部也并非铁板一块。六洲各有洲规，洲规之间互不完全相认。人族的偏见首先发生在“自己人对自己人”之间。"},{"t":"p","s":"注意：沈阶与听澜：人族史权与灵族守档权，彻底分属"},{"t":"table","head":["人物","族属","权力位置","管辖范围","不可混淆点"],"rows":[["沈阶","人族","澄鸣书院史学权威 / 守档首座（人族语境下的“守档”）","人族《澄鸣实录》的修撰、删改、刊行","他管的是人族史书，不是灵族冰弦玉版；他的“档”是人族官档与书院藏本"],["听澜","灵族","涿光境守档首座","灵族冰弦玉版、缄廊档窖、守档一脉人事","他管的是灵族密档，不涉人族史书；他的“档”是琴音刻录的冰弦玉版"]]},{"t":"p","s":"“守档”一词若单独出现，必须由上下文限定族属：人族说“守档”指沈阶一系的书院档官；灵族说“守档”指涿光境守档一脉。"},{"t":"p","s":"沈阶终局交“删改簿”，听澜终局“因档案中也有自己的名字而崩溃”，两件事不合并、不互相替代。"},{"t":"p","s":"两人无直接师承、无血缘、无密信往来；他们的联系只在“都经手过潮汐档案的某一层副本”，且彼此不知道对方掌握到哪一层"},{"t":"ol","items":["六洲权力分布"]},{"t":"table","head":["洲","权力机构","实际掌权者","公开诉求","软处与秘密","与其他洲的矛盾"],"rows":[["羲和洲","朝堂","裴照","绥靖、稳局","经手第一份抄本，终局致仕前交出抄本","怕封阳坐大，又依赖封阳抵御妖族"],["澄鸣洲","书院、史馆","沈阶","护史、护家族","每月焚一页，终局交出删改簿","与羲和争夺正史解释权"],["扶桑洲","港督、十三行","罗半帆","商利、汇兑","祖上趁乱收购愿约簿分簿","与蜃市牙人争航线和桥价"],["乾时洲","阵师行会","宋判","技术垄断、阵契","压下测灵仪周期数据","与封阳争军阵预算"],["珩蕴洲","匠门","章百工","匠作、器物标准","彩凤鸣岐曾经改弦，出自珩蕴匠门","与乾时争夺引灵器标准"],["封阳洲","军镇","韩朔","守边、增军费","借边患坐大，终局哗变后自请解甲","与朝堂、书院、行会均有矛盾"]]},{"t":"ol","items":["六洲权力人物"]},{"t":"p","s":"裴照：羲和朝堂的经手人"},{"t":"p","s":"表层动机：维持朝局稳定，避免三族关系进一步恶化。"},{"t":"p","s":"深层动机：保全自身政治地位，避免承担百年前事件的责任。"},{"t":"p","s":"关键秘密：经手第一份抄本。"},{"t":"p","s":"终局动作：致仕前交出抄本。"},{"t":"p","s":"裴照不是事件的唯一制造者，也不是最终的解释者。他的罪责在于明知材料存在，却选择让它继续留在权力体系之内。"},{"t":"p","s":"沈阶：澄鸣书院的史学权威"},{"t":"p","s":"表层动机：维护正史与书院秩序。"},{"t":"p","s":"深层动机：保护家族和自身的学术权威。"},{"t":"p","s":"关键秘密：每月焚毁一页材料。"},{"t":"p","s":"终局动作：交出删改簿。"},{"t":"p","s":"沈阶相信，历史必须经过整理才能成为秩序。他不是不懂真相的重要性，而是认为真相一旦公开，现有秩序就会崩塌。"},{"t":"p","s":"罗半帆：扶桑十三行的商人"},{"t":"p","s":"表层动机：维持航运、贸易和汇兑。"},{"t":"p","s":"深层动机：保护十三行长期积累的商业利益。"},{"t":"p","s":"关键秘密：祖上曾经收购愿约簿分簿。"},{"t":"p","s":"终局动作：航线逐渐民用化，旧有信息垄断受到冲击。"},{"t":"p","s":"宋判：乾时阵师行会会首"},{"t":"p","s":"表层动机：维护技术标准和阵契安全。"},{"t":"p","s":"深层动机：通过技术门槛维持行会垄断。"},{"t":"p","s":"关键秘密：压制测灵仪周期数据。"},{"t":"p","s":"终局动作：数据公开，行会分裂，部分阵师转向民用技术。"},{"t":"p","s":"宋判最重要的特点是相信数据中立。他并不认为自己在作恶，而认为技术应当由专业人士掌握。"},{"t":"p","s":"章百工：珩蕴匠门代表"},{"t":"p","s":"表层动机：维护器物工艺与匠作标准。"},{"t":"p","s":"深层动机：保护匠门在引灵器制造中的地位。"},{"t":"p","s":"关键秘密：彩凤鸣岐曾经改弦，改弦者来自珩蕴匠门。"},{"t":"p","s":"终局动作：改弦真相公开。"},{"t":"p","s":"韩朔：封阳军镇统领"},{"t":"p","s":"表层动机：守边、保卫人族。"},{"t":"p","s":"深层动机：利用边患扩大军镇权力。"},{"t":"p","s":"关键秘密：边军哗变。"},{"t":"p","s":"终局动作：自请解甲，关隘改为巡检体系。"},{"t":"p","s":"韩朔始终认为守边就是忠诚。他的问题在于，当边患成为权力来源时，他已经无法分辨自己究竟是在保护边境，还是在保护军镇本身。"},{"t":"ol","items":["若淮洲：人族权力体系的裂缝"]},{"t":"p","s":"地理归属：若淮洲属中央主岛一体四洲之一（澄鸣、若淮、羲和、扶桑），地理上属中央主岛西部淮水三角洲，不需航海可达，与澄鸣、羲和陆路水路互通。"},{"t":"p","s":"行政归属：若淮洲名义上归羲和朝堂辖制，实际为村社自治的缓冲洲。人族六洲行政链（羲和—澄鸣—扶桑—乾时—珩蕴—封阳）不覆盖若淮；若淮不设洲衙、不编里甲、不执行净籍审查，只保留村社推举的“水老”处理水利、纠纷与渡口事务。"},{"t":"p","s":"与六洲的关系：羲和朝堂对若淮采取“不登记、不征税、不驻军、不设学官”的四不政策；若淮不向六洲提供兵役与籍册。双方默认：若淮是人族制度的泄洪区——逃户、混血、无籍者流向若淮，比留在六洲境内更“不碍事”。"},{"t":"p","s":"路人口径：若淮不是“自由之地”，是“制度懒得管的地方”。它的自治不是权利，是放弃。若淮洲不属于六洲正式权力链，保留村社自治和多族杂居的状态。"},{"t":"p","s":"这里聚集着："},{"t":"p","s":"无籍者。"},{"t":"p","s":"混血者。"},{"t":"p","s":"逃户。"},{"t":"p","s":"失去原有氏族身份的人。"},{"t":"p","s":"不愿接受六洲洲规的人。"},{"t":"p","s":"三族贸易与迁徙过程中被遗留下来的人。"},{"t":"p","s":"若淮洲并不是理想化的自由之地。它缺少稳定的制度保护，也缺少足够的医疗、教育和行政资源。"},{"t":"p","s":"但它证明了另一种社会生活方式的存在。"},{"t":"p","s":"村塾师用三种语言教三族孩子同一段课文，是若淮最重要的象征：教育可能是唯一的慢解药。"},{"t":"ol","items":["人族权力的核心矛盾"]},{"t":"p","s":"人族权力戏的“脏”不在贪，而在程序。"},{"t":"p","s":"沈聿相信礼能护人。"},{"t":"p","s":"沈阶相信删能护史。"},{"t":"p","s":"宋判相信数据中立。"},{"t":"p","s":"韩朔相信守边即忠。"},{"t":"p","s":"每个人都能为自己找到体面的理由。"}]},{"title":"06.3 妖族十七氏与氏老会","blk":[{"t":"ol","items":["妖族权力的整体特征"]},{"t":"p","s":"妖族权力建立在血统、煞脉、氏籍和共同生活的猎场之上。"},{"t":"p","s":"氏籍决定一个妖族在氏族内部的位置，也决定其能否参与氏族事务、继承资源、获得庇护。"},{"t":"p","s":"煞脉深浅是氏族内部判断尊卑的重要依据。"},{"t":"p","s":"妖族并非一个由幽都完全统治的统一国家。十七氏共同参与氏老会，但各氏仍有自己的利益、历史和生存方式。"},{"t":"p","s":"北境部落不认幽都，只认寒灵。它们与幽都的关系更接近长期协商，而非绝对服从。"},{"t":"ol","items":["氏老会的权力机制"]},{"t":"p","s":"氏老会驻幽都，由十七氏共同议事。"},{"t":"p","s":"其权力主要依靠四种机制："},{"t":"table","head":["机制","权力作用"],"rows":[["血誓","维系氏族共同体，建立忠诚与约束"],["氏籍","决定身份、继承、资源和保护资格"],["影戏","传播氏族立场，塑造共同记忆与舆论"],["猎场","控制资源、食物、迁徙与经济关系"]]},{"t":"p","s":"妖族的政治动员不依靠统一行政命令，而依靠血仇、氏族责任和共同生存压力。"},{"t":"ol","items":["重要氏族"]},{"t":"table","head":["氏族","方位与职能","代表人物","公开立场","真实动机与软处","终局"],"rows":[["鬼豹氏","善潜行、突袭，眉心有一竖氏纹","老疤","沉默","唯一坚持白芜并非有罪，却不敢公开说出口","复猎场"],["蜃蛟氏","河海交界，善驭水与雾","蜃无涯","血仇、主战","经营仇恨，却不真正相信仇恨；害怕密库证明鬼豹氏无罪","被放逐，走旧航线"],["烛阴氏","司影与记","影婆","不表态","历代秘密收容混血儿，噬轲幼年旧衣由她塞入","承认旧衣，噬轲回赠"],["雪罴氏","北境部落，凉凌一带","北境猎首","不认幽都，只认寒灵","对血仇冷感，认为冻土没有仇恨的燃料","入氏老会共议"]]},{"t":"p","s":"已点名四氏：鬼豹氏、蜃蛟氏、烛阴氏、雪罴氏。"},{"t":"p","s":"其余十三氏：暂不命名，作为留白。正文可提“十七氏”总数，可写“某某氏”作为功能性提及，但不进入设定集正式名单，留待补编二。"},{"t":"p","s":"命名规则（防走味）：妖族单名+氏；氏名多带“影、煞、幽、雪、蛟、豹、烛、黑”等字；不出现与已点名四氏同字根的新氏名。"},{"t":"p","s":"功能位预留：十三氏中至少应有——① 与蜃蛟氏争主战权的第二大河海氏；② 与雪罴氏对立的南境暖地氏；③ 司“影戏”传承的氏；④ 司“煞植”种植的氏；⑤ 与鬼豹氏有旧怨的氏。不命名，只留功能位，写作时按需调用，不提前锁死。"},{"t":"ol","items":["妖族权力人物"]},{"t":"p","s":"蜃无涯：主战派的经营者"},{"t":"p","s":"蜃无涯并不完全相信自己对外宣扬的仇恨。"},{"t":"p","s":"他需要白芜之仇，因为这件事能够凝聚十七氏、维持蜃蛟氏的政治地位，也能将噬轲塑造成共同仇恨的象征。"},{"t":"p","s":"他真正害怕的不是战争结束，而是密库证明鬼豹氏无罪。"},{"t":"p","s":"如果仇恨失去依据，他就必须重新回答：蜃蛟氏靠什么维持自己的位置？"},{"t":"p","s":"老疤：沉默的鬼豹氏氏老"},{"t":"p","s":"老疤是唯一坚持白芜并非那种人的人。"},{"t":"p","s":"但他不敢说出口。"},{"t":"p","s":"他的沉默不是不在乎，而是知道公开真相可能导致鬼豹氏内部进一步分裂，也可能让更多孩子被卷入氏族仇恨。"},{"t":"p","s":"影婆：烛阴氏的收容者"},{"t":"p","s":"影婆不公开表态，却长期秘密收容混血儿。"},{"t":"p","s":"噬轲幼年时的旧衣由她留下。"},{"t":"p","s":"她不试图推翻整个氏族秩序，而是用最小的行动为那些无法进入氏籍的人留下活路。"},{"t":"p","s":"北境猎首：不参与仇恨的人"},{"t":"p","s":"雪罴氏不认幽都，只认寒灵。"},{"t":"p","s":"他们对“白芜之仇”的冷感，并非不懂仇恨，而是生存环境让他们更重视现实资源。"},{"t":"p","s":"冻土里没有仇恨的燃料。"},{"t":"ol","items":["妖族权力的核心矛盾"]},{"t":"p","s":"妖族权力戏不写“野蛮”，而写冷。"},{"t":"p","s":"老疤的沉默，是为了让氏族中的孩子继续活下去。"},{"t":"p","s":"影婆的旧衣，是对血统制度的无声抵抗。"},{"t":"p","s":"雪罴氏的冷感，是对被制造出来的仇恨保持距离。"},{"t":"p","s":"蜃无涯的主战，是对自身权力失去依据的恐惧。"},{"t":"p","s":"混血者不进入氏籍，不是因为氏籍册上写着禁止，而是因为册子里根本没有“混血”这个字。"}]},{"title":"06.4 灵族三支与三老","blk":[{"t":"ol","items":["灵族权力的整体特征"]},{"t":"p","s":"灵族的权力并非由单一王权统治，而是由三支共同维系。"},{"t":"p","s":"三支各自掌握不同领域："},{"t":"p","s":"守脉： 掌握落珂境灵脉与净血事务。"},{"t":"p","s":"守档： 掌握涿光境密档与历史记录。"},{"t":"p","s":"司祭： 掌握赤华境星象、祭仪与祭祀秩序。"},{"t":"p","s":"三支互不统属，三老由各支推举一人组成。"},{"t":"p","s":"灵族的权力特点是高度重视秩序、仪式与历史连续性。它不一定依赖直接的行政命令，而是通过档案、祭仪、血统和礼制，决定什么可以被承认，什么必须被封存。"},{"t":"ol","items":["琴议制度"]},{"t":"p","s":"灵族重要事务通过琴议表态。"},{"t":"p","s":"琴议不是普通的投票制度，而是一种以琴音表达立场的议事方式："},{"t":"p","s":"发声代表表态。"},{"t":"p","s":"不同音律代表不同意见。"},{"t":"p","s":"沉默代表弃权。"},{"t":"p","s":"闭琴可以表达拒绝参与，也可能成为一种政治态度。"},{"t":"p","s":"琴议的特殊之处在于：沉默并不意味着没有意见，只意味着意见没有进入正式记录。"},{"t":"ol","items":["灵族权力人物"]},{"t":"table","head":["支系 / 职位","人物","公开立场","真实动机与软处","终局"],"rows":[["三老之首、主封存","璇玑","不可公开周期","不贪财，害怕公开周期意味着鲲鹏会衰、灵族存在意义崩塌","不悔改，只老去"],["守脉","泠岫","守脉","一〇七年献血者；在名录上偷偷将沈聿、白芜并排","成为历史证物线索"],["守档首座","听澜","最忠诚","告密者之子，靠父亲告发聆霜上位；最怕档案见光","因档案中也有自己的名字而崩溃"],["守档","素玦","闭琴三十年","当年沉默的第三方，怀疑真相却没有发声；知第三抄本下落","开琴一次"],["守档一脉暗护者","珩鸣","暗中保护守档一脉","当年主张公布却被否决，百年来暗中保护守档一脉","主政"],["首任言档者","巽宁","器灵、替身","心口有旧痕；本器改弦之谜；终卷前不得自称巽宁","入缄廊，成为“活的档”"]]},{"t":"ol","items":["守档一脉的制度变化"]},{"t":"p","s":"聆霜案之后，守档一脉遭到清洗和改组。"},{"t":"p","s":"新的规矩被确立："},{"t":"p","s":"只守档，不言档。"},{"t":"p","s":"守档人一生不许阅读自己所守的档案。"},{"t":"p","s":"这一规定将档案管理与历史解释权彻底分离：守档人负责保护材料，却不被允许解释材料；他们可以知道档案存在，却不能决定档案意味着什么。"},{"t":"p","s":"缄廊，也就是档窖，需要三老琴印共同开启。"},{"t":"p","s":"这种制度看似避免了个人篡改历史，实际上让守档一脉成为历史的看守者，却失去了为历史作证的权利。"},{"t":"p","s":"终局设立“言档者”，允许守档人开口。"},{"t":"p","s":"巽宁成为首任言档者。"},{"t":"p","s":"守档一脉制度沿革时间线：聆霜案后至终局"},{"t":"table","head":["时间","事件","制度变化"],"rows":[["潮历一〇七年八月","聆霜自沉，尸身不获","守档一脉被清洗；三老问责"],["一〇七年九月","三族上层阅看伪本，确认“三方一致同意封存”","守档一脉改组启动"],["一〇七年末","听澜之父告发聆霜“调包”，升任守档首座","立“只守档，不言档”；守档人不得读自己所守之档；缄廊需三老琴印并启"],["一〇八—二〇六年","听澜任首座近百年；珩鸣暗中护守档一脉","守档一脉成为“只保存、不解释”的封闭系统；琴夜党在民间萌芽"],["二〇六年","守档末裔（巽宁所附之身）殁于渡海","守档末裔一脉断绝；巽宁以器灵身份附身"],["二〇七年","巽宁受灵族礼遇与监视；听澜奉命监视","守档制度出现“活着的矛盾”：一个器灵顶着守档末裔的名字活着"],["卷四","素玦开琴；听澜崩溃","“只守档，不言档”第一次被公开质疑"],["卷六","珩鸣主政；设“言档者”；巽宁首任","守档人可开口；缄廊琴印制度保留，但解释权不再归三老独占"]]},{"t":"p","s":"听澜之父告发聆霜一事，不是公开审判，是密告三老；因此听澜的“告密者之子”身份在灵族内部半公开——上层知道，下层不知。"},{"t":"p","s":"珩鸣“暗中保护守档一脉”的方式是不撤销缄廊编制、不裁守档祭户、不追查守档人私藏抄本；他不公开对抗璇玑，只让守档一脉“饿不死”。"},{"t":"p","s":"巽宁成为言档者，不是恢复聆霜的位置；聆霜是“言档被清洗”，巽宁是“新设言档”。前者是旧职，后者是新制。"},{"t":"ol","items":["凡灵与器灵的身份差异"]},{"t":"table","head":["类型","身份特征","社会地位"],"rows":[["凡灵","无琴籍","可以居住，但不能参与议事"],["器灵","有身无籍，附于逝者之身，借名而活","受到礼遇，也受到监视"]]},{"t":"p","s":"巽宁是器灵。"},{"t":"p","s":"她拥有身体，也拥有被他人承认的身份外观，但她的身份并不完全属于自己。"},{"t":"p","s":"她受到灵族礼遇，同时受到灵族监视。作为守档人末裔，她的言行始终处于观察之下。"},{"t":"p","s":"这使她成为灵族制度最矛盾的存在：她被赋予了言档者的职责，却也是一个长期没有完整身份自主权的存在。"},{"t":"ol","items":["灵族权力的核心矛盾"]},{"t":"p","s":"灵族权力戏的“傲”是一种防御。"},{"t":"p","s":"他们最害怕的不是死亡，而是自己所维护的秩序失去意义。"},{"t":"p","s":"璇玑害怕公开周期意味着灵族存在理由崩塌。"},{"t":"p","s":"听澜害怕档案揭露自己与父亲的关系。"},{"t":"p","s":"素玦知道某些事情不是真的，却用三十年的闭琴避免再次说出自己不相信的话。"},{"t":"p","s":"珩鸣相信守档不应意味着永远沉默。"},{"t":"p","s":"巽宁则代表一种新的可能：档案不仅可以被保存，也应该被允许说话。"}]},{"title":"06.5 碧海洲·蜃市共管权力","blk":[{"t":"ol","items":["蜃市的社会性质"]},{"t":"p","s":"蜃市不是三族共同建立的正式行政区，而是长期贸易、迁徙和人口流动形成的特殊自治空间。"},{"t":"p","s":"它没有传统意义上的官府，也没有单一统治者。"},{"t":"p","s":"蜃市依靠桥议、桥禁、牙人、船帮和行会维持秩序。"},{"t":"p","s":"它最重要的制度原则是："},{"t":"p","s":"过桥不问名。"},{"t":"p","s":"在蜃市长桥之上，不问族籍、不问名讳，只称“客”。"},{"t":"p","s":"这条规矩早于百年前冤案。冤案发生后，它被重新写成不可违背的铁律。"},{"t":"p","s":"蜃市人见过名字如何变成刀，因此不愿意让名字成为过桥的条件。"},{"t":"ol","items":["桥议制度"]},{"t":"p","s":"每月初一，三族各出三名桥老，在桥心议事。"},{"t":"p","s":"决议刻在桥栏上，作为蜃市共同遵守的规则。"},{"t":"p","s":"桥议并不拥有强大的武力，其权威来自所有参与者对持续贸易的依赖。"},{"t":"p","s":"桥禁是蜃市唯一的共同律法，也是三族少数能够长期遵守的规则。"},{"t":"p","s":"桥议共九席：人族三席、妖族三席、灵族三席。"},{"t":"p","s":"三族首席桥老：人族铁算盘、妖族灰嫂、灵族哑琴。三人是长期出现的核心群像，固定席位，不随月轮换。"},{"t":"p","s":"其余六席：每族另两席由本族桥老推举，按月轮值或按议题指派，不固定人名，留给后续剧情与群像调用。"},{"t":"p","s":"议事规则：九席到齐方可开议；不足九席为“流议”，只记录、不决议。桥禁相关事项需九席中至少七席同意；日常通商事项五席即可。"},{"t":"p","s":"终局扩席：卷六桥议增设无籍者三席，九席变十二席；铁算盘、灰嫂、哑琴仍为三族首席。无籍者三席不归三族，由桥下短工、无牌客、夜市掮客推举。"},{"t":"ol","items":["蜃市权力节点"]},{"t":"table","head":["权力节点","人物 / 机构","权力来源","公开诉求","软处与秘密","终局"],"rows":[["桥议","三族各三名桥老","桥禁、惯例","维持通商","谁都不愿先破坏长期形成的规矩","增设无籍者三席"],["人族桥老","铁算盘","管账","账目清楚、欠债要还","账本里也有自己的欠","桥议扩席"],["妖族桥老","灰嫂","管影、掌握夜间消息","寡言、维持秩序","知道夜里谁来过","桥议扩席"],["灵族桥老","哑琴","管音","维持桥议传统","素玦弟子后人，师承琴音是聆霜死前传下的一段","交出最后一把钥匙"],["牙人","何三筏","情报、兑换、桥价","表面中立","收藏所有消息，却不收藏结论；无相失踪前夜见过他","交出航路，牙人上层失势"],["船帮","半楷","航线与运输","不问客籍，只问给不给钱","用生意暂时消化偏见","航线民用化"],["唱证人行会","唱证人","愿约簿、信誉记账","记录口头之诺","处决日拒绝唱价，百年来唯一一次罢工","终局唱三史、唱空白页"],["底层摊贩","有牌摊贩、无牌客","牌照、夜市","寻找活路","夜市是三族消息最灵通的地方","无籍者获得议事席"]]},{"t":"ol","items":["桥价制度"]},{"t":"p","s":"牙人每日在桥心挂牌，根据当日三族货物数量、供需和兑换情况确定兑换率。"},{"t":"p","s":"桥价一日三变。"},{"t":"p","s":"因此蜃市有一句俗谚："},{"t":"p","s":"“桥上无隔夜的钱。”"},{"t":"p","s":"桥价不仅是商业机制，也是蜃市的权力机制。"},{"t":"p","s":"掌握兑换率的人能够影响货物流向，掌握航线的人能够影响商人和船帮的选择，掌握消息的人则能提前判断市场变化。"},{"t":"p","s":"牙人不必拥有官职，也能拥有实际影响力。"},{"t":"ol","items":["蜃市的底层社会"]},{"t":"p","s":"蜃市不是一个人人平等的地方。"},{"t":"p","s":"有牌摊贩可以获得相对稳定的经营位置，无牌客只能在夜市寻找机会。"},{"t":"p","s":"三族身份偏见并未消失，只是在商业利益的约束下暂时被压住。"},{"t":"p","s":"这里存在："},{"t":"p","s":"靠牌照谋生的固定摊贩。"},{"t":"p","s":"靠夜市交换消息的无牌客。"},{"t":"p","s":"依靠航线吃饭的船工。"},{"t":"p","s":"为三族商人担保的牙人。"},{"t":"p","s":"负责记录口头契约的唱证人。"},{"t":"p","s":"在桥下寻找短工的逃户与混血者。"},{"t":"p","s":"蜃市最重要的社会特征是：它允许人们在不完全承认彼此身份的情况下，暂时共同生活。"},{"t":"ol","items":["蜃市权力的核心矛盾"]},{"t":"p","s":"蜃市权力戏写“软规矩怎么管硬人”。"},{"t":"p","s":"桥禁不是靠军队维持，而是靠每个人都知道：明年还想做买卖。"},{"t":"p","s":"但当利益无法继续维持秩序时，蜃市也可能出现危机。"},{"t":"p","s":"它最终增设无籍者三席，不意味着偏见已经消失，而是意味着那些长期被排除在议事之外的人，终于获得了参与制定规则的资格。"}]},{"title":"06.6 跨族暗线与“合谋无主”","blk":[{"t":"ol","items":["潮汐档案的秘密"]},{"t":"p","s":"作者层面的全知设定："},{"t":"p","s":"三族上层都曾接触过潮汐档案，并确认衰潮属于自然周期。"},{"t":"p","s":"他们没有公开这一事实。"},{"t":"p","s":"这不是一个由某个幕后人物策划的完整阴谋，而是一次跨越三族、持续百年的集体沉默。"},{"t":"p","s":"每一方都拥有自己的理由，每一方都只需要向前推一步，就足以让谎言继续存在。"},{"t":"ol","items":["三族各自的沉默"]},{"t":"table","head":["族群","权力人物","行为","沉默的理由"],"rows":[["灵族","璇玑","主张封存","公开周期意味着鲲鹏衰落，灵族的存在意义受到动摇"],["灵族","珩鸣","主张公布但被否决","无法改变三老决策，只能暗中保护守档一脉"],["灵族","素玦","怀疑却未发声","知道真相可能是假的，却不愿再次参与制度性沉默"],["灵族","听澜之父","告发聆霜","通过告发换取自身与家族的安全"],["人族","裴照","经手第一份抄本","知道材料存在，却没有推动公开"],["人族","沈阶","删改实录","认为删改能够维护历史秩序"],["人族","宋判","压制周期数据","维护阵师行会的技术权威"],["人族","韩朔","借边患请军费","将持续冲突转化为军镇利益"],["妖族","蜃无涯","经营白芜之仇","依靠仇恨凝聚十七氏"],["妖族","老疤","保持沉默","不敢公开替白芜翻案"],["妖族","影婆","收容混血儿","在氏族制度之外保留活路"],["妖族","雪罴氏","对仇恨保持距离","不愿让幽都的政治议题取代北境现实生存"]]},{"t":"p","s":"潮汐档案接触权限：三级权限，无人全知"},{"t":"table","head":["层级","权限内容","持有人","知道什么","不知道什么"],"rows":[["一级·全本+附录+调包","冰弦玉版真本（随聆霜沉海）","无人完整持有","——","聆霜之外，无人同时知道“周期为真”与“上呈本是伪本”"],["二级·全本+附录（伪本）","上呈三老核验的抄本（附录被聆霜改写为“三方一致同意封存”）","灵族三老（璇玑主封存； 珩鸣当年阅看； 素玦疑之未言）； 人族裴照（经手第一抄本）； 妖族氏老会主事（密库藏第二抄本， 蜃无涯未开）","知道“衰潮为周期”与“三方默许封存”","不知道附录被改写；不知道真本沉海；不知道聆霜调包"],["三级·全本无附录","第一抄本（羲和帝宫夹壁，缺附录）","卷三取出者（鸣可线经手）； 沈阶知道存在但未全读","知道“周期为真”","不知道“三方默许封存”的具体条款；不知道调包"],["四级·数据/片段","测灵仪周期曲线（宋判压下）； 守档零散抄件（素玦知第三抄本下落但未言）； 愿约簿分簿（罗半帆祖上收购）","宋判、素玦、罗半帆、何三筏（只知有消息，不知内容）","各自掌握片段","拼不出全貌"],["五级·只知“有档案”","听澜之父、韩朔、老疤、影婆、闻钟（藏《浊净同源考》抄本，非档案本身）","知道“上层有东西瞒着”","不知具体内容",""]]},{"t":"p","s":"“三族上层各自知道一部分，且都以为别人知道得比自己多”。这正是“合谋无主”的信息基础——没有人需要全知，只需要各推一步。"},{"t":"p","s":"聆霜调包之所以成功，是因为她利用的正是二级权限者之间的信息差："},{"t":"p","s":"灵族三老以为人族和妖族也同意了，人族以为灵族和妖族也同意了，妖族以为另外两族也同意了。三方都以为自己只是“跟随共识”，没人知道共识是伪造的。"},{"t":"p","s":"蜃无涯不敢开密库，所以他连二级权限都没行使；他的“经营仇恨”建立在主动不确认之上。"},{"t":"ol","items":["外部参与者"]},{"t":"table","head":["人物","行为","作用"],"rows":[["无相","废阵、收集证物","不直接参与权力中心，却留下关键证物"],["何三筏","收集消息，不收藏结论","连接三族与蜃市的信息流"],["唱证人","保存愿约簿和空白页","让被制度忽略的承诺仍然存在"],["哑琴","保存末页琴音","留下无法通过文字完整记录的证据"],["闻钟","藏禁书三十年","让被禁止的知识得以延续"],["闻铃","成为新守档在人族的第一个抄手","为新的历史记录机制提供入口"]]},{"t":"ol","items":["“合谋无主”的四步机制"]},{"t":"p","s":"第一步：自然层——衰潮发生。"},{"t":"p","s":"大衰潮属于自然周期，祭仪必然失败。"},{"t":"p","s":"第二步：制度层——失败必须有人负责。"},{"t":"p","s":"三族都无法接受祭仪失败只是自然规律，因为这会动摇各自的制度解释与政治合法性。"},{"t":"p","s":"第三步：利益层——各方各推一步。"},{"t":"p","s":"有人封存，有人删改，有人压制数据，有人经营仇恨。"},{"t":"p","s":"没有任何一个人必须独自承担全部责任。"},{"t":"p","s":"第四步：记忆层——仇恨成为常识。"},{"t":"p","s":"一百年足以让一段被选择性记录的历史变成社会常识。"},{"t":"p","s":"年轻一代只知道应该恨谁，却不知道仇恨最初从何而来。"},{"t":"p","s":"5.反派不得自认恶"},{"t":"p","s":"蜃无涯独处时，不会想“我是坏人”。"},{"t":"p","s":"他会想：“我不经营仇恨，鬼豹氏就散了。”"},{"t":"p","s":"璇玑不会想“我要欺骗所有人”。"},{"t":"p","s":"她会想：“我不封存，灵族就不是灵族了。”"},{"t":"p","s":"沈阶不会想“我要篡改历史”。"},{"t":"p","s":"他会想：“我不删，书院就散了。”"},{"t":"p","s":"权力人物必须相信自己的理由。"},{"t":"p","s":"他们的可怕之处不是不知道自己在做什么，而是他们能够把自己的利益解释成共同体的生存需要。"}]},{"title":"06.7 权力与偏见的利益层：谁靠偏见吃饭","blk":[{"t":"ol","items":["偏见如何转化为利益"]},{"t":"p","s":"偏见并不只是社会观念。"},{"t":"p","s":"当偏见进入制度，它就能转化为稳定的资源分配方式。"},{"t":"p","s":"谁有资格登记、谁能通行、谁可以继承、谁能进入市场、谁能获得保护，都可能成为权力和利益的来源。"},{"t":"p","s":"三族的偏见并非由所有人平均承担，也不是所有人都从中获利。"},{"t":"p","s":"真正需要追问的是："},{"t":"p","s":"谁依靠偏见维持自己的位置？谁通过偏见获得资源？谁承担偏见带来的代价？"},{"t":"ol","items":["主要利益集团"]},{"t":"table","head":["势力","靠什么获利","偏见如何变现","衰潮时的动作","终局失去什么"],"rows":[["封阳军镇","边患、军费","将妖族蚀田解释为边境威胁，申请增军费","请增军费、设卡","韩朔解甲，关隘改巡检，不再世兵"],["澄鸣书院","修史权、教育与解释权","删改实录，决定谁是正统、谁是罪人","重刊冤案卷，操纵舆论","沈阶交出删改簿，三史馆并立"],["乾时行会","技术垄断、阵契","以技术门槛和测灵仪收费设卡","涨价、压制周期数据","数据公开，行会分裂，阵师转向民用"],["妖族氏老会","血誓、氏籍与猎场","利用白芜之仇凝聚十七氏","影翼大祭，确定盟主","蜃无涯放逐，十七氏改为共议"],["灵族三老","净血道统、祭仪合法性","以净血大祭维持灵族秩序与存在理由","封港、避谈祭仪失败","璇玑老去，设立言档者"],["牙人上层","信息差、兑换与航线","利用桥价、保人和航路信息获利","灾年扩大交易","何三筏交出航路，牙人上层失势"],["唱证人行会","信誉记账","不依靠族群偏见获利，而依靠“记得”维持地位","处决日罢工，拒绝唱价","终局唱三史与空白页，价钱一栏空着"]]},{"t":"ol","items":["偏见的三层结构"]},{"t":"p","s":"第一层：认知偏见。"},{"t":"p","s":"普通人相信自己听到的故事。"},{"t":"p","s":"人族相信妖族天生带煞，妖族相信人族是窃火者，灵族相信净血秩序是维护世界的必要条件。"},{"t":"p","s":"这些认知未必来自亲身经验，而是来自家族教育、书院讲授、氏族影戏和祭仪叙事。"},{"t":"p","s":"第二层：制度偏见。"},{"t":"p","s":"偏见进入制度后，变成登记、通行、婚姻、继承、市场准入和身份认证。"},{"t":"p","s":"一个人即使不相信偏见，也可能在办事时被迫执行偏见。"},{"t":"p","s":"第三层：利益偏见。"},{"t":"p","s":"制度继续运作，就会产生依赖制度的人。"},{"t":"p","s":"军镇需要边患，行会需要技术壁垒，书院需要历史解释权，氏老会需要血仇维系共同体，灵族三老需要净血道统维持合法性。"},{"t":"p","s":"他们不一定主动制造每一次冲突，却有理由不让冲突彻底结束。"},{"t":"ol","items":["本篇的核心立意"]},{"t":"p","s":"查案的过程，就是亲手拆掉这三层结构："},{"t":"p","s":"认知偏见、制度偏见、既得利益。"},{"t":"p","s":"真相当然重要，但更重要的问题是："},{"t":"p","s":"为什么那么多人宁愿相信谎言？"},{"t":"p","s":"因为谎言不仅提供了一个仇恨对象，也提供了身份、利益、秩序和安全感。"},{"t":"p","s":"当一个人必须依靠某种谎言才能维持生活时，真相对他而言就不一定是解脱。"}]},{"title":"06.8 社会群像：制度之外的人如何生活","blk":[{"t":"p","s":"权力结构不能只写朝堂、氏老会、三老和桥议。真正让制度持续运转的，是数量庞大的普通人。"},{"t":"p","s":"他们不一定参与决策，却每天都在承受决策的后果。"},{"t":"p","s":"他们可能维护偏见，也可能利用偏见谋生；可能相信官方历史，也可能只相信邻居的讲述；可能想改变世界，也可能只想让家人平安度过下一次衰潮。"},{"t":"ol","items":["人族社会群像"]},{"t":"table","head":["社会群体","主要生活状态","对现有秩序的态度","叙事功能"],"rows":[["朝堂官吏","依靠官籍、品阶和奏疏维持地位","习惯通过程序解决问题","展现制度如何执行"],["书院士子","通过教育、科名和修史获得上升渠道","容易相信正史，但也可能产生质疑","展现知识如何塑造偏见"],["史馆抄手","抄写、整理、保存官方记录","知道文字可能被删改，却未必敢反抗","展现记录者的困境"],["阵师与工匠","依靠技术、器物和阵契谋生","既依赖技术垄断，也担心垄断限制创新","展现技术权力的基层利益"],["港口商人与船工","依靠航运、贸易、货物运输谋生","更在乎航线能否通行","展现商业如何跨越偏见"],["军户与边民","承担边境防守、征役和战争成本","既需要军队保护，也厌倦长期征役","展现战争的真实代价"],["里甲与保甲","负责基层登记、人口管理和治安","依靠制度获得小范围权力","展现身份制度如何下沉"],["村塾师","在村社教授识字、礼法与基本知识","可能不认同族群隔离","展现教育的缓慢改变"],["逃户与无籍者","靠短工、夜市和临时交易生活","不相信制度会主动保护自己","展现制度之外的生存"]]},{"t":"p","s":"人族社会的关键矛盾："},{"t":"p","s":"人族的普通人未必都认同偏见，但他们的生活往往依赖登记、身份和行政程序。"},{"t":"p","s":"有些人主动维护制度，有些人只是害怕不遵守制度的后果。"},{"t":"p","s":"因此，人族基层最重要的社会问题不是所有人都仇恨妖族，而是很多人已经习惯了按照身份决定如何对待别人。"},{"t":"ol","items":["妖族社会群像"]},{"t":"table","head":["社会群体","主要生活状态","对现有秩序的态度","叙事功能"],"rows":[["氏老与氏族贵族","掌握氏籍、血誓和资源分配","维护氏族秩序","展现血统权力"],["普通氏族成员","依靠氏族获得庇护和资源","既依赖氏族，也受氏族约束","展现共同体的双面性"],["猎团","负责猎场、资源和边界","重视实际生存胜过政治口号","展现妖族经济基础"],["煞植采集者","采集煞植、药材与其他资源","关心煞地环境和交易安全","展现煞地生活"],["影戏艺人","传播氏族故事、历史和舆论","可能被氏族利用，也可能暗中改写叙事","展现文化如何制造共同记忆"],["北境部落","依靠部落自治和寒灵秩序生活","不愿接受幽都统一指挥","展现妖族内部差异"],["被放逐者","失去氏籍与庇护，依靠外部关系生存","对氏族既怀恨又依赖","展现身份剥夺"],["混血者","无法进入氏籍，依靠隐匿、迁徙和私人关系生活","对氏族制度保持警惕","展现制度如何制造不存在的人"]]},{"t":"p","s":"妖族社会的关键矛盾："},{"t":"p","s":"氏族能够提供保护，也能够成为束缚。"},{"t":"p","s":"一个普通妖族可能并不关心幽都的政治斗争，但他需要氏籍才能获得猎场、资源和庇护。"},{"t":"p","s":"因此，即使他不相信血仇，也可能不敢公开反对血仇。"},{"t":"ol","items":["灵族社会群像"]},{"t":"table","head":["社会群体","主要生活状态","对现有秩序的态度","叙事功能"],"rows":[["三老与支系长老","掌握祭仪、档案和灵脉事务","维护三支平衡","展现灵族权力中心"],["守脉者","维护灵脉、净血与相关事务","重视灵脉稳定","展现灵族的资源控制"],["守档者","管理档案、守护缄廊","习惯沉默，不参与解释","展现记忆的制度化控制"],["司祭者","掌握星象与祭仪","相信仪式秩序","展现信仰与合法性"],["琴阁执事","维持琴议与礼仪","服从正式议事规则","展现沉默如何成为制度"],["凡灵","无琴籍，可以居住但不能议事","对权力中心缺少参与渠道","展现身份与居住权的分离"],["器灵","有身无籍，借名而活","受到礼遇，也受到监视","展现身份不完整者的处境"],["祭户","负责祭仪相关事务和日常供给","依赖祭仪秩序谋生","展现制度的基层劳动者"]]},{"t":"p","s":"灵族社会的关键矛盾："},{"t":"p","s":"灵族的秩序并不只是由上层强制维持，也由大量普通人对礼仪、琴议和档案制度的习惯性遵从维持。"},{"t":"p","s":"凡灵可以居住，却不能议事；器灵可以受到礼遇，却不一定拥有完整身份。"},{"t":"p","s":"灵族最值得书写的不是它有多高贵，而是它如何在强调秩序的同时，制造了无法参与秩序的人。"},{"t":"ol","items":["蜃市社会群像"]},{"t":"table","head":["社会群体","主要生活状态","对现有秩序的态度","叙事功能"],"rows":[["牙人","负责兑换、担保、信息与航路","不愿轻易站队","展现利益中立的边界"],["船帮","负责运输和航线","更重视交易能否持续","展现商业对偏见的暂时压制"],["唱证人","记录口头承诺与信誉","重视承诺是否被记住","展现民间记忆"],["有牌摊贩","依靠固定摊位谋生","维护现有经营秩序","展现牌照带来的基层特权"],["无牌客","靠夜市和临时交易谋生","对规则既依赖又警惕","展现无籍者的生存"],["夜市掮客","交换消息、物品与人情","以信息为生","展现民间情报网络"],["桥下短工","靠临时劳动维持生活","只希望不被驱逐","展现最底层的流动人口"]]},{"t":"p","s":"蜃市不是偏见消失的地方，而是偏见必须与利益谈判的地方。"},{"t":"p","s":"同一个人可能白天在桥上不问族籍地与妖族商人交易，晚上回到自己的族群中继续传播对妖族的偏见。"},{"t":"p","s":"这不是人物逻辑矛盾，而是蜃市社会的真实状态：商业合作并不自动带来观念改变。"},{"t":"ol","items":["跨族社会群像"]},{"t":"p","s":"除了三族各自的社会结构，还应当存在一些跨越族群边界的人群。"},{"t":"table","head":["群体","生活方式","社会处境"],"rows":[["混血者","在不同地区隐匿身份、迁徙谋生","三族制度均不承认其完整身份"],["逃户","逃避原有登记和责任体系","容易被视为无籍人口"],["跨族商人","依靠贸易和私人担保活动","需要不断处理身份与通行问题"],["民间医者","为不同族群提供诊疗","可能掌握跨族知识，却缺乏正式认可"],["走唱艺人","通过歌曲、说书和影戏传播故事","可以保存官方史书之外的记忆"],["船工与脚夫","在不同族群的港口和市场间流动","对族群边界有最直接的生活经验"],["禁书收藏者","私下保存被禁止的文本","让知识在制度之外延续"]]},{"t":"p","s":"三主角的政治位置"},{"t":"table","head":["人物","制度位置","被哪套权力排除","在第六篇中的功能","不写什么"],"rows":[["鸣可","无净籍的游方蛊医；纳维族（人族南方支族，被中原视为“半秽之术”）","人族净籍制（附籍/无籍）；蛊医不被正统医籍承认","展示人族内部的第一层排除：她查案前先被自己人排除","不写她的断臂细节、蛊术代价、情感线；这些归第八篇"],["噬轲","妖人混血；鬼豹氏王裔但氏籍册无名","妖族氏籍制（“混血”无写法）；人族净籍制（无籍）","展示制度性不存在：他不是被歧视，是被登记系统跳过","不写他的影行代价、刺杀经历、与无相师承细节；归第八篇"],["巽宁","器灵；附守档末裔之身；有身无籍，借名而活","灵族琴籍制（器灵有身无籍）；守档“只守档不言档”","展示身份不完整者的政治位置：受礼遇，受监视，不能自名","不写她的本器改弦之谜、读弦代价、与素玦/听澜的具体冲突；归第八篇"]]},{"t":"p","s":"三主角在第六篇中不直接参与权力决策；他们是权力结构的受压点与裂缝，不是权力人物。"},{"t":"p","s":"鸣可开骨鸣堂（无籍者行医合法化的民间样本）；"},{"t":"p","s":"噬轲立“过桥人”（混血者互助组织，不入正式氏籍但被桥议承认）；"},{"t":"p","s":"巽宁任言档者（器灵首次进入正式议事记录）。"},{"t":"ol","items":["普通人的三种生存策略"]},{"t":"p","s":"这个世界的普通人面对权力，不应只有服从和反抗两种选择。"},{"t":"p","s":"更常见的是三种生存策略："},{"t":"p","s":"第一种：依附秩序。"},{"t":"p","s":"通过加入氏族、取得净籍、进入行会、获得牌照，换取安全与资源。"},{"t":"p","s":"他们不一定认同制度，但需要制度提供的保护。"},{"t":"p","s":"第二种：利用缝隙。"},{"t":"p","s":"在蜃市交易、通过私人担保、借助亲缘和师承关系、利用不同洲规之间的差异寻找活路。"},{"t":"p","s":"他们不试图改变规则，只希望规则不要完全封死自己。"},{"t":"p","s":"第三种：建立替代关系。"},{"t":"p","s":"通过村塾、民间医馆、私人救助、口头契约和知识传承，建立不依赖正式制度的互助网络。"},{"t":"p","s":"这类人数量不多，也未必能够改变整个世界，但他们是旧秩序开始松动的原因。"},{"t":"ol","items":["社会群像的核心原则"]},{"t":"p","s":"不要让所有普通人都成为主角立场的支持者。"},{"t":"p","s":"一个真实的社会应该存在："},{"t":"p","s":"明知不公平，却仍然依赖现有制度的人。"},{"t":"p","s":"从偏见中获利，却不认为自己有错的人。"},{"t":"p","s":"不相信官方历史，但也不愿承担揭露真相代价的人。"},{"t":"p","s":"只关心家人和生计，不想参与政治的人。"},{"t":"p","s":"曾经受过伤害，却仍然对其他族群抱有善意的人。"},{"t":"p","s":"希望改变制度，却不知道应该从哪里开始的人。"},{"t":"p","s":"社会不是由好人和坏人组成，而是由拥有不同利益、恐惧、记忆和选择的人组成。"}]},{"title":"06.9 各卷权力变化与政治进程","blk":[{"t":"p","s":"权力变化必须跟随主线推进，不能只作为背景新闻出现。"},{"t":"p","s":"每一卷都应该让主角逐渐接触一个新的权力层级，并发现此前看似独立的事件实际上彼此相关。"},{"t":"table","head":["卷目","权力动作","主要人物","结果与剧情钩子"],"rows":[["卷一《霜上鹭》","封阳请增军费；乾时涨价；澄鸣重刊；幽都筹备影翼大祭；落珂封港","韩朔、宋判、沈阶、蜃无涯、璇玑","三位主角被“不该知道的人”找上门"],["卷二《蜃市桥》","桥议、牙人、息日市；澄鸣舆情反转","何三筏、三桥老、沈阶","取得第一抄本，但缺少附录；字条留下“问素玦”"],["卷三《影与名》","幽都氏老会推噬轲上“白芜之仇”祭台；蜃无涯拒绝开启密库","蜃无涯、老疤、影婆","鸣可查断臂真凶；巽宁进入缄廊"],["卷四《空弦》","素玦开琴；第二抄本附录对读；琴夜党推动言档","素玦、听澜、琴夜党","伪本反转；发现哑琴保存的末页琴音"],["卷五《雾障》","雾港、无名木牌、三族通缉与首次合作","无相、何三筏、三位主角","无相木牌留下“阿七”；发现真本沉海处"],["卷六《三尺》","大衰潮封港；璇玑拒绝公布；珩鸣倒戈；三史架建立；韩朔哗变；沈阶自焚未遂；蜃无涯放逐；灵族改革派要求烧毁旧档","璇玑、珩鸣、韩朔、沈阶、蜃无涯、巽宁","通婚禁令废止；户籍松动；确立“可立一名”"]]},{"t":"p","s":"各卷的权力递进逻辑"},{"t":"p","s":"卷一：权力开始收紧。"},{"t":"p","s":"主角最初看到的是边境军费、市场涨价、历史重刊、氏族祭仪和灵族封港等独立事件。"},{"t":"p","s":"他们尚不知道这些行动背后存在共同的历史问题。"},{"t":"p","s":"卷二：发现权力并不只存在于朝堂。"},{"t":"p","s":"蜃市让主角接触到桥议、牙人、唱证人和民间消息网络。"},{"t":"p","s":"他们发现，真正有价值的证据未必保存在权力中心，也可能保存在交易、契约和民间记忆里。"},{"t":"p","s":"卷三：仇恨开始被拆解。"},{"t":"p","s":"妖族的白芜之仇成为政治工具。"},{"t":"p","s":"主角开始意识到，氏族内部并非所有人都相信官方叙事，沉默本身也可能是一种保护。"},{"t":"p","s":"卷四：档案开始说话。"},{"t":"p","s":"灵族守档制度被推到台前。"},{"t":"p","s":"素玦开琴，巽宁逐渐接近言档者的身份，主角开始理解：真正的问题不只是档案被隐藏，而是守档的人被禁止解释档案。"},{"t":"p","s":"卷五：跨族合作成为必要。"},{"t":"p","s":"三族通缉、雾港事件与无相留下的证物，使主角无法继续依赖单一族群的知识和关系网络。"},{"t":"p","s":"他们第一次真正形成跨族合作。"},{"t":"p","s":"卷六：旧秩序失去继续存在的理由。"},{"t":"p","s":"大衰潮到来，原本用于维护三族合法性的解释体系出现裂缝。"},{"t":"p","s":"旧有权力人物并非全部被清算，但他们所依赖的制度理由开始失效。"}]},{"title":"06.10 终局权力重组","blk":[{"t":"p","s":"终局不是建立一个新的统一帝国，也不是让某一族取得最终胜利。"},{"t":"p","s":"它的核心是：三族原有的权力结构开始失去垄断资格，部分制度被拆解，部分权力重新分配，部分历史被允许同时存在。"},{"t":"ol","items":["人族权力变化"]},{"t":"table","head":["原有势力","终局变化","新秩序"],"rows":[["封阳军镇","韩朔哗变后自请解甲","裁军，关隘改为巡检，不再世兵"],["澄鸣书院","沈阶交出删改簿","书院分裂为考据派与守旧派，三史馆并立"],["羲和朝堂","裴照致仕","少帝亲政，设立三族通使，无常任，一年一换"],["乾时行会","测灵仪数据公开","行会分裂，部分阵师转向造钟、造桥和民用测煞仪"],["珩蕴匠门","彩凤鸣岐改弦真相公开","器物标准重新讨论，匠门失去部分解释权"],["扶桑十三行","旧航路与分簿信息公开","航线逐渐民用化，商业关系重新调整"]]},{"t":"ol","items":["妖族权力变化"]},{"t":"table","head":["原有势力","终局变化","新秩序"],"rows":[["蜃无涯","被放逐","主战派失去核心人物"],["氏老会","盟主位仍然空缺","十七氏改为共议"],["鬼豹氏","复猎场","重新获得氏族生存基础"],["雪罴氏","进入氏老会","北境部落开始参与共同议事"],["混血身份","不再被完全排除在社会登记之外","氏籍制度开始松动"]]},{"t":"p","s":"妖族没有建立一个新的绝对权力中心。"},{"t":"p","s":"氏老会仍然存在，但十七氏之间的共同议事逐渐取代单一盟主的权力。"},{"t":"ol","items":["灵族权力变化"]},{"t":"table","head":["原有势力","终局变化","新秩序"],"rows":[["璇玑","不悔改，只老去","旧有封存秩序失去绝对合法性"],["珩鸣","主政","推动守档制度改革"],["素玦","开琴一次","以一次发声结束三十年的沉默"],["听澜","因档案中也有自己的名字而崩溃","守档制度的责任问题被公开"],["守档一脉","设立言档者","守档者可以参与历史解释"],["巽宁","成为首任言档者","进入缄廊，成为“活的档”"]]},{"t":"p","s":"灵族并未彻底放弃自身的祭仪与秩序，但不再允许档案永远只被保存、不被解释。"},{"t":"ol","items":["蜃市权力变化"]},{"t":"table","head":["原有势力","终局变化","新秩序"],"rows":[["牙人上层","何三筏交出航路","信息垄断受到冲击"],["桥议","扩大议事范围","增设无籍者三席"],["船帮","航线民用化","不再完全依赖少数商人控制"],["唱证人","唱三史、唱空白页","民间记忆进入公共叙事"]]},{"t":"p","s":"蜃市没有成为新的统治中心，但它的议事制度发生了最具象征意义的变化："},{"t":"p","s":"过去无籍者只能在桥下谋生，九席变十二席；铁算盘、灰嫂、哑琴仍为三族首席。无籍者三席不归三族，由桥下短工、无牌客、夜市掮客推举。"},{"t":"p","s":"终局废除通婚禁令：不是大赦，是“暂不执行”变成“不再存在”"},{"t":"table","head":["族","废除方式","具体动作","时间","关键点"],"rows":[["人族","朝堂“暂缓执行”","羲和朝堂以“边务未靖，暂缓执行《封阳盟约》第三款”下诏，不称废除，只称“暂缓”","卷六第24章","裴照致仕前推动；少帝亲政后不重申"],["妖族","氏老会“共议默认”","鬼豹氏复猎场后率先不执行；蜃蛟氏被放逐后，十七氏共议不将通婚禁令列入新议程","卷六第24—26章","不是投票废除，是“没人再提”"],["灵族","三老“琴议沉默”","璇玑不表态；珩鸣主政后不重申禁令；琴议记录中该条留空弦一记","卷六第26章","沉默即弃权，弃权即不执行"],["蜃市","桥议“不查”","桥议决议：桥上不问族籍、不查婚书；跨族婚礼可在桥心举行，桥老作证","卷六第24章","蜃市先行，三族跟上"]]},{"t":"ol","items":["三族终局政治原则"]},{"t":"p","s":"终局形成的不是一个统一的政治体系，而是几个新的原则："},{"t":"p","s":"三族可以建立常态化交流，但不建立永久统治关系。"},{"t":"p","s":"历史可以有不同版本，但不能再以删除其他版本的方式维持唯一正统。"},{"t":"p","s":"身份登记不应再以血统和族籍作为唯一依据。"},{"t":"p","s":"技术数据应当接受公开与监督。"},{"t":"p","s":"过去被排除在决策之外的人，应当获得参与规则制定的机会。"},{"t":"p","s":"旧制度的责任需要被记录，而不能仅靠个人退位或死亡解决。"},{"t":"ol","items":["仍在进行的三件事"]},{"t":"p","s":"落珂境仍在下沉。"},{"t":"p","s":"鲲鹏仍不可证。"},{"t":"p","s":"仍有一个村不肯看档案。"},{"t":"p","s":"这三件事不应该在终局被轻易解决。"},{"t":"p","s":"它们意味着：制度改革并不等于世界问题全部消失，历史公开也不等于所有人都愿意接受真相。"}]},{"title":"06.11 权力戏与群像","blk":[{"t":"p","s":"权力人物倒台，不一定要被杀死或彻底击败。"},{"t":"p","s":"更重要的是，他所依赖的制度理由不再成立。"},{"t":"p","s":"韩朔不再需要借边患证明军镇扩张的必要性。"},{"t":"p","s":"蜃无涯无法继续依靠白芜之仇维持氏族联盟。"},{"t":"p","s":"沈阶无法继续用删改实录维持唯一正史。"},{"t":"p","s":"璇玑即使依旧不悔改，也无法再独自决定哪些历史可以被看见。"},{"t":"ol","items":["每个权力人物都要有一个体面的理由"]},{"t":"table","head":["人物","他相信的理由"],"rows":[["韩朔","守边即忠"],["沈阶","删改是为了护史"],["裴照","稳局是为了避免更大的灾难"],["宋判","技术必须由专业人士掌握"],["蜃无涯","经营仇恨是为了维系氏族"],["璇玑","封存是为了保护灵族意义"],["听澜","服从守档规则是自己的职责"]]},{"t":"p","s":"人物不能只是为了作恶而作恶。"},{"t":"p","s":"他们的错误应该来自利益、恐惧、身份认同和对秩序的依赖。"},{"t":"ol","items":["制度暴力"]},{"t":"p","s":"制度暴力不一定需要惨叫、刑罚和公开杀戮。"},{"t":"p","s":"例如"},{"t":"p","s":"佩牌令：没有牌，就不能正常进入城市。"},{"t":"p","s":"禁市令：某些人不能在指定区域交易。"},{"t":"p","s":"通婚之禁：两个相爱的人无法获得合法身份。"},{"t":"p","s":"混血不立名：一个孩子无法进入正式户籍。"},{"t":"p","s":"净籍审查：一个人无法继承财产。"},{"t":"p","s":"档案删改：一个人的死亡被改写成另一种原因。"},{"t":"p","s":"最可怕的不是制度告诉你不准活，而是制度平静地告诉你：查无此人。"},{"t":"ol","items":["权力戏必须落在物件上"]},{"t":"p","s":"抽象权力需要通过具体物件进入故事。"},{"t":"table","head":["物件","象征意义","可能承载的剧情"],"rows":[["桥栏刻字","公共规则","桥议决议、规则改变"],["愿约簿空白页","被遗忘的承诺","唱证人罢工、口头契约"],["删改簿","历史解释权","沈阶的罪责与交代"],["测灵仪数据","技术权力","宋判压制数据的秘密"],["氏籍册缺字","身份排除","混血者不被承认"],["琴印","灵族议事权","缄廊开启、档案公开"],["旧衣","被隐藏的混血身份","影婆与噬轲的关系"],["无名木牌","无籍者留下的证据","无相的行动痕迹"],["三史馆","多种历史并立","终局的历史重建"]]},{"t":"ol","items":["普通人不能只承担背景功能"]},{"t":"p","s":"每个地区都应该有普通人的日常生活："},{"t":"p","s":"人族村庄里，有人忙着缴税，有人抄写族谱，有人教孩子识字。"},{"t":"p","s":"妖族猎场里，有人采集煞植，有人分配猎物，有人等待氏族的庇护。"},{"t":"p","s":"灵族缄廊里，有人修琴，有人守档，有人一生都没有机会参与琴议。"},{"t":"p","s":"蜃市桥下，有人摆摊、搬货、唱证、交换消息，有人始终没有自己的牌照。"},{"t":"p","s":"让读者看到，制度不仅存在于权力人物的谈判中，也存在于每个人每天如何吃饭、工作、迁徙、结婚和埋葬之中。"},{"t":"ol","items":["终局不清算"]},{"t":"p","s":"旧秩序的瓦解不意味着所有责任都被解决。"},{"t":"p","s":"有人失去职位，有人失去权力，有人承认错误，有人始终不悔改。"},{"t":"p","s":"终局不需要所有人都得到报应，也不需要所有受害者都得到补偿。"},{"t":"p","s":"旧制度真正失去的，是继续要求所有人服从它的理由。"},{"t":"p","s":"终局的情绪不是痛快，而是寂静。"}]},{"title":"06.12 本篇核心总结","blk":[{"t":"p","s":"三族权力结构并不是简单的政治制度介绍，而是整部《蜉蝣十洲志》历史矛盾的社会基础。"},{"t":"table","head":["维度","人族","妖族","灵族","蜃市"],"rows":[["权力基础","籍、史、阵","血、煞脉、猎场","净血、档、琴议","桥禁、交易、惯例"],["核心控制","登记与程序","氏籍与血誓","档案与仪式","信誉与利益"],["社会偏见","身份与秩序","血统与氏族","净血与礼制","交易中的临时中立"],["主要受害者","无籍者、逃户","混血者、被放逐者","凡灵、器灵","无牌客、流动人口"],["权力软处","六洲洲规不统一","十七氏内部不齐","三支互不统属","依赖长期贸易"],["终局方向","制度松动、三史并立","十七氏共议","言档者制度","无籍者参与议事"]]},{"t":"p","s":"第六篇最终要回答的不是“谁统治这个世界”，而是：为什么这个世界能够以这样的方式持续一百年？"},{"t":"p","s":"答案是：因为每个族群都需要自己的秩序，每个权力中心都需要自己的理由，每个普通人都需要一种活下去的办法。"},{"t":"p","s":"有人从偏见中获利，有人被偏见伤害，有人明知真相却不敢说，有人不相信真相也不愿改变。"},{"t":"p","s":"而当这些人开始不再需要旧有的理由时，三族延续百年的秩序才真正开始松动。"}]}]}]},{"num":"七","title":"力量与技术体系","raw":"第七篇｜力量与技术体系","zh":[{"title":"07. 灵力、煞气与术法","sec":[{"title":"7.1 灵脉运行原理","blk":[{"t":"p","s":"灵脉＝世界的血管：气息自落珂境（源）涌出，沿洋底与地脉向四周扩散，浓度随距离递减。"},{"t":"p","s":"三个梯度：高灵区（落珂、涿光、赤华）→ 中灵区（中央主岛、乾时、碧海）→ 低灵高煞区（东阴、凉凌、封阳外枯煞滩）。"},{"t":"p","s":"地理即阶层：灵族占高地，人族占平原，妖族居低洼煞地。地图本身就是等级图。"},{"t":"p","s":"可测性：涸尺（水位）、测灵仪（浓度）、井水味（民间土法）。三种测法，三种可信度，三种被收买的可能。"}]},{"title":"7.2 灵力转煞机制","blk":[{"t":"p","s":"抽灵 → 留\"空穴\" → 空穴纳煞。"},{"t":"p","s":"煞不是入侵者，是空出来的位置。故\"驱煞\"只是搬家，\"净化\"是伪命题。"},{"t":"p","s":"煞的三级：浮煞（地表，可散）、沉煞（地脉，需引）、煞穴（大面积真空，百年难复）。"},{"t":"p","s":"一个反讽设定：煞地并非死地。煞地有煞植、煞兽、矿藏，是妖族真正的家园。三族口中的\"贫瘠之地\"，是另一族的沃土。"}]},{"title":"7.3 三条力量铁律（代替境界等级）","blk":[{"t":"p","s":"本书拒绝修仙等级制。强者不强在\"境界\"，强在敢付多少。以下三条，是全书战力的唯一硬约束。"},{"t":"ol","items":["等价损耗：力从身出，无白来的术。任何超出体能的效果，都要从身体、记忆、寿数、或他人身上扣。"]},{"t":"ol","items":["载体上限：人身七窍所容有数。术法的\"上限\"不是等级，是承受力。越强的术，后遗症越像慢性病。"]},{"t":"ol","items":["煞不灭，只转移：任何\"驱煞\"都是搬家。因此没有\"净化世界\"的英雄，只有\"把煞挪到别人家门口\"的胜利者。"]},{"t":"p","s":"战力写作口径：一场打斗的胜负，取决于三件事——谁更肯付代价、谁更懂地形、谁更能忍痛。不取决于谁\"境界高\"。禁止出现\"力量暴涨\"\"突破境界\"这类描写。"}]},{"title":"7.4 蛊术体系（鸣可线）","blk":[{"t":"table","head":["术","效果","代价","叙事用途"],"rows":[["母蛊认血","蛊识主，蛊不离主三里","主伤则蛊乱；主死则蛊散（或反噬）","她不能远行，也不能弃蛊逃生"],["碧落蝶蛊","附人成傀儡，操控其言行","须以施术者骨骼为桥——她的骷髅左臂即母蛊与骨共生的后果","她几乎从不用；用一次，读者就该怕她一次"],["迷梦蜘","毒丝成雾，引人入幻境，吐真","以施术者的记忆为薪——每用一次，她自己忘掉一段","全书最狠的代价：\"证据主义者\"在亲手遗忘自己"],["蛊虫识途","寻物、辨毒、追踪","蛊只认\"气味\"，不认\"是非\"","她能找到证物，但证物不会告诉她谁在说谎"]]},{"t":"p","s":"纳维族的\"以蛊证清白\"：验毒、验亲、验尸三术。族谚：\"蛊可验尸，验不了人心。\""}]},{"title":"7.5 幽冥术与影行（噬轲线）","blk":[{"t":"p","s":"幽冥淬体：以煞气淬炼筋骨，痛如剥皮；一次淬体，三月畏光。"},{"t":"p","s":"影行：把自己拆成影子再拼回去。一日两次为限；第三次必留\"残影\"——影子碎片自行其是，可能替你答应你没答应的事。"},{"t":"p","s":"幽冥突刺：凝煞于爪成刃，瞬移至敌侧。伤害加倍，代价是\"落地时半息不能动\"——刺客的破绽永远在得手之后。"},{"t":"p","s":"幽冥护盾：煞气成盾，可挡刃不可挡光（净光直照即溃）。"},{"t":"p","s":"长年影行的反噬：熟人会慢慢记不清你的脸。噬轲以为是自己\"长得像没人看的人\"，实为术之代价。"},{"t":"p","s":"→ 被遗忘，是偏见的终极形态，也是他弧线的具象敌人：他最终要对抗的不是某个反派，是\"没人记得我来过\"。"},{"t":"p","s":"混血病理：日光下灵煞二气相争即灼痛；情绪激荡则煞纹失控（纹路从眉心蔓至半身）。"},{"t":"p","s":"→ 【关键伏笔】混血体质本身就是\"灵煞同源\"的活体证据，是《浊净同源考》第三论点的证明物。噬轲的身体，就是那本书。"}]},{"title":"7.6 琴音术与器灵族（巽宁线）","blk":[{"t":"table","head":["术","效果","边界"],"rows":[["音波攻守","以琴音扰敌、护阵；可加强同伴之势","需\"静场\"；嘈杂处威力大减；弦断则术止"],["愈和共鸣","与听者灵魂共鸣，愈合伤口；不同琴曲异效","治伤不治心；奏者需同感其痛（她会疼）"],["读弦（听心）","听见对方\"压住的那一音\"——没说出口的话","说谎而自信者，无压音可读。&#x88AB;偏见养大的、满口\"真话\"的百姓，她读不出来"],["读档","以彩凤鸣岐奏开冰弦玉版，重放珂语琴音档案","需本器；奏档极耗，一次三日不能言"]]},{"t":"p","s":"读弦的叙事功能：她的能力对知真说假的上层有效，对深信偏见的民间失效。这逼她直面一个残忍的事实：读心术破不了人心。全书的\"审讯戏\"因此不能靠她一招解决。"},{"t":"p","s":"器灵族通用规则【提案】："},{"t":"p","s":"器有主：器灵依附于本器，本器毁则灵散。"},{"t":"p","s":"名有魂：器灵需借\"名\"而行世——故必附逝者之身，替其解心结、超度之，而后代其活下去。"},{"t":"p","s":"久用开灵：器物被长期以情使用，方生器灵（故器灵多是琴、剑、镜、钟）。"},{"t":"p","s":"一世一代：一次附身只及一世；身死则灵归本器，待下一次机缘。"},{"t":"p","s":"器语：器灵之间以共振相认，人耳不闻。"},{"t":"p","s":"器冢：器灵族群栖于混沌遗迹\"器冢\"，每代不过十数人——比灵族更稀有的\"活着的器物\"。"},{"t":"p","s":"禁忌：器灵不得\"自择其名\"。一旦自择，即为\"僭名\"，会被同类放逐。巽宁终卷的\"自称\"，就是一次僭名——也是她的成人礼。"}]},{"title":"7.7 器物、阵法与引灵技术","blk":[{"t":"table","head":["器物","规则","叙事功能"],"rows":[["引灵器","阵纹锁灵，灵力是\"借\"不是\"生\"，须还——器物折旧即还灵","人族的繁荣建立在\"借\"上，而借是要还的"],["测灵仪","只测浓度，不测真伪","技术中性，压数据的是人（宋判）"],["封灵阵","以阵断一地之灵，军用禁术——\"让一地无灵可引\"的制度化暴力","无相废的就是它；冤案后三族边境遍设"],["三颗佛珠","无相手制：珩蕴老料＋逆封灵阵纹（开阵还灵）；每珠封一段他人交托的记忆；开珠须以开珠者自己的记忆置换","与迷梦蜘同一代价体系——查案者都在用自己换真相"],["彩凤鸣岐","器灵本器；独能奏\"已经消失的声音\"——珂语记史中被抹的空弦，唯它补得全；亦是冰弦玉版唯一的\"读档\"钥匙","巽宁既是钥匙，也是锁"],["冰弦玉版","寒煞冰晶薄片，琴音刻痕遇曲振动即\"重放\"；藏涿光境档窖\"缄廊\"，需三老琴印并启","档案的物理形态＝一段必须被\"演奏\"才能读的录音"]]}]},{"title":"7.8 力量使用的代价与限制","blk":[{"t":"table","head":["术","上限","代价","恢复"],"rows":[["迷梦蜘","一次一人，雾域三尺","遗忘一段自身记忆","不可恢复"],["碧落蝶","一人，需近身","骨桥磨损，左臂剧痛","三日"],["影行","一日两次","第三次留残影；长期\"被遗忘\"","不可逆"],["幽冥淬体","一次一炷香","三月畏光，情绪失控","半年"],["音波攻守","需静场","弦断则术止，指伤","随弦"],["读弦","只读\"压住之音\"","同感其痛，情绪污染","一夜"],["读档","一次一曲","三日不能言","三日"],["开佛珠","一次一颗","以自身记忆置换","不可恢复"]]},{"t":"p","s":"一条总纲：本书所有能力的代价，都指向同一件事——记忆与名字。忘掉自己、被别人忘掉、名字不能立、名字被销。因为全书主题是\"偏见\"，而偏见的第一步，就是不承认对方是一个有名字的人。"}]},{"title":"7.9 各族力量的相互制约","blk":[{"t":"pre","s":"人族（器物·阵）──封灵阵──▶ 妖族（煞术）：断其煞源\n              ▲                        │\n        测灵仪·引灵阵                  │ 煞蚀：腐蚀阵纹，令器\"失重\"\n              │                        ▼\n        灵族（琴音·净血）◀──净光灼身──┘\n              │\n        琴音乱阵（音波共振可破阵纹）"},{"t":"p","s":"人族制妖族：封灵阵（断煞源）、净光（直照）。"},{"t":"p","s":"妖族制人族：煞蚀（腐阵纹）、近身（阵师不善近战）。"},{"t":"p","s":"灵族制人族：琴音乱阵（共振破纹）、断供（净血与光晶）。"},{"t":"p","s":"人族制灵族：器物（灵族不善造物，引灵器全靠人族）、粮铁。"},{"t":"p","s":"妖族制灵族：煞雾（遮音，琴术需静场）、断引路（祭仪无法举行）。"},{"t":"p","s":"灵族制妖族：净光、以及\"不给解药\"（煞毒需灵族灵酿缓解）。"},{"t":"p","s":"结论：三族谁也灭不了谁，所以只能打一百年。这不是平衡，是互相扣着对方的药。"}]}]}]},{"num":"八","title":"人物志","raw":"第八篇｜人物志","zh":[{"title":"08. 核心人物与人物关系","sec":[{"title":"8.1 人物关系图（血脉 · 师承 · 对立）","blk":[{"t":"pre","s":"【冤案一代 · 潮历一〇七年】\n        沈　聿（人族祭司·司仪）═══恋人═══白　芜（妖族行者·鬼豹氏）\n                    │                            │\n                    └────────┬───────────────────┘\n                             │  （二人本定一〇七年十月\"过桥\"）\n                        混血之子（无籍，史书不载）\n                             │\n                        ……两代隐于幽都……\n                             │\n                      ★ 噬　轲（19，妖人混血，刺客）\n        沈　聿 ──旁支──▶ 沈氏祭官旁支（改\"祭\"为\"医\"，隐姓）\n                             │\n                      ★ 鸣　可（17，人族蛊师·纳维族，骷髅左臂）\n        聆　霜（灵族守档人）──玄孙女──▶ 所附之身（殁于二〇六年，21岁）\n                             │                    ▲\n                             │                    │ 附身\n                        哑弟子（无籍，\"哑琴\"之祖）  │\n                             │              ★ 巽　宁（琴龄87，彩凤鸣岐器灵）\n                             └──琴音──▶ 哑　琴（蜃市桥老·管音）\n【师承线】\n        闻　钟（洛华寺住持）──师兄──▶ 无　相／闻　磬（前知客僧，以佛珠为刃）\n              │                              │\n          收养 │                              │ 授艺·留三珠\n              ▼                              ▼\n           鸣　可  ◀──洛华寺第一次交叉──▶  噬　轲\n【权力线】\n  人族：韩朔（封阳军镇）／沈阶（澄鸣书院）／裴照（羲和朝堂）／宋判（乾时行会）／章百工（珩蕴匠门）／罗半帆（扶桑十三行）\n  妖族：蜃无涯（蜃蛟氏·主战）／老疤（鬼豹氏·沉默）／烛阴氏·影婆（藏混血者）／雪罴氏（北境·冷感）\n  灵族：璇玑（主封存）／珩鸣（暗护守档）／素玦（闭琴·知第三抄本）／听澜（守档首座·告密者之子）\n  蜃市：何三筏（牙王）／铁算盘·灰嫂·哑琴（三桥老）／唱证人行会\n【对立轴】\n  蜃无涯 ──利用\"白芜之仇\"──▶ 噬轲（要把他做成旗帜）\n  听　澜 ──监视──────────▶ 巽　宁（怕她\"言档\"）\n  沈　阶 ──删改──────────▶ 鸣　可（她手里的拓片是他最怕的一页）\n  素　玦 ──闭琴──────────▶ 全灵族（他不说，谁也不能说）"}]},{"title":"8.2 三位主角","blk":[{"t":"h4","s":"8.2.1 鸣可（人族线）"},{"t":"table","head":["项","内容"],"rows":[["年龄","十七"],["出身","珩蕴洲纳维族——人族南方支族，世代以蛊入医。蛊医在中原被视为\"半秽之术\"，她在人族内部就先受一层偏见（歧视链上人人有位置）"],["职业","蛊师（游方医）"],["生理（Egri）","左臂毁于幼年，左手呈骷髅状，常年覆布；蛊虫寄于臂骨，以骨为巢"],["社会（Egri）","无净籍的行医者，走到哪都被盘查；靠替人治病换宿"],["心理（Egri）","极度严谨，凡事求证三遍；不轻信，但一旦信了就以命托"],["技能","碧落蝶蛊（附人成傀儡，几乎不用）、迷梦蜘（雾中吐真，以自身记忆为薪）、蛊虫识途（寻物加成）"],["The Lie","\"只要证据足够，世界就会讲道理。\""],["Wound","九岁断臂之夜，她指认凶手，无人信一个蛊医孤女的话——证据齐全，人心不信"],["Want","查清断臂真相，找回家传被夺的半枚拓片"],["Need","明白有些偏见不靠证据驳倒，靠活出反例；为\"拿不出证据的人\"作证"],["弧线","正向弧：从\"证据主义者\"到\"在证据缺席处仍选择相信人\""],["口癖","\"证据呢？\"；思考时用骷髅手背轻叩三下（蛊信的暗号，也是自我安抚）"],["秘密","她九岁前的记忆已经稀薄——她以为是断臂之痛，其实是迷梦蜘在吃她"],["声纹","\"毒走三焦，两个时辰。你骗我可以，别骗我的虫。\""],["冤案勾连","沈聿的旁支后裔（主脉已绝，旁支改\"祭\"为\"医\"隐姓埋名）。断臂之夜被夺的\"半枚拓片\"，正是净血名录散佚的拓片之一——她查的私仇，通向公案"],["终局","留蜃市开蛊医馆\"骨鸣堂\"，收三族学徒；开始\"写自己的档\"（因为她的记忆已薄到需要外置）"]]},{"t":"h4","s":"8.2.2 噬轲（妖族线 ）"},{"t":"table","head":["项","内容"],"rows":[["年龄","十九"],["出身","幽都（凉凌洲地底），鬼豹氏——白芜的玄孙。沈聿×白芜之孙为混血，不入氏籍，其后人隐于幽都最深处"],["身份","妖人混血。战斗时双目全黑、诅咒状纹路蔓延周身；平日唯眉心一纹（鬼豹氏纹，证明他\"半个出身\"）"],["职业","刺客（师承无相）"],["生理（Egri）","影行如鬼豹，日光下久留即灼痛——他的身体本身就是\"两边都不要\"的证词"],["社会（Egri）","氏籍册上没有他的名字。出生高贵（鬼豹王裔），却因混血连\"鱼肉\"都算不上——是砧板上的灰"],["心理（Egri）","隐忍，狠，对善意过敏——谁对他好，他先想对方图什么"],["技能","幽冥突刺（瞬袭）、幽冥护盾；\"瞬移\"是\"把自己拆成影子再拼回去\"，每次都疼"],["The Lie","\"出身即原罪。唯有变强，强到没人敢提我的血，我才算活人。\""],["Wound","幽都氏老会上，有人当众念他\"查无此籍\"；师父无相是唯一叫他名字的人"],["Want","查无相失踪之谜，顺藤摸到自己的身世"],["Need","承认血脉的两半都是自己；明白以刺杀洗雪\"刺客之后\"，只是把偏见倒过来执行"],["弧线","暗线险堕负向（复仇几乎成功时停手），终归正向——\"我不是鱼肉\"的下半句是\"也不做刀\""],["口癖","句尾\"……罢。\"；紧张时摩挲眉心纹；几乎不用敬语"],["秘密","他早已发现自己\"被人记不住脸\"，以为是长相，其实是影行反噬——他怕的不是死，是死后没人记得他来过"],["声纹","\"不去。……怕。怕也得去。\""],["终局","散尽刺术，立混血互助会\"过桥人\"；把一缕残影永远留在落珂境阶前陪两位祖先——他拼不回的那部分自己，去做了守灵"]]},{"t":"h4","s":"8.2.3 巽宁（灵族线 ）"},{"t":"table","head":["项","内容"],"rows":[["琴龄","八十七年（体龄：所附之身殁于潮历二〇六年，年二十一）"],["出身","器灵族——混沌遗迹灵力所养之器灵。彩凤鸣岐古琴（珩蕴洲古匠所制、流落灵族的传世名琴）之灵"],["存在方式","每位器灵附于一位逝者之身，替逝者解心结、超度之，而后代替其活下去。所附之身的主人是灵族守档人一脉末裔（聆霜玄孙女），一心想把涿光境密档带出三岛，殁于渡海"],["职业","琴师（以逝者之名行世）"],["生理（Egri）","身体无恙，唯心口有一道不愈合的旧痕——那是逝者未解的心结；结不解，痕不消"],["社会（Egri）","以逝者之名活着，受灵族礼遇，也受灵族监视——守档人末裔言行受察"],["心理（Egri）","傲娇腹黑，毒舌；爱与灵族小孩论混沌遗迹经书（大人不许谈的话题，孩子可以）"],["技能","音波攻守、愈和共鸣；读弦——能听见对方\"压住的那一音\"；读档（冰弦玉版）"],["The Lie","\"我只是替身。替别人活的人生，我自己不算数。\""],["Wound","第一次\"代替\"一位逝者活下去时，她发现自己开始想替他哭——器灵不该有自己的情绪，她把这当作故障"],["Want","替逝者解开心结：把涿光境密档带出三岛（逝者的遗憾）"],["Need","承认八十七年里她已然长出了一个\"自己\"；替身也是人生"],["弧线","平坦弧带觉醒：她改变了世界（让守档一脉重新\"言档\"），也终于认领了自己"],["口癖","开口先\"啧\"；自称\"予\"；评价事件用琴曲：\"此事，当奏《碎珂》。\""],["秘密","她的本器（彩凤鸣岐）曾在珩蕴匠门被\"改过一次弦\"——改弦者是谁、为什么改，是她八十七年里唯一不敢查的事"],["声纹","\"啧。予不救俗人——不过你这份伤，恰好值得予费半根弦。\""],["终局","入缄廊做\"活的档\"——守档一脉重立后第一任\"言档者\"，心口旧痕在解结之日淡成一枚月牙"]]}]},{"title":"8.3 百年前冤案三人","blk":[{"t":"table","head":["","沈聿","白芜","聆霜"],"rows":[["定位","程序主义者／沉默的共谋","实用主义者／被利用的证词","记录主义者／用谎言保住真相的人"],["性格","守礼、口吃、固执；紧张时更口吃","爽利、爱笑、会讲价；笑时先低头","冷、准、不肯说\"我不知道\""],["信念","礼能护人","路会通","档比人长寿"],["挣扎","知道祭仪已败，仍按礼唱完最后一句","知道自己在替人背罪，仍不辩——因为辩了会牵出沈聿的旁支","知道档案一旦示人，灵族道统即崩；仍选择让真相\"沉下去\"而不是\"被烧掉\""],["他们的错","他以为沉默是守礼","她以为不辩是保护","她以为藏起来就还有一天"],["做对的一件事","在愿约簿上，三年赊账从不赖","临刑前把沈聿的袖口理平","死前把末页琴音传给哑弟子"],["交往细节","学幽语总把\"你影里有火\"说成\"你影里有水\"，她每次都笑，从不纠正","替他在蜃市讲价，讲的价总是少一文——\"少一文，他才还得起\"","只在祭仪上见过他们两次，第二次替他们挡了一次盘查"]]},{"t":"p","s":"写作纪律：这三人不能写成\"完美受害者\"。沈聿的沉默、白芜的不辩、聆霜的隐瞒，都是真实的、可指摘的选择——正因为可指摘，他们才像人。"}]},{"title":"8.4 关键配角","blk":[{"t":"h4","s":"无相／闻磬（全书最重要的影子角色）"},{"t":"p","s":"俗名闻磬，洛华寺知客僧，住持闻钟的师弟。（注意：无相与闻磬是同一人。&#x56;3.0 大纲将三名并列，此处统一为一人两名；\"闻\"字辈另设小师弟闻铃，见下。）"},{"t":"p","s":"转折：化缘蜃市三年，在唱证人处听到太多\"不入史的名\"；偶入禁书库读《浊净同源考》，抄录被判\"谤史\"，逐出寺门。他没辩。"},{"t":"p","s":"自号：\"无相者，无籍之相\"——他后来给混血孤儿起的名字全是\"无名之名\"（阿一、阿二、阿七）。"},{"t":"p","s":"刺术与真相：佛珠为刃，珠身刻逆封灵阵纹。他从不杀人，他废阵——封灵阵一夜一夜地碎，三族通缉\"刺客无相\"。他背了另一种冤案：冤案制造了它自己的影子。"},{"t":"p","s":"失踪：顺愿约簿查到三份抄本下落，托何三筏送出三颗佛珠，只身入赤华雾障寻最后一件物证，生死不明。"},{"t":"p","s":"他留给噬轲的不是刺术，是\"问名字的习惯\"。"},{"t":"h4","s":"洛华寺一脉"},{"t":"table","head":["人物","设定","功能"],"rows":[["闻钟","住持。收养鸣可（因其生母纳维族蛊医曾施药于寺）。替无相藏了一箱书三十年。信条\"庙可破，钟不能哑\"。与沈阶每月一书，论战半生——论敌，也是唯一知道对方软肋的人","鸣可的\"父亲\"；鸣可线与噬轲线的交叉点"],["闻铃","闻钟晚年收的小徒弟，十七岁，话多，记性好，爱抄经【提案·新增】","鸣可的传信人；后期成为\"新守档\"在人族的第一个抄手"]]},{"t":"h4","s":"蜃市四人"},{"t":"table","head":["人物","设定"],"rows":[["何三筏（牙王）","情报掮客，三族上层都欠他。中立＝两边下注；无相失踪前夜与他见过一面。他收藏一切消息，唯独不收藏结论"],["铁算盘（桥老·人族）","管账。一辈子只信两样：算盘和\"欠债要还\""],["灰嫂（桥老·妖族）","管影，夜里的事。寡言，会在桥下给人塞热汤"],["哑琴（桥老·灵族）","管音。素玦弟子，氏籍上不存在的\"哑弟子\"的后人。她师承的那段琴音，正是聆霜死前传下的那一段"]]},{"t":"h4","s":"灵族四人"},{"t":"table","head":["人物","设定"],"rows":[["璇玑","三老之首，主封存者。逻辑：公开周期＝宣告鲲鹏会衰＝灵族存在意义崩塌。他不贪财，他怕\"意义没了\""],["珩鸣","当年主张公布被否；百年来暗中护着守档一脉（巽宁背后不知名的庇护者）"],["素玦","当年沉默的第三方；已\"闭琴\"三十年（自我禁言）；知道第三份抄本真正的下落。他闭琴不是为了守秘，是为了不再说谎"],["听澜","守档首座。告密者之子，靠其父告发聆霜一系上位。表面最忠诚，实际最怕档案见光"]]},{"t":"h4","s":"妖族三人"},{"t":"table","head":["人物","设定"],"rows":[["蜃无涯","蜃蛟氏老，主战派盟主候选。\"白芜之仇\"的最大受益者。他不信仇恨，他经营仇恨"],["老疤","鬼豹氏现任氏老，废了半张脸的老猎手。唯一坚持\"白芜不是那种人\"的人，也是唯一不敢说出口的人"],["影婆","烛阴氏收容混血儿的老妇。噬轲幼年那件旧衣是她塞的。她不说，是因为\"说了，孩子就活不成\""]]},{"t":"h4","s":"基层四枚（不是大人物，是\"被偏见裹挟的人\"）"},{"t":"table","head":["人物","设定","功能"],"rows":[["半橹（蜃市船帮老大）","不问客籍，只问给不给钱——用生意消化偏见","证明\"利益可以暂时压住偏见\""],["老墨（澄鸣刻书匠）","白天刻官史，夜里给儿子讲禁书里的故事","证明\"真相靠私下传\""],["村塾师（若淮）","用三种话教三族孩子同一段课文——他不知道自己已经活在\"后真相时代\"","证明\"教育是唯一的慢解药\""],["不肯看的村老（封阳外）","档案公开后拒看，说\"看了，我儿子就白死了\"","证明\"主题不能被大团圆消解\""]]}]},{"title":"8.5 人物秘密、动机与弧光总表","blk":[{"t":"table","head":["人物","秘密","动机（表层）","动机（深层）","弧光"],"rows":[["鸣可","记忆正在被自己吃掉","查断臂真相","想被相信一次","从\"要证据\"到\"肯作证\""],["噬轲","他正在被世界遗忘","查无相下落","想有一个名字","从\"不做鱼肉\"到\"也不做刀\""],["巽宁","本器被改过一次弦","替逝者解结","想证明\"替身也算活过\"","从\"我是替身\"到\"我就是我\""],["无相","他废阵，从不杀人","找证物","想替\"无籍者\"留一个名","不出场，只留痕"],["沈阶","每月焚一页","护史","护家族","从\"删\"到\"交\""],["素玦","知第三抄本下落","守秘","赎三十年的沉默","从\"闭琴\"到\"开琴\"（终卷唯一一次）"],["蜃无涯","明知白芜冤","争盟主","想被十七氏承认","被放逐，走旧航线"],["听澜","父亲是告密者","保位","怕被看穿","崩溃于\"档案里也有他的名字\""],["璇玑","落珂境已降三尺","护道统","怕\"灵族不再特殊\"","不悔改，只老去"]]}]}]}]},{"num":"九","title":"核心谜团与证据系统","raw":"第九篇｜核心谜团与证据系统","zh":[{"title":"09. 百年冤案解密档案","sec":[{"title":"9.1 冤案真正发生了什么（作者层全知版）","blk":[{"t":"p","s":"纪年说明【提案】：大陆行\"潮汐历\"，以鲲鹏呼吸节律纪年。案发于潮历一〇七年，故事开场于潮历二〇七年，整一百年。"},{"t":"p","s":"潮历一〇七年，大衰潮。"},{"t":"p","s":"元月：鲲鹏之源气息始衰。落珂境灵脉水位三日降一寸。守脉者上报，灵族三老议定：封锁消息，\"恐乱人心\"。"},{"t":"p","s":"二月：边洲井水带煞味，封阳洲首现枯田。人族边军报\"妖族蚀田\"，幽都斥\"人族窃气\"。第一次边境冲突，死者七人。"},{"t":"p","s":"三月：灵族宣布净血大祭照旧举行。名录定人：沈聿、白芜在列。二人在蜃市相识已有三年——此事只记在唱证人的愿约簿上。"},{"t":"p","s":"四月：大祭如期。气息未复，反衰。灵族讳\"祭无效\"，改称\"祭被人窃\""},{"t":"p","s":"五月：蜃市流言四起。三个版本同时成形：人族说\"妖物混入祭仪\"，妖族说\"人族祭司窃气邀功\"，灵族说\"守祭不力，其罪在人妖\"。"},{"t":"p","s":"六月：\"窃气叛仪\"罪名成立，沈聿、白芜下狱。守档人聆霜请调潮汐档案自证\"此乃周期\"，被三老驳回——档案不可示人。"},{"t":"p","s":"七月：三族联席会审。三份供词各按本族礼法书写，彼此矛盾。审了十九天，审出的不是真相，是三族各自\"需要一个罪人\"。"},{"t":"p","s":"八月：处决。沈聿、白芜同日刑于落珂境阶前。二人临刑未辩一句——唱证人的愿约簿上，这一天的记录是空白。聆霜于当夜自沉碧海，尸身不获。"},{"t":"p","s":"九月：涿光境密档：三族上层各自阅看潮汐档案，确认气息骤衰为自然周期。无人提出公布。档案封存，三份抄本分授三家。"},{"t":"p","s":"十月：《封阳盟约》于封阳洲签订：三族划界、隙市限市、通婚之禁。禁令第一条的措辞，出自那桩\"祭仪丑闻\"——从此人妖相恋即是\"叛仪之遗风\"。"},{"t":"p","s":"十一月：边境冲突全面化。幽都主战派以\"血仇\"凝聚十七氏，鬼豹氏首当其冲——因为白芜是鬼豹氏的人。"},{"t":"p","s":"十二月：争战全面爆发。灵族守档一脉因聆霜之死被清洗改组，守档人从此\"只守档，不言档"},{"t":"p","s":"一〇八年—二〇七年（百年）：每约十年，潮汐复衰一次。每一次衰潮，三族上层都重启当年的旧话——\"妖族蚀田\"\"人族窃气\"\"守祭不力\"。潮汐的周期成了仇恨的闹钟。净血名录在乱世中散佚，据传拓片流落蜃市【伏笔·待回收】。"},{"t":"p","s":"真相的三个要点（全书所有谜团的答案）："},{"t":"p","s":"祭仪没有被人窃气。它失败，是因为那年是衰潮年。"},{"t":"p","s":"沈聿与白芜确实\"违规\"了——他们在祭中私改气序半刻，只为多站在一起半刻。他们犯的罪是相爱，不是窃气。"},{"t":"p","s":"三族上层全都知道。他们看过档案，然后各自决定\"不公布\"。这不是一个阴谋，是一次集体沉默。"}]},{"title":"9.2 三族各自掌握的历史版本","blk":[{"t":"table","head":["","人族版《澄鸣实录·冤案卷》","妖族版《影翼谣·血仇章》","灵族版《落珂引·祭仪考》"],"rows":[["起因","妖族混入祭仪，以煞引气，致灵脉枯竭","人族祭司窃气邀功，欲独吞灵脉","守祭不力，其罪在人妖"],["沈聿","\"通妖之祭官\"","\"被妖女所惑的可怜人\"","\"失仪的司仪\""],["白芜","\"以声色惑人之妖物\"","\"为族捐身的行者\"","\"越界的引路者\""],["聆霜","只一句\"守档人失察\"","不载","\"自沉以谢\""],["审判","\"三族共审，情罪俱实\"","\"三族逼杀，血仇不共\"","\"天讨，非人力\""],["战后","删改七处，加\"妖族性狡\"四字","口传成歌，添\"她临刑不哭\"","追销其名，琴史上留空一弦"]]},{"t":"p","s":"同事件异文的使用方式：每卷卷首引三段，读者自行比对。三份都是\"真话\"，只是各删了对自己不利的部分。"}]},{"title":"9.3 三份密档及其下落","blk":[{"t":"table","head":["抄本","载体","藏处","经手人","状态"],"rows":[["第一份","冰弦玉版摹刻","羲和帝宫佛堂夹壁","裴照经手","二〇七年被取出，内容\"完整但缺附录\""],["第二份","冰弦玉版摹刻","幽都氏老会密库","蜃无涯经手","他一辈子没打开过——他怕里面写着鬼豹氏无罪"],["第三份","冰弦玉版原件","下落不明","素玦疑之而未言","真本随聆霜沉海；上呈三老核验的是伪本"]]},{"t":"p","s":"涿光境缄廊：档窖的物理形态——峡壁凿出的长廊，每格一版，光晶照明，需三老琴印并启。守档人日常工作是\"拂尘、校音、补弦\"，不是\"读档\"。守档人一生不许读自己守的档——这条规矩是聆霜案之后立的。"}]},{"title":"9.4 净血名录拓片","blk":[{"t":"p","s":"实体：桑皮纸半枚，朱砂拓，边缘毛糙（撕的，不是剪的）。名录上三十六人名，沈聿、白芜两名并排，其旁有两道指痕（朱砂被汗洇开）。"},{"t":"p","s":"下落：半枚在鸣可家（后被夺＝她 Wound 之夜），半枚下落不明。"},{"t":"p","s":"功能：证明\"执礼三人\"的名单上，沈聿与白芜的名字是并排写的——按礼，司仪与引路的署名应分列两端。并排，是当时写名录的人（泠岫）偷偷替他们留的一句话。"},{"t":"p","s":"回收：鸣可线中后段。她最终发现，夺拓片的人不是仇家，是沈阶派来\"收干净\"的人。"}]},{"title":"9.5 《浊净同源考》","blk":[{"t":"p","s":"形态：非刊本，手抄；封面无题，题在第三页（前两页故意留白，以便\"随时可撕\"）。"},{"t":"p","s":"三论点："},{"t":"ol","items":["净浊同源：煞为灵之空穴，非异物。（→ 拆\"妖=邪\"）"]},{"t":"ol","items":["潮汐有常：衰潮非罪，乃周期。（→ 拆\"冤案\"）"]},{"t":"ol","items":["蜉蝣与鹏同呼吸：三族本为同一批幸存者在灵力梯度上的三次分化；混血之体即同源之证。（→ 拆\"血统\"，故最犯忌）"]},{"t":"p","s":"下落：禁毁；无相抄本随其书箱藏于洛华寺（闻钟替他藏了三十年）。"},{"t":"p","s":"叙事功能：这本书是全书唯一的\"理论武器\"——它不提供证据，它提供看证据的方式。"}]},{"title":"9.6 愿约簿","blk":[{"t":"p","s":"形态：鱼胶桑皮纸，蜡封骑缝，一册三百页；总簿存唱楼，分簿流散。"},{"t":"p","s":"内容：一切口头之诺的记账——买卖、婚约、赊欠、作保、道歉。它是全世界唯一记录\"底层人说过什么\"的东西。"},{"t":"p","s":"关键页：一〇七年敛月十九（处决日）的那一页空白，且被撕去一角；撕角者留下墨渍指痕（鸣可线物证）。"},{"t":"p","s":"三年赊账：一〇四—一〇七年，沈聿与白芜互相唱价二十一笔记账，笔迹两种，字迹越来越像——账目即情书。这也是唱证人后来不敢销账的原因。"},{"t":"p","s":"功能：它是\"官方史书之外的另一部史书\"，也是三线交汇的物证枢纽。"}]},{"title":"9.7 冰弦玉版与空弦","blk":[{"t":"p","s":"冰弦玉版：寒煞冰晶薄片，厚如指节，琴音刻痕遇曲振动即\"重放\"。读档须以珂语琴曲\"演奏\"它——档案不是用来看的，是用来弹的。"},{"t":"p","s":"空弦：珂语记史中，\"潮汐周期\"一段被抹成了一记空弦——不是删掉，是\"留一个音位不弹\"。"},{"t":"p","s":"为什么留空：珂语记史规矩，删记事须留\"空弦\"以示\"此处曾有\"。这是灵族唯一诚实的制度，也是唯一被利用的制度。"},{"t":"p","s":"谁能补全：只有彩凤鸣岐（巽宁本器）能奏\"已经消失的声音\"。"},{"t":"p","s":"补全的代价：读档一次三日不能言；补空弦一次，她要\"以己音填之\"——用自己的一段记忆去填那一记空。"}]},{"title":"9.8 三颗佛珠及其记忆","blk":[{"t":"table","head":["珠","封的记忆","交给谁","开珠代价"],"rows":[["第一珠","蜃市桥下，一个混血孩子被赶出氏籍册的那一天（无相记下的第一个\"无名之名\"）","噬轲","忘掉\"自己第一次杀人的脸\""],["第二珠","赤华雾港，一个灵族守档人临终托付的一句话：\"第三份不在缄廊。\"","噬轲","忘掉\"无相教他刺术的第一课\""],["第三珠","洛华寺书箱的位置（藏《浊净同源考》抄本）","鸣可（由噬轲转交）","忘掉\"母亲哼过的调子\""]]},{"t":"p","s":"设计用意：每开一珠，主角失去一段\"与人有关\"的记忆，换到一段\"与案有关\"的线索。查案的过程，就是把人变成档案的过程。"}]},{"title":"9.9 聆霜调包伪本的真相","blk":[{"t":"p","s":"当年：聆霜请调潮汐档案自证，被三老驳回。她做了守档人最大的禁忌——把自己变成档。"},{"t":"p","s":"调包：上呈三老核验的抄本是伪本（她把附录里三族互相默许的部分，改写成\"三方一致同意封存\"）；真本随她沉入碧海。"},{"t":"p","s":"后果：三族上层九月\"阅看\"的，是她做的假账——他们以为\"大家都同意封存\"，于是安心地不公布。她用谎言保住了真相。"},{"t":"p","s":"镜像：冤案是\"用真相杀人\"，聆霜是\"用谎言救人\"。全书最重要的一次道德颠倒。"},{"t":"p","s":"素玦：当年沉默的第三方，疑之而未言。他闭琴三十年，不是守秘，是不肯再说一句自己知道是假的话。"},{"t":"p","s":"哑琴的琴音：聆霜死前将周期记录的末页琴音传给一个氏籍上不存在的\"哑弟子\"，这段琴音一路传到哑琴（蜃市桥老）。这是全书最后一把钥匙。"}]},{"title":"9.10 证物之间的逻辑关系（一张图）","blk":[{"t":"pre","s":"净血名录拓片（半枚·鸣可家）\n                │ 证明\"二人名字并排\"\n                ▼\n        愿约簿（三年赊账 + 敛月十九空白页 + 撕角指痕）\n                │ 证明\"他们相爱\"且\"有人撕过这一页\"\n                ▼\n        《浊净同源考》（三论点）──── 提供\"看证据的方式\"\n                │\n                ▼\n        三颗佛珠（无相遗物）──── 指向\"三份抄本的下落\"\n                │\n                ▼\n        三份抄本（羲和·幽都·失踪）──── 附录：三方互相默许\n                │\n                ▼\n        冰弦玉版 + 空弦（聆霜伪本 / 哑琴琴音）──── 证明\"周期\"与\"调包\"\n                │\n                ▼\n        真相：祭仪必败，无人窃气，三族皆知而不言\n递进节奏：\n第一层（卷一—卷二）：拓片 + 愿约簿 → 读者知道\"这两个人相爱\"。\n第二层（卷三—卷四）：佛珠 + 两份抄本 → 读者知道\"三族都知道\"。\n第三层（卷五—卷六）：空弦 + 哑琴 → 读者知道\"聆霜调了包\"。\n读者永远比角色早三章知道真相——悬念不在\"是谁\"，在\"知道了之后，他们会怎么做\"。"}]},{"title":"9.11 真相公开的条件与代价","blk":[{"t":"p","s":"三个条件（缺一不可）："},{"t":"ol","items":["物证：三份抄本中至少两份可对读（否则被斥为伪）。"]},{"t":"ol","items":["人证：一个\"活着的高层\"肯开口（素玦开琴 / 裴照致仕前交出抄本）。"]},{"t":"ol","items":["场合：一个三族都在、都不能动手的地方——蜃市长桥（桥禁）。"]},{"t":"p","s":"代价（公开之后才付的账）："},{"t":"p","s":"灵族失去道统（\"光\"不再是光）；"},{"t":"p","s":"人族失去史官权威（沈阶身败）；"},{"t":"p","s":"妖族失去血誓（蜃无涯被放逐）；"},{"t":"p","s":"而三族的普通人，失去的是\"恨了一辈子的理由\"。"}]}]}]},{"num":"十","title":"小说叙事结构","raw":"第十篇｜小说叙事结构","zh":[{"title":"10. 主线剧情与三线结构","sec":[{"title":"10.1 故事开端与核心事件","blk":[{"t":"p","s":"开端（卷一前五章）：三件互不相干的\"小事\"在同一个月发生。"},{"t":"ol","items":["碧海洲，一具\"煞死\"的尸体验出半枚朱砂拓痕（鸣可）。"]},{"t":"ol","items":["幽都，师父失踪满三年，第三颗佛珠裂开一线（噬轲）。"]},{"t":"ol","items":["落珂境，全岛下降三尺；同一夜，巽宁心口的旧痕开始疼（巽宁）。"]},{"t":"p","s":"核心事件（全书发动机）：有人在二〇七年重新开始收集当年的证物。→ 谁在收？不是反派，是无相。他失踪三年，其实一直在收，只是收得太深，深到自己成了\"失踪\"。"},{"t":"p","s":"主线问题（读者追读的动力）："},{"t":"p","s":"表层：谁杀了沈聿与白芜？（答案：没有人，也没有所有人）"},{"t":"p","s":"中层：三族为什么宁可相信谎言？（答案：因为谎言养活着一些人）"},{"t":"p","s":"深层：知道了之后，你怎么办？（答案：三个人各给一个）"}]},{"title":"10.2 三线各自的推进逻辑","blk":[{"t":"h4","s":"鸣可线：私仇与证据"},{"t":"table","head":["阶段","她追什么","她得到什么","她失去什么"],"rows":[["卷一","一具尸体的拓痕","半枚拓片与家传残片同源","拓片被夺（第二次）"],["卷二","谁在收拓片","愿约簿上的三年赊账","她开始怀疑自己记错了事"],["卷三","断臂那夜的真凶","真凶不是仇家，是\"收干净\"的人","母亲哼过的调子（开珠）"],["卷四","沈聿是谁","她是沈聿旁支","九岁前的记忆只剩三幕"],["卷五","怎么让证据被信","证据齐了，人心不信","她几乎忘掉\"为什么要查\""],["卷六","不再靠证据","学会\"为拿不出证据的人作证\"","她接受了\"忘掉也没关系\""]]},{"t":"p","s":"她的核心台词弧线："},{"t":"p","s":"卷一：\"证据呢？\""},{"t":"p","s":"卷三：\"证据在这儿。你们看。\""},{"t":"p","s":"卷五：\"……我忘了。（停顿）不碍事，虫记得。\""},{"t":"p","s":"卷六：\"没有证据。但我信他。\""},{"t":"h4","s":"噬轲线：身世与无相失踪"},{"t":"table","head":["阶段","他追什么","他得到什么","他失去什么"],"rows":[["卷一","无相的下落","第一颗佛珠：一个混血孩子被赶出氏籍册","第一次杀人的那张脸（开珠）"],["卷二","谁在通缉无相","无相\"废阵不杀人\"的真相","他被蜃无涯看中，做成\"血仇的旗帜\""],["卷三","自己的血","他是沈聿×白芜的玄孙","氏老会上被当众\"查无此籍\"（第二次）"],["卷四","第二抄本","密库钥匙；蜃无涯不敢开","他发现自己记不住自己的脸"],["卷五","谁记得他","影行反噬的真相：是术，不是长相","熟人开始认不出他；他差点杀了老疤"],["卷六","怎么留在这世上","一缕残影留在落珂境阶前","他接受了\"被人忘记\"也可以是守灵"]]},{"t":"p","s":"他的核心台词弧线："},{"t":"p","s":"卷一：\"我叫噬轲。\""},{"t":"p","s":"卷三：\"查无此籍。……那就查无此籍罢。\""},{"t":"p","s":"卷五：\"你还记得我姓什么么？\""},{"t":"p","s":"卷六：\"记不住，也不要紧。石头记得。\""},{"t":"h4","s":"巽宁线：守档与自我认同"},{"t":"table","head":["阶段","她追什么","她得到什么","她失去什么"],"rows":[["卷一","心口那道痕为什么疼","所附之身（守档末裔）的遗憾：把档带出三岛","她第一次想替人哭"],["卷二","空弦是谁抹的","珂语记史的\"留空\"规矩","她开始怀疑自己是\"故障\""],["卷三","怎么进缄廊","听澜的监视；琴夜党的拥戴","她被人当成\"旗\""],["卷四","素玦为什么闭琴","\"我不说，因为我曾说错\"","她答应素玦\"不替我说\""],["卷五","补全空弦","用自己的一段记忆填那一记空","她忘了自己是第几次\"代替\""],["卷六","我是谁","首任\"言档者\"；心口痕淡成月牙","她放弃了\"永远做别人\"的安全"]]},{"t":"p","s":"她的核心台词弧线："},{"t":"p","s":"卷一：\"啧。予不救俗人。\""},{"t":"p","s":"卷三：\"予是替身。替身不必有名字。\""},{"t":"p","s":"卷五：\"这一音，予来填。\""},{"t":"p","s":"卷六：\"予名巽宁。不是谁的名字，是予的。\""}]},{"title":"10.3 三线交汇节点","blk":[{"t":"table","head":["节点","位置","形态","交汇物"],"rows":[["第一次·擦肩","卷二第 14 章","三人在蜃市长桥同日过桥，彼此不识；唱证人在愿约簿上把三个名字记在同一页","愿约簿（全书唯一一次\"第四视角\"）"],["第二次·同席","卷三第 8 章","洛华寺：闻钟设一席，鸣可与噬轲同桌，巽宁在门外弹琴不进","无相（闻钟拿出他的旧钵）"],["第三次·对峙","卷四第 26 章","涿光境缄廊外：三人各持一半证据，互相怀疑对方是内鬼","第二抄本"],["第四次·同盟","卷五第 20 章","赤华雾港：三人第一次主动合作，代价是鸣可忘掉一段、噬轲被一人彻底遗忘","第三颗佛珠"],["第五次·同桥","卷六第 22 章","蜃市长桥：三人并肩，把三份史书摊在桥栏上（\"三史架\"）","三史并立"]]}]},{"title":"10.4 关键反转与伏笔回收","blk":[{"t":"table","head":["#","反转","埋点（前置）","揭示（回收）","时差"],"rows":[["R1","沈聿与白芜是恋人","卷一·愿约簿三年赊账（第 9 章）","卷一末·鸣可拼出\"账目即情书\"","读者早 8 章"],["R2","夺拓片的人不是仇家，是沈阶派来\"收干净\"的","卷一·夺拓片者手法太干净（第 12 章）","卷三·第 18 章","同步"],["R3","聆霜调了包——她用谎言保住真相","卷二·第三份抄本\"缺附录\"；卷四·素玦\"我不说我因为曾说错\"","卷四·第 27 章（大反转）","读者早 3 章"],["R4","噬轲\"被遗忘\"是影行代价，不是长相","卷一·半橹第二次见他问\"你是谁\"；卷三·老疤认不出","卷五·第 11 章","读者早 5 章"],["R5","三族上层全都知道（附录）","卷二·两份抄本附录各记\"对方默许\"","卷六·第 6 章","读者早 4 章"],["R6","无相没死，他成了\"无名之名\"","卷三·佛珠里的名字全是\"阿一阿二\"；卷五·雾港有人替所有无名者立木牌","卷六·第 18 章（不给正面出场，只给木牌上的字迹）","读者自行判断"]]},{"t":"p","s":"伏笔总表："},{"t":"table","head":["卷","伏笔","预期回收"],"rows":[["一","净血名录拓片（半枚）","卷三（夺片者）／卷六（并排之名）"],["一","愿约簿敛月十九空白页＋撕角指痕","卷四（撕角者）／卷六（补唱这一页）"],["一","巽宁心口旧痕","卷六（淡成月牙）"],["一","噬轲眉心一纹（半个出身）","卷三（氏老会）／卷六（残影守灵）"],["二","何三筏\"不收藏结论\"","卷五（他交出一条航路）"],["二","哑琴的琴音（师承不明）","卷四（聆霜末页）"],["三","烛阴氏旧衣","卷五（影婆承认）／卷六（噬轲回赠）"],["三","素玦闭琴三十年","卷四（开琴一次）"],["三","彩凤鸣岐\"改过一次弦\"","卷六（改弦者为珩蕴匠门，为\"封灵\"而改）"],["四","落珂境\"三尺\"","卷六（公开危机）"],["五","雾港无名木牌","卷六（无相的\"名\"）"],["五","通语里没有\"回来\"这个词","卷六（终句）"]]}]},{"title":"10.5 各卷剧情安排（六卷·一百八十章）","blk":[{"t":"p","s":"每卷三十章。每卷按\"三幕九拍\"分配：第 1—6 章建制，7—12 章第一转折，13—18 章中段失控，19—24 章至暗，25—30 章收束＋钩子。"},{"t":"h4","s":"卷一《霜上鹭》（潮历二〇七·醒月—汛月）"},{"t":"p","s":"主线：三线开局。"},{"t":"p","s":"建制：验尸得拓痕（鸣可）；第三珠裂（噬轲）；心口疼（巽宁）。"},{"t":"p","s":"第一转折：三人都被\"不该知道这件事的人\"找上门——鸣可被沈阶的人\"请\"去澄鸣；噬轲被蜃无涯召见；巽宁被听澜\"请\"入缄廊外堂。"},{"t":"p","s":"中段失控：蜃市相遇；洛华寺；三人各得一半真相，各自以为别人是敌人。"},{"t":"p","s":"至暗：鸣可拓片被夺（第二次）；噬轲被当众\"查无此籍\"；巽宁被禁足。"},{"t":"p","s":"收束：三人同时决定去涿光境。卷一末章（第 30 章）用唱证人视角：愿约簿上三个名字，写在同一页。"},{"t":"p","s":"钩子：巽宁隔墙听见一记空弦——那一记空弦，是她自己的心跳声。"},{"t":"h4","s":"卷二《蜃市桥》（二〇七·平月—盈月）"},{"t":"p","s":"主线：蜃市三线并行，愿约簿成为枢纽。"},{"t":"p","s":"建制：蜃市全景（桥议、牙人、息日市）；何三筏登场；桥老三人。"},{"t":"p","s":"第一转折：鸣可发现愿约簿上有一页被撕角；噬轲发现有人用\"无相\"的名义在蜃市收货。"},{"t":"p","s":"中段：第 14 章·三线擦肩（唱证人视角）；桥上三人同日过桥，彼此不识。"},{"t":"p","s":"至暗：澄鸣书院重刊《澄鸣实录·冤案卷》，三史异文并置，舆情反转，三线同时被泼脏水。"},{"t":"p","s":"收束：取第一份抄本（羲和帝宫佛堂夹壁），发现缺附录。"},{"t":"p","s":"钩子：附录不在，但夹壁里有一张字条：\"问素玦。\""},{"t":"h4","s":"卷三《影与名》（二〇七·缓月—二〇八·滞月）"},{"t":"p","s":"主线：噬轲回幽都；鸣可回珩蕴；巽宁入缄廊。"},{"t":"p","s":"建制：幽都地底（城无日而明）；纳维族炉城；缄廊外堂。"},{"t":"p","s":"第一转折：噬轲被蜃无涯推上\"白芜之仇\"的祭台；鸣可发现夺拓片者手法太干净；巽宁被听澜逼着\"替灵族说话\"。"},{"t":"p","s":"中段：老疤的沉默；影婆的旧衣；鸣可查断臂真凶（R2 揭）。"},{"t":"p","s":"至暗：鸣可发现自己一直在查的仇人，是\"替家族收干净\"的人——她的仇，是同一桩冤案的余震。"},{"t":"p","s":"收束：幽都密库前，蜃无涯拒绝开门——\"里面若写着鬼豹氏无罪，我这百年怎么算？\""},{"t":"p","s":"钩子：老疤在门外说了一句：\"……其实我记得她的样子。\""},{"t":"h4","s":"卷四《空弦》（二〇八·敛月—眠月）"},{"t":"p","s":"主线：素玦、哑琴、调包。"},{"t":"p","s":"建制：素玦闭琴三十年；哑琴的琴音；琴夜党的\"言档\"运动。"},{"t":"p","s":"第一转折：素玦开口第一句不是真相，是\"我不说，因为我曾说错\"。"},{"t":"p","s":"中段：第二抄本启出，附录对读——三方互相默许（R5 铺垫）。"},{"t":"p","s":"至暗：大反转 R3——上呈三老的是伪本，真本沉海。三族百年\"共识\"是一场骗局，而骗他们的人是受害者。"},{"t":"p","s":"收束：三人缄廊外对峙（交汇三）；素玦第一次开琴，只弹了一个音。"},{"t":"p","s":"钩子：哑琴把那段琴音弹给他们听——末页只有一句：\"若有人听见，请替我说完。\""},{"t":"h4","s":"卷五《雾障》（二〇九·醒月—汛月）"},{"t":"p","s":"主线：赤华雾港、无相下落、代价爆发。"},{"t":"p","s":"建制：雾港（雾是灾也是屏障）；无名木牌；引水人。"},{"t":"p","s":"第一转折：三人第一次真正合作（交汇四）；鸣可开第三珠，忘掉母亲的调子。"},{"t":"p","s":"中段：R4——噬轲发现自己被遗忘；他差点杀了认不出他的老疤。"},{"t":"p","s":"至暗：雾障中三人失散；鸣可的记忆只剩三幕；巽宁补空弦，忘掉\"自己第几次代替别人\"。"},{"t":"p","s":"收束：找到真本沉海处（碧海·落珂境阶前海域），但打捞需要\"三族同意的船\"。"},{"t":"p","s":"钩子：无相的木牌上写着\"阿七\"——是噬轲小时候的名字。"},{"t":"h4","s":"卷六《三尺》（二〇九·滞月—藏月）"},{"t":"p","s":"主线：公开、阵痛、终局。"},{"t":"p","s":"建制：大衰潮至，落珂境下降三尺，封港；蜃市备战。"},{"t":"p","s":"第一转折：璇玑拒绝公布，理由是\"公开了，灵族就不是灵族了\"；珩鸣倒戈。"},{"t":"p","s":"中段：三史架——三方史书并排挂上桥栏（交汇五）；公开当日三份\"核实\"又写出三个版本。"},{"t":"p","s":"至暗：韩朔部哗变；沈阶自焚未遂；蜃无涯被放逐（走当年驱逐鬼豹氏遗孤的旧航线）；灵族改革派要烧尽旧档，巽宁拦下：\"谎言也是档。\""},{"t":"p","s":"收束：三位主角各自落位；不肯看的村；三史并立。"},{"t":"p","s":"终章：蜃市通语新添一词，三族各有写法、读音相同，意为\"回来\"。"}]},{"title":"10.6 章节视角与时间线安排","blk":[{"t":"p","s":"【潮历二〇七·汛月·初七｜碧海洲·蜃市｜鸣可】"},{"t":"p","s":"三线时间差（重要）："},{"t":"p","s":"鸣可线与巽宁线大致同步；"},{"t":"p","s":"噬轲线常落后十天至半月——因为幽都在凉凌洲地底，航程最远。故读者读噬轲线时，常\"已经知道鸣可线后来的事\"。"},{"t":"p","s":"这是刻意的：读者永远比角色多知道一点，悬念因此从\"是什么\"转为\"他们会怎么做\"。"},{"t":"p","s":"三线交叉的三条纪律："},{"t":"ol","items":["同一事件若三线都写，必须三版不同，且三版都不说谎。"]},{"t":"ol","items":["交汇章用\"第四视角\"——唱证人的愿约簿，只记\"谁在何时说了什么价\"，不记心理。"]},{"t":"ol","items":["每五章一次视角切换，切换点必留钩子；禁止在一章内切三个视角。"]},{"t":"p","s":"时间线总表："},{"t":"table","head":["卷","潮历","时长","三线状态"],"rows":[["一","207 醒月—汛月","四个月","三线并行，各自启动"],["二","207 平月—盈月","三个月","三线聚于蜃市，擦肩不识"],["三","207 缓月—208 滞月","约一年","三线分散，各回本族"],["四","208 敛月—眠月","五个月","三线重聚涿光境"],["五","209 醒月—汛月","六个月","三线共赴赤华"],["六","209 滞月—藏月","十个月","三线同桥"]]}]}]}]},{"num":"十一","title":"终局与世界变迁","raw":"第十一篇｜终局与世界变迁","zh":[{"title":"11. 结局设计","sec":[{"title":"11.1 真相公开：不是一场审判，是一次朗读","blk":[{"t":"p","s":"地点：蜃市长桥（桥禁之地，三族都不能动手）。"},{"t":"p","s":"形式：不是审判，是唱证人把愿约簿摊开，从头唱一遍——唱到一〇七年敛月十九那一页空白，全桥静一炷香。"},{"t":"p","s":"然后：三份史书并排挂上桥栏的\"三史架\"。不合并，不裁定，不投票。"},{"t":"p","s":"公开的内容：①祭仪必败（周期）②无人窃气 ③三族上层全都知道 ④聆霜调包。"},{"t":"p","s":"不公开的内容：沈聿与白芜\"私改气序半刻\"这件事——鸣可把它从档案里抽走了。她说：\"他们犯的罪是相爱，不是窃气。这条不用公开。\""},{"t":"p","s":"这是全书对\"真相\"的态度：真相不是全部说出来，是该说的说完，不该说的守住。"}]},{"title":"11.2 三族社会的反应：三波阵痛","blk":[{"t":"table","head":["波次","时间","表现","代表画面"],"rows":[["否认期","公开当日—三个月","三族史官各自\"核实\"，又写出三份不一样的记述","三史架上三层纸，谁也不删谁"],["清算期","三个月—两年","韩朔部哗变，裁军之乱；沈阶欲自焚书院，被弟子抱住腿；蜃无涯被放逐，船走旧航线；灵族改革派要烧旧档，巽宁拦下","烧档的火堆前，巽宁抱着冰弦玉版说：\"谎言也是档。\""],["疲惫期","两年—十年","通婚解禁后第一场跨族婚礼仍被砸；第二年同一家孩子满月酒，全洲的人都来了","世界不是被说服的，是被过日子磨平的"]]}]},{"title":"11.3 权力结构的崩解与重组","blk":[{"t":"table","head":["旧结构","崩解方式","新形态"],"rows":[["封阳军镇（世兵制）","哗变→裁军→韩朔自请解甲，换部曲不咎","关隘改为\"巡检\"，不再世兵"],["澄鸣书院（史学权威）","沈阶交出\"删改簿\"，书院分裂为\"考据派\"与\"守旧派\"","三史馆并立，各修各史，互不删改"],["羲和朝堂（绥靖）","裴照致仕，少帝亲政","设\"三族通使\"，无常任，一年一换"],["乾时行会（技术垄断）","测灵仪数据公开，行会分裂","阵师改行造钟、造桥、造测煞仪（民用）"],["妖族氏老会（血誓）","蜃无涯被放逐，盟主位仍空","十七氏改\"共议\"，鬼豹氏复猎场，雪罴氏入会"],["灵族三老（道统）","璇玑不悔改，只老去；珩鸣主政；素玦开琴一次","设\"言档者\"（巽宁首任），守档人可开口"],["蜃市牙人","何三筏交出航路，牙人上层失势","桥议扩为\"九人桥议\"，加三席无籍者"]]}]},{"title":"11.4 通婚禁令与身份制度的变化","blk":[{"t":"p","s":"通婚禁令：卷六第 24 章废除。废除的方式很\"不英雄\"——不是大赦，是三族各自\"暂不执行\"，三年后无人再提，遂成废文。通婚禁令的消失方式是“行政遗忘”，不是“正义胜利”。"},{"t":"p","s":"户籍：人族净籍制松动，附籍者可应试（三年试行）；妖族氏籍册新增\"混血\"写法（一个字，争了七年）；灵族设\"凡灵议事席\"。"},{"t":"p","s":"名字：\"不立两名\"改为\"可立一名\"——这一条是噬轲争来的。他站在氏老会说：\"我不要两个名字。我要一个能写进册的。\""},{"t":"p","s":"一处不肯改的：混血者仍不得承两产，不随通婚禁令废除而改。世界变好了一点，不是全好。"},{"t":"table","head":["族","废除方式","具体动作","时间","关键点"],"rows":[["人族","朝堂“暂缓执行”","羲和朝堂以“边务未靖，暂缓执行《封阳盟约》第三款”下诏，不称废除，只称“暂缓”","卷六第24章","裴照致仕前推动；少帝亲政后不重申"],["妖族","氏老会“共议默认”","鬼豹氏复猎场后率先不执行；蜃蛟氏被放逐后，十七氏共议不将通婚禁令列入新议程","卷六第24—26章","不是投票废除，是“没人再提”"],["灵族","三老“琴议沉默”","璇玑不表态；珩鸣主政后不重申禁令；琴议记录中该条留空弦一记","卷六第26章","沉默即弃权，弃权即不执行"],["蜃市","桥议“不查”","桥议决议：桥上不问族籍、不查婚书；跨族婚礼可在桥心举行，桥老作证","卷六第24章","蜃市先行，三族跟上"]]},{"t":"p","s":"三年成废文："},{"t":"p","s":"第一年：跨族婚礼仍被砸（民间惯性）。"},{"t":"p","s":"第二年：同一家孩子满月酒，全洲的人都来了（利益与生活磨平）。"},{"t":"p","s":"第三年：三族文书往来中不再出现“通婚之禁”条目；无人宣布废除，但无人再执行。"}]},{"title":"11.5 三位主角的最终命运","blk":[{"t":"table","head":["人物","结局","最后一幕"],"rows":[["鸣可","留蜃市开蛊医馆\"骨鸣堂\"，收三族学徒","她的记忆簿已薄——终章她开始\"写自己的档\"。写到九岁那年，只写下三个字：\"我记得。\""],["噬轲","散尽刺术，立混血互助会\"过桥人\"；把一缕残影永远留在落珂境阶前陪两位祖先","影行代价的闭环：他拼不回的那部分自己，去做了守灵"],["巽宁","入缄廊做\"活的档\"——守档一脉重立后第一任\"言档者\"","心口旧痕在解结之日淡成一枚月牙；她终于肯说\"予名巽宁\""]]},{"t":"p","s":"三人关系：不落爱情俗套。三人共立蜃市新俗\"过桥人\"——每年敛月处决之日，同上长桥，唱一遍愿约簿；唱到那一页空白，全桥静一炷香。"}]},{"title":"11.6 世界的新秩序","blk":[{"t":"p","s":"三史并立：三份史书永久并存，任读者自行比对。叙事结构本身就是答案。"},{"t":"p","s":"三族通使：无常任，一年一换，防\"通使\"变成\"通谋\"。"},{"t":"p","s":"桥议扩大：无籍者获三席——第一次有\"没有名字的人\"坐在议事的地方。"},{"t":"p","s":"未解决的三件事（留白，不解决）："},{"t":"ol","items":["落珂境还在下沉。三尺之后是几尺？没人知道。"]},{"t":"ol","items":["鲲鹏仍不可证。信的人信，不信的人不信。"]},{"t":"ol","items":["仍有一个村不肯看档案。"]}]},{"title":"11.7 最终主题落点与终句","blk":[{"t":"p","s":"主题落点："},{"t":"ol","items":["认知层：三族神话不改。人族的《拾穗书》还在唱\"拾穗者\"，妖族的《影翼谣》还在唱\"影子也是身\"——但他们开始在同一张桌上唱。"]},{"t":"ol","items":["制度层：禁令废了，户籍松了，名字能立了。制度是可以改的，改得慢，但能改。"]},{"t":"ol","items":["利益层：既得利益者没有被杀，只是失去了理由。韩朔解甲，沈阶交簿，蜃无涯放逐，听澜崩溃。没有清算的痛快，只有\"他们不再被需要\"的寂静。"]},{"t":"p","s":"防廉价大团圆的三道保险："},{"t":"p","s":"不肯看的村：档案公开后仍有村寨拒看。主角不破门，把一部《浊净同源考》留在村口书摊。多年后书翻毛了边，没人承认读过。——你无法证明一颗心变了，正如当年无法证明一颗心没变：证据主义者鸣可，最终学会了这一点。"},{"t":"p","s":"三史并立：终卷不合并史书。"},{"t":"p","s":"终句："},{"t":"p","s":"那年冬天，蜃市的孩子学会了一个新词。"},{"t":"p","s":"人族的写法是\"回还\"，妖族写作\"影归\"，灵族把它记成一记短音，落在琴上，是\"回来\"两个字的意思。"},{"t":"p","s":"三种写法，一个读音。"},{"t":"p","s":"唱证人把它记进愿约簿，价钱一栏空着。"},{"t":"p","s":"空着，是因为这句话不要钱。"},{"t":"p","s":"也是因为，它还没有被兑现。"},{"t":"p","s":"最后一句："},{"t":"p","s":"霜上的鹭飞走了。飞回来的，不是原来那只。"}]}]}]},{"num":"十二","title":"文学表达与创作规范","raw":"第十二篇｜文学表达与创作规范","zh":[{"title":"12. 小说写作手册","sec":[{"title":"12.1 叙事视角规范","blk":[{"t":"p","s":"七条铁律："},{"t":"ol","items":["一章一视角。禁一章内切三个视角；交汇章用\"唱证人视角\"（客观记录、只记言行、不记心理）。"]},{"t":"ol","items":["只写视角人物能感知的。他看不见的，不写；他不懂的，用他\"懂错的方式\"写。"]},{"t":"ol","items":["不写全知解释。世界观由人物\"用错的方式\"说出来——偏见的说法，就是最好的说明书。"]},{"t":"ol","items":["三线写同一事件，必须三版不同，且三版都不说谎。"]},{"t":"ol","items":["每章结尾留一件\"未解之物\"（一个动作、一句话、一件东西），不给解释。"]},{"t":"ol","items":["视角人物死亡或失忆，该章立即结束，下一章换线——不给\"死后视角\"。"]},{"t":"ol","items":["全书只允许三次\"第二人称\"（\"你\"）——三次都出现在愿约簿的唱词里，指\"那个不肯看的人\"。"]}]},{"title":"12.2 三位主角的语言风格","blk":[{"t":"table","head":["","鸣可","噬轲","巽宁"],"rows":[["句长","短，切分清楚，像验伤记录","极短，常省主语，句子像刀鞘","长，雅，句末常带评语"],["用词","术语精确（三焦、时辰、剂量）；口语带南地腔（\"莫\"\"咋\"）","少形容词；多动词；几乎不用敬语","用\"予\"自称；爱用琴曲作比；偶尔夹珂语音译"],["节奏","先结论，后依据","先沉默，后一句","先\"啧\"，后一句半"],["禁忌","不说\"我觉得\"，只说\"我验过\"","不说\"我怕\"，只说\"不去\"","不承认\"我在乎\""],["口头禅","\"证据呢？\"","\"……罢。\"","\"啧。\""],["情绪外化","骷髅手背轻叩三下","摩挲眉心纹","手按琴弦不弹"],["一句示范","\"这尸身上的拓痕是朱砂，不是血。朱砂渗进骨头，得三天。他死了不止三天。\"","\"桥上有人等他。……不去。……去罢。\"","\"啧。这一曲叫《碎珂》，弹的是一个人把话说到一半就死了。\""]]},{"t":"p","s":"三人对话的化学反应："},{"t":"p","s":"鸣可＋噬轲＝一个要证据，一个不肯说，互相逼；"},{"t":"p","s":"噬轲＋巽宁＝一个不说，一个能听见他没说的，互相怕；"},{"t":"p","s":"巽宁＋鸣可＝一个读心，一个只信物证，互相不服。"}]},{"title":"12.3 三族语言的使用规范","blk":[{"t":"p","s":"正文语言策略（中文写作的现实方案）："},{"t":"ol","items":["正文一律用通语（即现代汉语书面语）叙述，这是\"叙述者的语言\"，不带族属。"]},{"t":"ol","items":["对白按人物族属加\"腔\"，用词、语序、敬语三处体现，不造生词："]},{"t":"p","s":"净语腔：语序正常，多用\"当、须、宜、不宜\"，敬语按籍贯分档（对净户称\"先生\"，对附籍直呼其名）。"},{"t":"p","s":"幽语腔：倒装（\"桥上的风，冷\"），尾音加\"哩/罢/噻\"，敬语靠\"你影里……\"这类意象句。"},{"t":"p","s":"珂语腔：少用第一人称\"我\"，多用\"予/此身\"；句末常有\"慎言\"式的自我告诫；不用感叹号。"},{"t":"ol","items":["禁语的处理：出现禁语时，必须写\"说出后的反应\"，而不是解释词义。"]},{"t":"p","s":"例：某人说了\"蜉蝣\"→ 在场灵族抚琴一礼 → 琴弦响了一声 → 说话人脸红。"},{"t":"ol","items":["通语的特殊性：通语里没有骂人的字根。角色要骂人时必须\"切换回母语\"——写作时用一句母语原词（音译），后接一句通语解释他\"骂不出口\"。"]},{"t":"p","s":"例：\"他张嘴，想骂一句幽语的'窃火'，可那两个字在通语里没有。他只好说：'你不对。'——这句话轻得像道歉。\""},{"t":"ol","items":["三族三套纪年：跨族文书出现时，必须写出换算的麻烦（\"潮历二〇七年，即影历一六四年，珂历……\"），由抄书吏、牙人抱怨带出。"]}]},{"title":"12.4 文化、风俗与仪式描写","blk":[{"t":"p","s":"三条原则："},{"t":"ol","items":["不解释，只使用。风俗第一次出现时，人物按规矩做，读者自己懂；不懂也没关系，第二次出现时给一点解释。"]},{"t":"ol","items":["用\"做错\"来展示规矩。外人做错一次，规矩就清楚了——这比作者说明有效十倍。"]},{"t":"ol","items":["仪式必须有\"不神圣\"的细节。净血大祭上有人在算香烛钱；影翼大祭上孩子哭；琴夜有人偷喝酒。神圣感来自这些杂音。"]},{"t":"p","s":"可直接取用的六个风俗场面："},{"t":"table","head":["风俗","场面"],"rows":[["过桥不问名","桥上有人问\"客从何处来\"，被桥老瞪一眼；问的人立刻改口\"客\""],["息日市","一年五天，不查籍、不佩牌、不收税；桥上最挤也最安静"],["隔水聘","两岸成亲，隔水拜堂；孩子生在水边，两边都不上籍"],["影戏","妖族讲史靠看戏；唱到白芜临刑，台下有人小声说\"她没哭\""],["下元琴夜","灵族孩子第一次上琴，弹错不罚，弹对了要\"再弹一遍给祖先听\""],["唱价","唱证人高声记账，全桥都听见；赖账者从此无人替他唱价"]]}]},{"title":"12.5 物件、意象与象征系统","blk":[{"t":"table","head":["意象","物理属性","象征","首次出现","终局落点"],"rows":[["霜 / 鹭","霜薄、易散；鹭白、独脚立","三族短暂的共处；\"愧\"","卷一开篇","\"飞回来的不是原来那只\""],["桥","木石长桥，横跨海峡，桥禁","例外之地；唯一能\"不问名\"的地方","卷一","三史架挂在桥栏上"],["影","噬轲的影子比别人淡","被否认的一半；影行代价","卷一","残影守灵"],["空弦","琴上一记不弹的音位","被抹去的记录；也是唯一能补的","卷一末","巽宁以己音填之"],["三尺","落珂境下降的高度","灵族最大的恐惧，也是最大的谎","卷三","公开危机"],["簿 / 档","愿约簿（民间）／冰弦玉版（官方）","两种记忆；谁记谁有理","卷一","三史并立"],["拓片","半枚桑皮纸，朱砂，两道指痕","被撕开的名字；并排的两个人","卷一","鸣可把它贴在骨鸣堂墙上"],["名字","氏籍册上的一个位置","存在的凭证","卷一","\"我要一个能写进册的\""],["回来","通语新词，三种写法一个读音","重聚但不复原","卷六","终句"]]},{"t":"p","s":"意象使用纪律："},{"t":"p","s":"每个意象全书出现不少于三次，不多于十二次；出现时必是实物，不作比喻用。"},{"t":"p","s":"禁止\"意象解说\"（如\"那桥就像三族的关系\"）。让桥只是桥，读者自己会懂。"}]},{"title":"12.6 伏笔与悬念设计","blk":[{"t":"table","head":["类型","写法","例"],"rows":[["物件伏笔","第一次\"有用但不重要\"，第二次\"重要但不明\"，第三次\"明白了\"","拓片、佛珠、哑琴的琴音"],["语言伏笔","某人说了一句\"不合身份\"的话，当时不解释","素玦\"我不说，因为我曾说错\""],["行为伏笔","某人做了一个\"多余的动作\"","沈阶每月焚一页；璇玑每次都说\"再议\""],["结构伏笔","章首三史异文里的一句\"多出来的话\"","妖族版\"她临刑不哭\""]]},{"t":"p","s":"悬念的三条纪律："},{"t":"ol","items":["不在章末制造\"突然的危险\"，只在章末制造\"突然的明白\"或\"突然的空白\"。"]},{"t":"ol","items":["每个悬念必须有\"物证\"落在纸面上，读者可回查——不给纯心理悬念。"]},{"t":"ol","items":["大反转前必有三个\"明示\"埋在前文，且三个明示都是\"真话\"，只是读者会读错。"]}]},{"title":"12.7 叙事节奏与信息揭露原则","blk":[{"t":"p","s":"节奏公式：一章一场景，一章一次信息位移。"},{"t":"p","s":"每章只写一个连续场景（最长不超过一天）；一章之内必须有一次\"读者知道了新东西\"。"},{"t":"p","s":"每五章一个小高潮（一次对峙、一次揭示、一次失去）。"},{"t":"p","s":"每卷一个\"至暗时刻\"（主角失去最重要的东西：证据、名字、记忆）。"},{"t":"p","s":"信息揭露的四级阶梯："},{"t":"table","head":["级","读者知道","角色知道","效果"],"rows":[["一级","比角色多","少","悬念（\"别去！\"）"],["二级","与角色同","同","共感"],["三级","比角色少","多","反转（\"原来他早就知道\"）"],["四级","比\"叙述者\"多","少","回味（重读时发现）"]]},{"t":"p","s":"配比：全书以一级为主（约六成），三级用于六次大反转，四级用于章首三史异文。"},{"t":"p","s":"信息揭露的三条禁令："},{"t":"ol","items":["不许用\"多年以后他才明白\"这类全知回溯（除非是章首志体）。"]},{"t":"ol","items":["不许让角色\"恰好听见关键对话\"——要听见，必须有代价（影行、潜入、失去记忆）。"]},{"t":"ol","items":["不许在终章一次性解释所有谜团。终章只解释\"人为什么这么做\"，不解释\"机关怎么运作\"。"]}]},{"title":"12.8 禁止出现的设定矛盾","blk":[{"t":"p","s":"写作时逐条对照。凡违反，即为硬伤。"},{"t":"p","s":"力量体系："},{"t":"ol","items":["❌ 不得出现\"境界\"\"突破\"\"灵力暴涨\"等修仙等级表述。"]},{"t":"ol","items":["❌ 煞不可被\"净化\"\"消灭\"，只能被搬运（第三铁律）。"]},{"t":"ol","items":["❌ 迷梦蜘每用一次，鸣可必须遗忘一段自身记忆，不可豁免、不可恢复。"]},{"t":"ol","items":["❌ 影行一日最多两次；第三次必留残影；长期影行必致\"被遗忘\"。"]},{"t":"ol","items":["❌ 琴音读弦读不出\"说谎而自信者\"；不得让巽宁靠读心解决审讯。"]},{"t":"ol","items":["❌ 本器（彩凤鸣岐）毁则巽宁灵散；她不可\"脱离琴身\"行动。"]},{"t":"ol","items":["❌ 开佛珠必须以自身记忆置换，不可\"免费获取情报\"。"]},{"t":"ol","items":["❌ 鲲鹏不得现身、不得说话、不得成为解谜神迹。"]},{"t":"p","s":"历史与证物：9\\. ❌ 冤案不得有\"主谋\"（合谋无主是核心设定）。10\\. ❌ 沈聿与白芜不得\"真的窃气\"——他们犯的罪是相爱与私改气序半刻。11\\. ❌ 聆霜尸身不得被打捞到（尸身不获是硬设定）。12\\. ❌ 上呈三老的抄本必须是伪本；真本必须沉海（调包反转不可撤销）。13\\. ❌ 三份史书终卷不得合并、不得裁定谁对。14\\. ❌ 涿光境密档必须\"演奏\"才能读，不可\"翻看\"。15\\. ❌ 落珂境不得写成\"悬浮仙境\"——圣地即岛下（已定案）。"},{"t":"p","s":"地理与历法：16\\. ❌ \"洛珂境\"写法废止，统一\"落珂境\"。17\\. ❌ \"东阳洲\"写法废止，统一\"东阴洲\"。18\\. ❌ 十三岛体数量不得改动；中央主岛一体四洲，不需航海。19\\. ❌ 航行时间不得随意压缩（消息传播必须滞后，是三线结构的物质基础）。20\\. ❌ 潮汐历一年十二潮、每潮三十日、息日五天，不得改；三族三套纪年换算关系固定（影历＝潮历－43）。"},{"t":"p","s":"身份与制度：21\\. ❌ 混血者不得\"入籍承产\"（直到终卷改革）；改革也不得\"全好\"。22\\. ❌ 灵族不得大量生育（生育极低是净血制度的成因）。23\\. ❌ 人族不得直接驭灵（只能借器物与阵法）。24\\. ❌ 通语里不得出现骂人字根。25\\. ❌ 妖族氏籍册在终卷前不得有\"混血\"写法。"},{"t":"p","s":"人物：26\\. ❌ 无相不得杀人（他废阵）。27\\. ❌ 无相不得正面出场于终章（只留木牌与字迹）。28\\. ❌ 三主角不得成为恋人（三人关系是\"共立一俗\"，不是爱情）。29\\. ❌ 反派不得自认恶；独处时不得想\"我是坏人\"。30\\. ❌ 巽宁在终卷前不得自称\"巽宁\"（她一直自称\"予\"，用逝者之名行世）。"}]}]},{"title":"命名规则","sec":[{"title":"","blk":[{"t":"table","head":["族","命名法","例"],"rows":[["人族·净籍","单姓＋单/双名，字义偏\"礼、器、光\"","沈聿、裴照、宋判、章百工"],["人族·南地/附籍","双字名，带草木虫鱼","鸣可、老墨、半橹"],["妖族","单名＋氏；名多带\"影、煞、幽、雪\"","白芜、噬轲、蜃无涯、老疤、影婆"],["灵族","双字，偏\"玉、音、水\"；无姓","聆霜、璇玑、珩鸣、素玦、听澜"],["佛门","\"闻\"字辈","闻钟、闻磬（无相）、闻铃"],["蜃市","绰号先行","何三筏、铁算盘、灰嫂、哑琴"]]}]}]}]}],"islands":[{"id":"chengming","name":"澄鸣洲","short":"文教","owner":"人族","pos":"中央主岛北部","x":596,"y":330,"r":92,"land":"高地丘陵，山地林地","goods":"桑皮纸 · 松烟墨 · 刻书梨木 · 云雾茶","line":"全洲以鸣钟作息，钟一响，满山翻书声。","note":"书院林立，学官治国。《澄鸣实录》藏于此，也毁于此。"},{"id":"ruohuai","name":"若淮洲","short":"缓冲","owner":"混居缓冲","pos":"中央主岛西部","x":470,"y":415,"r":78,"land":"平缓丘陵＋淮水三角洲","goods":"淮稻 · 苇编 · 海盐 · 蚌珠","line":"水清蚌肥——因为这块地从不抽灵。","note":"无主之洲，村社自洽。人妖通婚者多隐居于此：违法，所以沉默。"},{"id":"xihe","name":"羲和洲","short":"帝都","owner":"人族","pos":"中央主岛东部","x":706,"y":420,"r":88,"land":"开阔河谷平原","goods":"五谷主仓 · 官窑“净白”瓷 · 驿马","line":"城郭九重，檐角悬日纹，越往里越白。","note":"帝制＋净籍制。灵耗巨大，是“过度抽灵生煞”的反面教材。"},{"id":"fusang","name":"扶桑洲","short":"商港","owner":"人族","pos":"中央主岛南部","x":600,"y":520,"r":86,"land":"湿热河谷密林","goods":"神木脂（船漆）· 香料 · 硬木 · 蔗糖","line":"船坞连着林子，砍树的人兼造桨。","note":"港督＋十三行商。最活络的钱庄业，汇兑通达六洲。"},{"id":"fengyang","name":"封阳洲","short":"关隘","owner":"人族","pos":"西北独立岛","x":196,"y":208,"r":66,"land":"岩岸高台、石堡群","goods":"铁煤 · 青石 · 耐寒矮马 · 风干肉","line":"风大得能把话吹散，故封阳人说话极短。","note":"军镇，戍卒世兵。《封阳盟约》在此签订；石港为军港，混血之船禁入。"},{"id":"hengyun","name":"珩蕴洲","short":"匠作","owner":"人族","pos":"西南独立岛","x":178,"y":520,"r":70,"land":"迎风山城，多云多雨","goods":"铜锡矿 · 灵砂 · 砂器 · 引灵器物","line":"家家有炉，孩子在炉边学认矿不学认字。","note":"匠籍世袭。彩凤鸣岐琴出自此洲古匠之手。鸣可的纳维族也在此。"},{"id":"liangling","name":"凉凌洲","short":"幽都","owner":"妖族","pos":"极南大陆","x":598,"y":726,"r":96,"land":"峡湾冰原，高地覆霜","goods":"寒煞冰晶 · 霜皮 · 雪参 · 幽冥矿","line":"极夜里，地底有城，城里有星。","note":"妖族核心。幽都建于地底灵穴，亚寒带长夜承载“城无日而明”。"},{"id":"chihua","name":"赤华境","short":"星象","owner":"灵族","pos":"中南弧岛","x":606,"y":636,"r":62,"land":"红土台地，偏干","goods":"赤陶 · 丹砂 · 火浣草（耐燃布）","line":"红土晒得发白，观星台比屋高。","note":"星象祭仪所在。北侧洋流交汇，常年海雾与突发气旋——古航海禁地。"},{"id":"luoke","name":"落珂境","short":"之源","owner":"灵族","pos":"中东小岛","x":812,"y":372,"r":50,"land":"丘陵环礁湾","goods":"无大产——产“补给与消息”","line":"港税、引水人；全世界的船都在这儿换水。","note":"凡人只见外港，守脉者知岛心。鲲鹏之源即在岛下；灵脉衰则岛沉，衰潮时全岛下降三尺。"},{"id":"zhuoguang","name":"涿光境","short":"守档","owner":"灵族","pos":"东北连体岛北段","x":926,"y":208,"r":60,"land":"峡谷灯楼","goods":"光晶（存光矿石，档窖照明）","line":"峡里全是灯，灯不为照路，为照档。","note":"守档一脉所在，三份密档之一藏此。与东阴洲同岛隔谷相望。"},{"id":"dongyin","name":"东阴洲","short":"妖域","owner":"妖族","pos":"东北连体岛南段","x":946,"y":300,"r":58,"land":"平原河谷，与涿光隔谷","goods":"煞稻 · 影丝（幽蚕丝）· 幽冥矿","line":"日头照不到的谷子，照样灌浆。","note":"妖族东北支十七氏聚居。与灵族隔谷相望，摩擦不断的第一线。"},{"id":"qianshi","name":"乾时洲","short":"阵法","owner":"人族","pos":"东南连体岛北段","x":1000,"y":508,"r":60,"land":"星位阵城、丘陵","goods":"测灵仪 · 阵盘 · 星图","line":"街巷按星位铺，走错巷等于走错卦。","note":"阵师行会。封灵阵与测灵仪的技术源头——偏见从手续变成生意的地方。"},{"id":"bihai","name":"碧海洲","short":"蜃市","owner":"共管","pos":"东南滨海低地","x":1046,"y":606,"r":56,"land":"浅滩红树林","goods":"盐 · 鱼 · 红树林蜜 · 蜃市百业","line":"屋随潮涨潮落，桥不动，屋动。","note":"蜃市所在：三族唯一常年开放之地。“过桥不问名”——桥上不问族籍名讳，只称“客”。"}],"races":{"human":{"name":"人族","en":"Human","color":"#C9A961","creed":"以“洁净／污秽”划分","prefix":"净","scent":"净籍 · 宗族 · 史书","items":[["起源与生理","灵力中等，不能直接驭灵，靠阵法与器物引灵；寿数约七十，血可被抽以续灵脉（净血大祭的“血源”）"],["社会结构","帝制＋净籍制，户分“净户”与“附籍”；六大派系各据一洲（帝都／书院／行会／匠门／军镇／商港）"],["阶层","士农工商，籍贯定终身。蛊医、混血、无籍者在下；纳维族等南方支族被视为“半秽”"],["货币","蜃钱本位，交子通行；乾时以“阵契”结算，封阳用军票"],["衣食住行","尚白（“净”色）；九重城郭，檐角悬日纹；官道驿传、雕版印刷"],["信仰","羲和日神＋祖先；《拾穗书》——鲲鹏以羽翼遮天漏，灵力是它的羽粉，“本分给人族一半”"],["语言","净语，敬语按籍贯分档；“妖”字从虫旁——偏见写进了字形"],["文化","修史传统极盛：刻书、藏书、毁书。禁毁书目里有《浊净同源考》"],["偏见形态","视幽煞为“污秽”，视妖族为“带菌者”。歧视被制度化：佩牌令、验血、入市作保"]]},"demon":{"name":"妖族","en":"Demon","color":"#7E9E8C","creed":"以“影／名”划分","prefix":"煞","scent":"氏籍 · 影 · 血脉","items":[["起源与生理","灵力稀薄处生机“衰减变质”为幽煞，煞地生妖族。体质近煞，夜视、耐寒、可淬体；白天久晒则伤"],["社会结构","十七氏，氏老会共议。幽都在凉凌洲地底；北境雪罴氏等部落不认幽都"],["阶层","按煞脉深浅分氏；混血者不入氏籍——“查无此籍”是噬轲一生的伤口"],["货币","煞珠（幽煞凝晶，妖族视其为“影子的骨头”）；北境以物易物"],["衣食住行","影纹衣（幽蚕“影丝”）；煞稻耐寒；地底城无日而明，煞植荧荧如星"],["信仰","万物有灵，影翼大祭。《影翼谣》——鲲鹏敛翼垂影，影中生万灵：“影子也是身”"],["语言","幽语，倒装；北腔多喉音。禁语里“潮汐周期”被抹成一记空弦"],["文化","影戏、口弦、煞植医道（人族不可替代的医术）"],["偏见形态","在人族眼里是“不净”，在灵族眼里是“不祥”。而他们自己也在排斥混血——歧视链上人人有位置"]]},"spirit":{"name":"灵族","en":"Spirit","color":"#8FA8C8","creed":"以“古／今”划分","prefix":"珂","scent":"琴籍 · 谱系 · 档","items":[["起源与生理","居灵力最浓处，寿数极长（聆霜案发时二百余）；生育率极低，靠“净血大祭”续灵脉。器灵族附逝者之身而活"],["社会结构","三老共议＋守脉者世职；守档一脉掌涿光境密档。147 年后立“只守档，不言档”之规"],["阶层","守脉者 ＞ 琴史 ＞ 凡灵；器灵受礼遇，也受监视"],["货币","无市，以愿易愿——天下愿约的源头；对外以“琴”与“净血”换粮铁"],["衣食住行","羽白裳；晨露灵酿；居琴阁。落珂境浮于洋心，凡图不载"],["信仰","鲲鹏本尊——全世界唯一“见过”鹏影的地方，因为岛影即鹏影"],["语言","珂语。最古一支“落珂音”可直接“演奏”潮汐。忌语：“蜉蝣”（对凡族的蔑称）"],["文化","净血大祭之源、下元琴夜之源；琴曲即史，《洛珂引》是琴曲经"],["偏见形态","以“古”自居，视短寿者为“朝生暮死，不知潮汐”。他们把真相沉进档案，是为了保住道统"]]}},"timeline":[{"ym":"一〇七 · 元月","title":"灵脉始衰","text":"落珂境灵脉水位三日降一寸。守脉者上报，三老议定封锁消息：“恐乱人心”。"},{"ym":"二月","title":"边田生煞","text":"边境农田一夜之间煞化。三族互指，各自记下对自己有利的说法。"},{"ym":"四月","title":"净血大祭","text":"三族共祭。沈聿私改“气序”半刻，为白芜多争半刻并肩的时间；白芜替他挡了一次盘查。"},{"ym":"五月","title":"翻潮","text":"中洲横流倒流半日，水色靛转墨。老水手见墨落帆——衰潮前兆，无人敢言。"},{"ym":"六月","title":"下狱","text":"“窃气叛仪”罪名成立。聆霜请调潮汐档案自证“此乃周期”，被三老驳回：档案不可示人。"},{"ym":"七月","title":"三族会审","text":"审了十九天。三份供词各按本族礼法书写，彼此矛盾。审出的不是真相，是三族各自“需要一个罪人”。"},{"ym":"八月 · 敛月十九","title":"处决","text":"二人同日刑于落珂境阶前，临刑未辩一句。愿约簿上这一天是空白——唱证人拒绝唱这一天的价，是百年间唯一一次罢工。"},{"ym":"同夜","title":"聆霜自沉","text":"解去配重，尸身不获。她带走的不是绝望，是调了包的伪本与真本的秘密。"},{"ym":"九月","title":"阅档无人公布","text":"三族上层阅看“档案”，无人公布。三份会议记录的附录里，是彼此默许的三句话。"},{"ym":"十月","title":"《封阳盟约》","text":"划界、限市、通婚之禁。原文只一句，却最长寿：“异族为婚者，以叛仪论。”"},{"ym":"十二月","title":"全面开战","text":"热战十年（107—118），烧田、劫粮、蜃市闭市三年。死人最多，记忆最浅。"}],"century":[{"y":"118","t":"碧海焚市","d":"热战末期蜃市大火，唱楼半毁，愿约簿分簿开始流散。官方史书对火灾起因有三种记载。"},{"y":"147","t":"销名之议","d":"灵族追销聆霜之名，守档一脉改组，立“只守档，不言档”之规。灵族从此不再有“言档者”。"},{"y":"176","t":"佩牌令","d":"妖族入城须佩木牌，牌上刻氏名与“限行”。偏见从看法变成手续。"},{"y":"198","t":"测灵仪之禁","d":"乾时行会以“测煞”为名设卡收费，混血者过卡须“验血”。偏见从手续变成生意。"}],"chars":[{"id":"mingke","name":"鸣可","en":"MING KE","race":"人族","job":"蛊师（游方医）","age":"十七","line":"毒走三焦，两个时辰。你骗我可以，别骗我的虫。","lie":"只要证据足够，世界就会讲道理。","wound":"九岁断臂之夜，她指认凶手，无人信一个蛊医孤女的话——证据齐全，人心不信。","want":"查清断臂真相，找回家传被夺的半枚拓片。","need":"明白有些偏见不靠证据驳倒，靠活出反例；为“拿不出证据的人”作证。","arc":"从“证据主义者”，到“在证据缺席处仍选择相信人”。","secret":"她九岁前的记忆已经稀薄——她以为是断臂之痛，其实是迷梦蜘在吃她。","link":"沈聿的旁支后裔。断臂之夜被夺的“半枚拓片”，正是净血名录散佚的拓片之一——她查的私仇，通向公案。","end":"留蜃市开蛊医馆“骨鸣堂”，收三族学徒；开始“写自己的档”。"},{"id":"shike","name":"噬轲","en":"SHI KE","race":"妖族","job":"刺客（师承无相）","age":"十九","line":"不去。……怕。怕也得去。","lie":"出身即原罪。唯有变强，强到没人敢提我的血，我才算活人。","wound":"幽都氏老会上，有人当众念他“查无此籍”；师父无相是唯一叫他名字的人。","want":"查无相失踪之谜，顺藤摸到自己的身世。","need":"承认血脉的两半都是自己；明白以刺杀洗雪“刺客之后”，只是把偏见倒过来执行。","arc":"暗线险堕负向（复仇几乎成功时停手），终归正向——“我不是鱼肉”的下半句是“也不做刀”。","secret":"他早已发现自己“被人记不住脸”，以为是长相，其实是影行反噬——他怕的不是死，是死后没人记得他来过。","link":"鬼豹氏，白芜的玄孙。沈聿×白芜之孙为混血，不入氏籍，后人隐于幽都最深处。他的身体本身就是“两边都不要”的证词。","end":"散尽刺术，立混血互助会“过桥人”；把一缕残影留在落珂境阶前陪两位祖先。"},{"id":"xunning","name":"巽宁","en":"XUN NING","race":"灵族","job":"琴师（器灵）","age":"琴龄八十七","line":"啧。予不救俗人——不过你这份伤，恰好值得予费半根弦。","lie":"我只是替身。替别人活的人生，我自己不算数。","wound":"第一次“代替”一位逝者活下去时，她发现自己开始想替他哭——器灵不该有自己的情绪，她把这当作故障。","want":"替逝者解开心结：把涿光境密档带出三岛（逝者的遗憾）。","need":"承认八十七年里她已然长出了一个“自己”；替身也是人生。","arc":"平坦弧带觉醒：她改变了世界（让守档一脉重新“言档”），也终于认领了自己。","secret":"本器彩凤鸣岐曾在珩蕴匠门被“改过一次弦”——改弦者是谁、为什么改，是她八十七年里唯一不敢查的事。","link":"所附之身是灵族守档人一脉末裔（聆霜玄孙女），心口旧痕即逝者未解的心结；结不解，痕不消。","end":"入缄廊做“活的档”——守档一脉重立后第一任“言档者”，心口旧痕在解结之日淡成一枚月牙。"}],"evidence":[{"n":"壹","name":"三份密档","kind":"冰弦玉版 · 三份抄本","desc":"当年会审的全部记录：供词的原始版本、三老议事的附录、以及“潮汐周期”的那一段。","where":"三处各一：涿光境档窖、羲和秘阁、幽都氏老会。三族各执一份，各自“保护”成各自的把柄。","key":"三份合读，才拼得出“无人主谋”的全貌——单看任何一份，都能证明别人有罪。"},{"n":"贰","name":"净血名录拓片","kind":"朱砂拓片 · 半枚","desc":"净血大祭的献血者名录，拓自祭坛侧碑。半枚在纳维族（鸣可家），半枚随尸身出现在二〇七年的蜃市。","where":"鸣可家传残片 ＋ 一具“煞死”的尸体。","key":"两半合上，会露出一个被抹掉的名字——那个人不该出现在献血的名单里。"},{"n":"叁","name":"《浊净同源考》","kind":"禁书 · 澄鸣禁毁书目","desc":"三个论点：煞非邪，乃灵力之“让位”；净非本，乃后起之名；混血非污，乃两源未分时的常态。","where":"澄鸣洲禁书库（原本已毁）、洛华寺抄本（无相抄录，因此被逐）。","key":"它把“净”字从族名还原成一个政治动作——立国者先划出“不净”，才有“净”。"},{"n":"肆","name":"愿约簿","kind":"口头之诺 · 唱证人记账","desc":"蜃市的信用本身：谁赊了谁什么，由唱证人当众唱价。分簿在 118 年焚市后流散商人之手。","where":"唱证人罗半帆持有主簿碎片；散页在十二家船帮与牙人手中。","key":"一〇七年八月十九那一页是空白——唱证人拒绝唱这一天的价。空白本身就是证词。"},{"n":"伍","name":"冰弦玉版","kind":"灵族档体 · 以琴音存字","desc":"灵族的档案载体：玉版为骨，冰弦为纹，需以珂语“落珂音”奏出才能读。少一弦，即少一段史。","where":"涿光境档窖深处；读档需琴、需谱、需“言档者”。","key":"聆霜在末页留了一记空弦——那不是缺漏，是她标出的“被删处”。"},{"n":"陆","name":"三颗佛珠","kind":"无相遗物 · 记忆载体","desc":"无相以佛珠存记忆：一颗存人，一颗存名，一颗存他自己删掉的那段。第三颗在噬轲掌心裂开一线。","where":"噬轲处（第三颗）；另两颗散于蜃市与洛华寺。","key":"三珠归位，才拼出无相为什么“废阵不杀人”——他杀的从来不是人，是封灵阵。"},{"n":"柒","name":"调包伪本","kind":"聆霜手书 · 伪","desc":"当年上呈三老“阅看”的抄本是伪本：关键段落被改得合乎三族体面。真本随她沉入碧海。","where":"伪本在三族档案里（被当作真本供奉百年）。真本的线索在冰弦玉版的空弦与她的末页琴音里。","key":"她用谎言保住了真相——与“用真相杀人”的冤案互为镜像。全书最大反转。"}],"currents":[{"name":"北玄环流","d":"M 120,236 C 300,150 700,150 960,196","label":"北部顺时针 · 利西→东北"},{"name":"中洲横流","d":"M 330,470 C 560,436 800,452 1010,486","label":"东西向 · 岛际主航道"},{"name":"南寒回流","d":"M 660,740 C 720,650 760,600 690,566","label":"南部逆时针寒流 · 多雾多风暴"}],"routes":[["fengyang","ruohuai","720 里","顺 5 天 / 逆 9 天"],["fengyang","hengyun","960 里","8—11 天"],["hengyun","ruohuai","800 里","7—10 天"],["hengyun","chihua","1100 里","9—13 天"],["fusang","chihua","360 里","顺风 3 天"],["chihua","liangling","480 里","4—6 天"],["liangling","luoke","1300 里","10—14 天"],["xihe","luoke","420 里","3—5 天"],["luoke","dongyin","540 里","4—6 天"],["xihe","zhuoguang","900 里","顺 7 天 / 逆 12 天"],["dongyin","qianshi","840 里","7—9 天"],["qianshi","luoke","700 里","6—8 天"],["bihai","liangling","1400 里","11—15 天"]]};
